//! Card data + pile management.
//!
//! Ports `sts2-rl-agent@01c094d:sts2_env/cards/card.py` (Card data shape)
//! and `sts2_env/core/combat.py` (move/draw/discard primitives — note that
//! the originally-cited `core/commands/pile.py` does not exist in the pinned
//! Python sim; the canonical pile commands live on `CombatState` in
//! `combat.py:1102-1141` for `_draw_cards_for_creature` / `_shuffle_if_needed`
//! and `combat.py:1682-1702` for `move_card_to_creature_hand` / `move_card_to_creature_discard`).
//!
//! Bead P1-2 (sts2-rs-8l3) lands the higher-level commands: `draw`,
//! `discard`, `shuffle`, `discard_pile_into_draw_pile`, `try_add_to_hand`.

use crate::dotnet_rng::Rng as CombatRng;
use crate::{CardUid, PlayerCombatState};
use smallvec::SmallVec;

// Bead sts2-rs-ov4 (P6-1): the ~580-variant `CardId` enum was bulk-scraped
// from `sts2-rl-agent@01c094d:sts2_env/core/enums.py::CardId`; it is now
// hand-maintained against the v0.107.1 C# decompilation (the scraper was
// retired — see the header of `card_ids_generated.rs`). Variants live in
// their own module to keep this file readable; we re-export at module scope
// so the canonical path stays `sts2_core::cards::CardId`.
#[path = "card_ids_generated.rs"]
mod card_ids_generated;
pub use card_ids_generated::CardId;

// Bead sts2-rs-pmf (P6-1b): CardId -> character mapping, generated by
// `scripts/scrape_card_specs.py` from per-character Python source files.
// Consumed by the coverage-census test.
#[path = "card_character_map_generated.rs"]
mod card_character_map_generated;
pub use card_character_map_generated::character_of;

/// The POD stat a run-persistent scaling card grows mid-combat.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RunScaledStat {
    Damage,
    Block,
}

impl RunScaledStat {
    #[must_use]
    pub const fn get(self, c: &Card) -> i32 {
        match self {
            Self::Damage => c.base_damage,
            Self::Block => c.base_block,
        }
    }

    pub fn get_mut(self, c: &mut Card) -> &mut i32 {
        match self {
            Self::Damage => &mut c.base_damage,
            Self::Block => &mut c.base_block,
        }
    }
}

/// Cards whose `OnPlay` also buffs their run-deck copy (C#
/// `DeckVersion.BuffFromPlay`), so the growth outlasts the combat. In both
/// pinned builds the decomp has exactly two: The Scythe (`TheScythe.cs:73`,
/// `CurrentDamage`) and Genetic Algorithm (`GeneticAlgorithm.cs:69`,
/// `CurrentBlock`). Read by the `exit_combat` fold-back (GH #838) and the
/// search's persistent-gain term (GH #839).
#[must_use]
pub const fn run_persistent_scaled_stat(id: CardId) -> Option<RunScaledStat> {
    match id {
        CardId::TheScythe => Some(RunScaledStat::Damage),
        CardId::GeneticAlgorithm => Some(RunScaledStat::Block),
        _ => None,
    }
}

// Bead sts2-rs-ov4 (P6-1): keys for per-card persistent combat-state
// (`Card::combat_vars`). Mirrors string keys used by Python's
// `CardInstance.combat_vars: dict[str, int]` in `sts2_env/cards/base.py`.
// Concrete keys are added as the corresponding cards are ported in
// downstream beads (Rampage, Claw, Genetic Algorithm, Ritual Dagger, ...).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum VarKey {
    /// Stacked extra damage for Rampage. Python: `combat_vars["damage"]`.
    RampageDamage,
    /// Claw's running buff to all subsequent Claw plays. Python:
    /// `combat_vars["claw"]`.
    ClawBuff,
    /// Genetic Algorithm permanent block bonus. Python:
    /// `combat_vars["block"]`.
    GeneticAlgorithmBlock,
    /// Ritual Dagger / Rite of the Quill scaling damage.
    RitualDaggerDamage,
    /// Per-card "free this turn" flag (non-zero = treat play-time cost as
    /// 0). Set by `InfernalBlade` when it spawns a random Attack into hand
    /// (bead `sts2-rs-c68o`); cleared at end-of-turn cleanup for every
    /// pile. Mirrors C# `CardModel.SetToFreeThisTurn()` at
    /// `sts2-wiki/decompiled/v0.103.2/MegaCrit.Sts2.Core.Models.Cards/
    /// InfernalBlade.cs:27`. The Python pin's simplified `infernal_blade`
    /// inlines a 0-cost Strike instead of toggling a flag; we follow the
    /// C# canonical behaviour (random Attack + free-this-turn).
    FreeThisTurn,
    /// Per-card "ethereal this combat" flag (non-zero = treat the card
    /// as Ethereal at end-of-turn cleanup even if its `CardId` is not in
    /// the static ethereal registry). Set by `MusicBox` when it spawns
    /// an Ethereal clone of a played Attack into hand (bead
    /// `sts2-rs-ad53n`); honored by the end-of-turn ethereal sweep in
    /// `combat_loop::end_player_turn_phase_two`. Mirrors C#
    /// `CardModel.IsEthereal` per-instance bit (Python pin inlines a
    /// `_ethereal: bool` attribute on `CardInstance`).
    EtherealThisCombat,
    /// Per-card "star cost is 0 for the rest of combat" flag (non-zero =
    /// treat the card's star cost as 0 in the legal-action gate and on the
    /// play-time star spend). Set by `TouchOfInsanity` (and its
    /// `MakeFreeInHand` choice resolver), which makes one cost-bearing hand
    /// card free for the combat. Mirrors the star half of C#
    /// `CardModel.SetToFreeThisCombat()` → `SetStarCostThisCombat(0)`
    /// (`CardModel.cs:984`); the energy half is the directly-stamped
    /// `cost = 0`. Combat-lasting (lives on `combat_vars`, reset at
    /// end-of-combat) — unlike [`VarKey::FreeThisTurn`], which is cleared at
    /// end-of-turn. Bead `sts2-rs-starcost-free-combat`.
    StarCostFreeThisCombat,
    /// MakeItSo's `effect_vars["cards"]` interval — every N Skills
    /// played this turn, the watched MakeItSo card returns to hand.
    /// Mirrors Python `sts2-rl-agent@01c094d:sts2_env/cards/regent.py:L790`.
    /// Bead `sts2-rs-j9x8`. Default value (`3`) is set by the MakeItSo
    /// factory; the late-effect reads it via `combat_var(MakeItSoInterval)`
    /// and falls back to `3` when the slot is unset.
    MakeItSoInterval,
    /// Stomp's per-turn energy-cost reduction (running total of `-1`s
    /// applied this turn). Stomp costs 1 less for each Attack the owner
    /// plays this turn (C# `Stomp.BeforeCardPlayed` →
    /// `EnergyCost.AddThisTurn(-1)`); this slot records how much has been
    /// shaved off `Card::cost` so far so the player-turn-start reset can
    /// add it back. Mirrors C#'s `AddThisTurn` auto-reset semantics.
    /// Bead `sts2-rs-stomp`.
    StompCostReductionThisTurn,
    /// Pinpoint's per-turn energy-cost reduction (running total of `-1`s
    /// applied this turn). Pinpoint costs 1 less for each Skill the owner
    /// plays this turn (C# `Pinpoint.AfterCardPlayed` →
    /// `EnergyCost.AddThisTurn(-1)`, floored at 0); this slot banks how much
    /// has been shaved off `Card::cost` so the player-turn-start reset can add
    /// it back. Same shape as `StompCostReductionThisTurn` (Skill-triggered
    /// instead of Attack-triggered). Silent's Pinpoint.
    PinpointCostReductionThisTurn,
    /// Snecko Oil's per-card cost delta for this turn (running total of
    /// `roll - prior_cost`). Snecko Oil randomizes each non-X-cost card in
    /// hand to a cost in `0..=3` via C# `EnergyCost.SetThisTurnOrUntilPlayed`,
    /// which auto-reverts at the owner's next turn start. This slot banks
    /// how much the absolute set shifted `Card::cost` so
    /// [`crate::CombatState::restore_snecko_costs_for_turn_start`] can undo
    /// it (mirrors the `StompCostReductionThisTurn` reset shape). Without
    /// the revert the randomized cost persisted across the turn boundary
    /// (coverage sweep: `potion:SNECKO_OIL` player.energy C#=2 rust=1 after
    /// a STRIKE whose cost should have reverted to its base). Bead
    /// `sts2-rs-2e9q2` follow-up.
    SneckoCostDeltaThisTurn,
    /// Records the player TURN number (`CombatState::turn_number`, C#
    /// `PlayerCombatState.TurnNumber`) on which a self-returning Attack
    /// (Bolas / ThrummingHatchet) was last played — the name predates the
    /// switch from the round. Their C# `BeforeHandDraw` hook returns the card
    /// to hand at the next turn start iff it was played on the previous
    /// player turn (`HappenedLastPlayerTurn`: `playedTurn == TurnNumber - 1`,
    /// `CombatHistoryEntry.cs:99-108`; an extra turn bumps the turn number,
    /// not the round). The turn-start sweep in
    /// `combat_loop::start_player_turn` reads this slot; `0` (unset) means
    /// "never played", so it never matches. Bead `sts2-rs-219ds`.
    ReturnIfPlayedRound,
    /// Marker (non-zero = flag set) indicating this card was downgraded by
    /// the DAMPEN power. Set when Dampen is applied via `MagiKnight`'s
    /// `DampenPower.AfterApplied` to track which upgraded cards to re-upgrade
    /// when Dampen is removed (mirror C# `DampenPower.cs:downgradedCardsToOldUpgradeLevels`).
    /// Bead `sts2-rs-mw4fy`.
    DampenDowngradedMarker,
    /// Marker (non-zero = flag set): this card is a DUPE — C#
    /// `CardModel.IsDupe`, set on `CreateDupe()` products (HistoryCourse's
    /// transient replay). Three behavioral consequences, all C#-anchored:
    /// `GetResultPileType()` returns `PileType.None` for dupes
    /// (`CardModel.cs:1608-1616`) so a played dupe is REMOVED from combat
    /// instead of discarded; HistoryCourse's `CardPlaysFinished` scan
    /// filters `!IsDupe` so a dupe can't seed next round's replay; and —
    /// crucially — `AbstractModel.MutableClone()` is `MemberwiseClone()`
    /// (`AbstractModel.cs:104`), so a card the DUPE's own OnPlay clones
    /// (Anger's self-copy) INHERITS the flag: that poisoned copy, later
    /// hand-played, also vanishes instead of discarding (sweep seed 5192:
    /// discard cs=13 rs=14). Rust card clones copy `combat_vars`, so the
    /// propagation is automatic. Bead `sts2-rs-ummci` follow-up.
    IsDupe,
    /// Marker (non-zero = flag set): this card was GENERATED mid-combat
    /// (spawned status/token, Stoke/Discovery/Calamity generation, clone)
    /// rather than coming from the run deck — the Rust analogue of C#'s
    /// `CardModel.DeckVersion == null`. Consumed by deck-scoped pickers
    /// (ThievingHopper's steal filters `c.DeckVersion != null`,
    /// `ThievingHopper.cs:203` — sweep seeds 4043/5342: generated cards
    /// inflated the steal pool's `NextItem` index). Stamped at the spawn
    /// chokepoints (`spawn_card_into_pile`,
    /// `spawn_card_into_draw_pile_random_position`,
    /// `create_character_cards_into_arena`). Bead `sts2-rs-a4096`.
    ///
    /// The value says how: [`GENERATED_FRESH`] for a new card,
    /// [`GENERATED_AS_CLONE`] for a [`Card::create_clone`] copy (C#
    /// `IsClone`). Readers that only need "not from the deck" test `!= 0`.
    GeneratedInCombat,
    /// Marker (non-zero = flag set): this card's `cost` currently holds an
    /// ABSOLUTE local cost modifier (C# `LocalCostModifier.Absolute`) —
    /// Confused's per-draw `SetThisCombat(roll)` or SneckoOil's
    /// `SetThisTurnOrUntilPlayed(roll)` — rather than its (possibly
    /// delta-shifted) base. `Card::upgrade` consults it to reproduce C#
    /// `CardEnergyCost.UpgradeBy`'s clamp (`CardEnergyCost.cs:189-198`):
    /// when an in-combat upgrade LOWERS the base cost, every absolute
    /// modifier above the new base is clamped down to it — so a
    /// BoneTea/BlessingOfTheForge upgrade of a Confused/Snecko-rolled
    /// MIND_BLAST / TANK / BODY_SLAM lands at the new base 0, not
    /// `roll + delta` (sweep seeds 1170/4720/4330). Bead `sts2-rs-i77h0`.
    CostAbsolutelySet,
    /// Thrash's accumulated decimal-fold REMAINDER, numerator. C#
    /// `Thrash.Damage.BaseValue` is a `decimal` that grows by the un-floored
    /// `ModifyDamage` of each exhausted attack (`Thrash.cs:67`). Rust keeps the
    /// integer part in `Card::base_damage` and the leftover fraction here as a
    /// reduced rational `ThrashFoldRemNum / ThrashFoldRemDen` in `[0, 1)`, so a
    /// later play deals `(base_damage + rem) × modifiers` with a single floor —
    /// matching C#'s `(int)` truncation only at HP application. Den 0 ⇒ treat as
    /// 1. Bead `sts2-rs-thrash-decimal`.
    ThrashFoldRemNum,
    /// Thrash's accumulated decimal-fold REMAINDER, denominator (see
    /// [`VarKey::ThrashFoldRemNum`]). Stored 0 when unset ⇒ treated as 1.
    ThrashFoldRemDen,
    /// Per-card "free until played" energy-cost marker (non-zero = treat
    /// play-time ENERGY cost as 0, fed as base into the modify_card_cost
    /// listener walk exactly like [`VarKey::FreeThisTurn`]). Unlike
    /// `FreeThisTurn` it has a CROSS-TURN lifetime: it survives the
    /// end-of-turn `clear_per_turn_card_vars` sweep and is cleared only
    /// `WhenPlayed` (the same late `AfterCardPlayedCleanup` site that clears
    /// `FreeThisTurn`) or at end-of-combat (the whole `combat_vars` reset).
    /// Mirrors C# `CardEnergyCost.SetUntilPlayed(0)` — an Absolute(0) modifier
    /// with the `WhenPlayed` expiry bit only (NO `EndOfTurn` bit), distinct
    /// from `SetThisTurnOrUntilPlayed`'s `EndOfTurn | WhenPlayed`
    /// (`CardEnergyCost.cs:103`). Energy-only — it does NOT zero star cost
    /// (the C# call is on `EnergyCost`, not `SetToFree`). Set by RocketPunch's
    /// `AfterCardGeneratedForCombat` reaction (`RocketPunch.cs`): when the
    /// player generates a Status card, every RocketPunch the player holds
    /// becomes free until played. Bead `sts2-rs-rocketpunch-statusgen`.
    FreeUntilPlayed,
    /// Per-instance FakeUpgrade level for the v0.107.1 `Wither` status card
    /// (C# `Wither._fakeUpgradeLevel`). Each `FakeUpgrade()` increments this
    /// and `DynamicVars.Damage.UpgradeValueBy(3m)`, so the turn-end self-damage
    /// is `3 + 3 * level`. The Aeonglass boss (bead `.2`) syncs the level on
    /// every Wither in hand each turn via its `WitherUpgradeCount`. Stored 0
    /// when unset ⇒ base 3 damage. Bead `sts2-rs-v0107-content-port-wb8lk.5`.
    WitherFakeUpgradeLevel,
    /// Marker (non-zero = flag set): this card has been COLLECTED by a
    /// two-phase batch auto-play (`combat_loop::auto_play_n_from_draw_top` —
    /// DistilledChaos / Cascade) into the Play pile during phase 1 but has NOT
    /// yet had its own play STARTED in phase 2. C# `NostalgiaPower` counts
    /// `History.CardPlaysStarted` (NOT Play-pile membership), so a pre-loaded
    /// batch sibling that hasn't started must NOT count toward another batch
    /// card's "Attack/Skill plays started this turn" total. Set when the card
    /// is collected (phase 1), cleared right before its play is dispatched
    /// (phase 2). The Nostalgia result-pile redirect's enclosing-play count
    /// skips cards carrying this flag. Distinguishes a not-yet-played batch
    /// sibling from a genuinely-started-but-unfinished NESTED enclosing play
    /// (Catastrophe), which never carries the flag. Bead `sts2-rs-1sew4`
    /// (DistilledChaos/Nostalgia/BeatDown follow-up, Ironclad seed 5513).
    PendingBatchAutoPlay,
    /// Captured star-X hit count for an AUTO-PLAYED `HasStarCostX` card
    /// (Stardust), stored as `stars + 1` so `0` (the unset default) is
    /// distinguishable from a genuine 0-star capture. C# `CardCmd.AutoPlay`
    /// (CardCmd.cs:106-131) captures `LastStarsSpent = current Stars` WITHOUT
    /// calling `SpendResources`/`LoseStars` (ResourceInfo.StarsSpent = 0), so
    /// an auto-played Stardust hits `Stars` times but does NOT spend the stars
    /// (manual play spends them in `SpendResources` before `OnPlay`). Stamped
    /// by the auto-play resolver before the effect dispatch; read + cleared by
    /// `play_stardust`. regent-legal-action Fix B (seed 2010).
    AutoPlayStarX,
    /// C# `Resources.EnergyValue` of an X-cost play when it differs from the
    /// captured X in `energy_spent`, stored as `value + 1` (`0` = unset: the
    /// play's `EnergyValue` is `energy_spent`). Only the Whispering Earring
    /// path sets it: it pays the card with `SpendResources()` and then runs
    /// `CardCmd.AutoPlay(skipXCapture: true)`, whose `EnergyValue =
    /// EnergyCost.GetAmountToSpend()` (CardCmd.cs:126) is the player's energy
    /// AFTER that spend (CardEnergyCost.cs:134-139), while the X stays the
    /// spent amount. Read through [`play_energy_value`] by RightHandHand and
    /// IvoryTile; cleared by every other play.
    AutoPlayEnergyValue,
    /// How much of this card's cost came from an END-OF-TURN-expiring
    /// modifier that a *foreign* producer had already applied when the state
    /// was reconstructed — the amount
    /// [`crate::CombatState::restore_wire_transient_costs_for_turn_start`]
    /// adds back at the owner's next turn start.
    ///
    /// The engine banks its own such discounts per effect
    /// (`StompCostReductionThisTurn`, `PinpointCostReductionThisTurn`,
    /// `SneckoCostDeltaThisTurn`), so a Rust-produced state needs nothing
    /// here. The C# dialects have no equivalent taxonomy: they send the
    /// card's current cost and, separately, what that cost becomes once the
    /// turn's modifiers wear off (`persistent_cost`). Without banking the
    /// difference, a reconstructed Stomp keeps its per-Attack shave forever
    /// — 163 of its 175 cost divergences on the v8 mirror sweep landed on the
    /// `end_turn` that should have restored it.
    ///
    /// Set only by the state reconstruction, and only for a card carrying no
    /// engine-owned this-turn bank; the two representations are mutually
    /// exclusive by construction and a producer sending both is a schema
    /// error, not something to reconcile.
    WireTransientCostThisTurn,
    /// How much of this card's cost came from a WHEN-PLAYED-expiring modifier
    /// that a *foreign* producer had already applied — the amount
    /// [`crate::CombatState::restore_wire_cost_expiring_on_play`] adds back
    /// the moment the card is played.
    ///
    /// Sibling of [`Self::WireTransientCostThisTurn`], and a genuinely
    /// different boundary rather than a duplicate of it. The game's "costs N
    /// this turn" helpers are `SetThisTurnOrUntilPlayed` /
    /// `AddThisTurnOrUntilPlayed` — `EndOfTurn | WhenPlayed`, *whichever comes
    /// first* — and the decomp explicitly flags the pure-`EndOfTurn` variants
    /// "BE CAREFUL USING THIS! … most effects that say 'this turn' really mean
    /// 'this turn or until played'." So a discount restored only at the turn
    /// boundary survives on the very card that spent it: 169 of the 1569
    /// divergences on the v15 mirror sweep were a just-played card sitting in
    /// the discard pile still shaved to 0.
    ///
    /// Set only by the state reconstruction, from the producer's
    /// `played_cost`. Both banks may be live at once on one card — a
    /// `EndOfTurn | WhenPlayed` modifier is counted by each — so whichever
    /// edge arrives first restores the cost and clears BOTH.
    WireCostExpiringOnPlay,
    /// This card's cost once BOTH transient edges have passed — played AND
    /// turn-ended — as an absolute value, from the producer's `stable_cost`.
    ///
    /// Consulted only when one of the two wire banks above is non-zero. The
    /// ambiguity to watch for runs the OTHER way from what that suggests: the
    /// var defaults to 0, so an absent `stable_cost` would read back as a
    /// legitimate-looking `0` and re-bank the surviving half to `0 - cost`.
    /// `parse_card` refuses a wire that sends any of the trio without all
    /// three, which is what makes that unreachable.
    ///
    /// It exists because the two banks alone cannot describe the card — though
    /// not because they collide. One `EndOfTurn | WhenPlayed` modifier arrives
    /// as `(base, base)`; two separate modifiers arrive as `(M2(base),
    /// M1(base))`, which differ unless both are no-ops. What the pair cannot
    /// say is how much of the shave SURVIVES the first edge: for the shared
    /// modifier the whole shave is already restored and the remaining bank must
    /// recompute to zero, while for two independent modifiers the unexpired
    /// half must stay. Leaving the other bank alone would restore a shared
    /// shave twice.
    WireCostStable,
    /// Generic counter slot used by future enchantments / cards. Reserved
    /// so downstream beads don't need to extend this enum just for a
    /// one-off; collisions are caller-managed.
    Generic,
    /// A Snecko Oil roll (C# `SetThisTurnOrUntilPlayed`) is live on this card,
    /// and who owns [`VarKey::CostAbsolutelySet`] when it expires:
    /// [`SNECKO_ROLL_RAISED_FLAG`] or [`SNECKO_ROLL_FLAG_PREOWNED`].
    ///
    /// `SneckoCostDeltaThisTurn` cannot carry this, because a roll equal to
    /// the prior cost banks a zero delta and looks exactly like "no roll". C#
    /// adds the Absolute modifier whatever the roll (`CardEnergyCost.cs:197-
    /// 203`) and drops it at either expiry edge (`:331-345`), so the zero-delta
    /// roll must release the flag too (GH #759). Under Confused (SneckoEye) the
    /// card already carries `SetThisCombat(roll)`, which outlives the Snecko
    /// modifier, so the flag stays when it was set before the roll.
    ///
    /// Appended after `Generic` so no existing discriminant moves.
    SneckoRollLive,
    /// Energy-cost reduction that lasts until the card is played — the
    /// running total of C# `EnergyCost.AddUntilPlayed(-1)` (a `Relative`,
    /// `WhenPlayed` local modifier, `CardEnergyCost.cs:258`). Banked by the
    /// Bookmark relic and the SlumberingEssence enchantment on both builds,
    /// and by v0.111.0 RocketPunch once per player-generated Status card
    /// (`RocketPunch.cs:49`) instead of v0.107.1's `SetUntilPlayed(0)`
    /// ([`VarKey::FreeUntilPlayed`]). Folded into the local base cost before the
    /// global `modify_card_cost` walk and cleared on play with the other
    /// `WhenPlayed` riders.
    CostReductionUntilPlayed,
    /// v0.111.0 Midnight: how many of the combat's exhausts this card's cost
    /// already reflects. Every exhaust bumps it along with the cost, and a
    /// Midnight entering combat is shaved by the exhausts it has not yet
    /// counted (C# `AfterCardEnteredCombat`). A copy (C# `CreateClone`, which
    /// keeps the cost modifiers and skips the catch-up) carries the count, so
    /// it is not shaved twice.
    MidnightExhaustsCounted,
    /// Per-combat "used" bits of the card's enchantments (Vigorous, Glam,
    /// Swift, Sown: `enchantment_hooks`). They lived on [`VarKey::Generic`],
    /// where MadScience keeps its packed TinkerTime variant, so a Glam
    /// MadScience changed rider after its first play and its replay hit as
    /// another variant. Appended so no existing discriminant moves.
    EnchantmentUsed,
    /// The STAR half of C# `SetToFreeThisTurn` (`CardModel.cs:1267-1271`:
    /// `EnergyCost.SetThisTurnOrUntilPlayed(0)` + `SetStarCostThisTurn(0)`),
    /// kept after a Snecko Oil roll clears [`VarKey::FreeThisTurn`]: the roll
    /// only overrides the ENERGY cost (`SneckoOil.cs` `EnergyCost.Set…`), so the
    /// star cost stays 0 this turn. A `ThisTurn` cost, so it clears on play
    /// (`CardModel.cs:1998`) and at turn end, alongside `FreeThisTurn`.
    /// Appended so no existing discriminant moves.
    StarCostFreeThisTurn,
    /// Momentum's running damage bonus (C# `Momentum._extraDamage`, grown by
    /// `Amount` in every `OnPlay` and returned by `EnchantDamageAdditive`).
    /// It shared [`VarKey::RampageDamage`] with Rampage's own growth, so a
    /// Momentum Rampage counted both twice (GH #1021). Appended so no existing
    /// discriminant moves.
    MomentumDamage,
    /// Banshee's Cry: how many of the combat's Ethereal plays this card's cost
    /// already reflects. Each Ethereal play bumps it along with the -2 shave
    /// (C# `AfterCardPlayed`), and a Banshee's Cry entering combat is shaved 2
    /// per Ethereal play it has not yet counted (C# `AfterCardEnteredCombat`,
    /// `BansheesCry.cs:42-55`). A copy (C# `CreateClone`, which keeps the cost
    /// modifiers and skips the catch-up) carries the count, so it is not shaved
    /// twice. Appended so no existing discriminant moves.
    BansheesCryEtherealCounted,
    /// C# `CardModel.ExhaustOnNextPlay` left set on a card whose forced-exhaust
    /// auto-play (Havoc, `CardPileCmd.AutoPlayFromDrawPile` `forceExhaust`) was
    /// blocked: `MoveToResultPileWithoutPlaying` exhausts it WITHOUT clearing
    /// the flag (only `GetResultLocationForCardPlay` and `EndOfTurnCleanup`
    /// clear it, `CardModel.cs:2090-2120`, `:1613`). A Howl from Beyond
    /// exhausted that way and auto-played again from the exhaust pile at the
    /// same turn's end therefore exhausts once more instead of landing in
    /// discard. Cleared at end-of-turn cleanup. Appended so no existing
    /// discriminant moves.
    ExhaustOnNextPlay,
    /// The part of the card's `AddThisCombat` reductions (Melancholy,
    /// Banshee's Cry) that took its cost below 0. C# keeps those as Relative
    /// local modifiers and clamps only the final cost
    /// (`CardEnergyCost.GetWithModifiers`, `Math.Max(0, num)` after the
    /// global hooks), so a 3-cost Melancholy after four deaths sits at -1
    /// and a +1 surcharge (Borrowed Time) still leaves it at 0. `cost` stays
    /// clamped at 0; this holds the rest and is subtracted from the local
    /// base ([`Card::add_cost_this_combat`]). Appended so no existing
    /// discriminant moves.
    CostDebtThisCombat,
    /// A Flatten's live Snecko roll: `1 +` the turn's Osty-attack count when
    /// the roll landed (0 = no live roll). Flatten's `SetThisTurn(0)` on an
    /// Osty attack and the roll's `SetThisTurnOrUntilPlayed` are both
    /// Absolute local modifiers applied in insertion order
    /// (`CardEnergyCost.GetWithModifiers`), so the roll beats a zero from an
    /// earlier attack and loses to one from a later attack
    /// ([`crate::hooks::card_cost_locally_zeroed`]). Cleared with the roll.
    /// Appended so no existing discriminant moves.
    FlattenOstyAttacksAtRoll,
    /// Relative cost added while a local zero was live (free this turn, free
    /// until played, Flatten after an Osty attack). C# folds local modifiers
    /// in insertion order, so Transfigure's `AddThisCombat(1)` on a
    /// Discovery-made free card reads `Absolute(0) + 1 = 1` until the zero
    /// expires ([`crate::hooks::card_cost_locally_zeroed`] is the base it is
    /// added to). Cleared with the free-this-turn / until-played riders.
    /// Appended so no existing discriminant moves.
    CostAddedAfterLocalZero,
    /// The part of the card's `AddThisTurn` reductions (Pinpoint per Skill,
    /// Stomp per Attack) that took its cost below 0. Like
    /// [`Self::CostDebtThisCombat`], C# keeps them as unclamped Relative
    /// local modifiers, so a global surcharge (Tangled's +1) lands on the
    /// negative local cost and leaves it at 0. Subtracted from the local
    /// base; cleared at the owner's turn start with the per-turn banks.
    /// Appended so no existing discriminant moves.
    CostDebtThisTurn,
    /// C# `Regret.CardsInHand`: the hand size this Regret stored in its
    /// `BeforeSideTurnEnd`, which it does only while it is in the hand
    /// (Regret.cs:31-42). A Regret drawn after that point (an orb-kill draw)
    /// keeps the value it had, normally 0, and `OnTurnEndInHand` deals that
    /// and resets it. Appended so no existing discriminant moves.
    RegretCardsInHand,
    /// A discarded Sly card whose auto-play a suspended `DiscardAndDraw`
    /// owes: its 1-based place in the discard order, played once the draw
    /// carrying [`crate::PendingDrawResume::then_play_sly`] finishes. Kept on
    /// the card, not in `CombatState`, which sits at clippy's
    /// large-stack-array limit. Appended so no existing discriminant moves.
    SlyOwedAfterDraw,
    /// On a Nightmare snapshot only: the single-turn flags C#'s
    /// `CardModel.CreateClone` copied from the picked card
    /// (`HasSingleTurnRetain` = 1, `HasSingleTurnSly` = 2, a Local Sly keyword
    /// = 4: [`crate::CombatState::clone_flags_of`]). The player's
    /// `retain_this_turn` / `sly_this_turn` / `sly_this_combat` lists hold
    /// them for live cards;
    /// the snapshot is in no pile, so the flush's `EndOfTurnCleanup` never
    /// clears them and the next-turn copies inherit them. Appended so no
    /// existing discriminant moves.
    CloneTurnFlags,
}

/// [`VarKey::SneckoRollLive`]: the Snecko roll raised `CostAbsolutelySet`, so
/// its expiry clears the flag.
pub const SNECKO_ROLL_RAISED_FLAG: i32 = 1;
/// [`VarKey::SneckoRollLive`]: another absolute modifier (Confused's
/// `SetThisCombat`) already owned `CostAbsolutelySet`, so the flag outlives
/// the Snecko roll.
pub const SNECKO_ROLL_FLAG_PREOWNED: i32 = 2;
/// [`VarKey::SneckoRollLive`] bit, or-ed onto the owner value: the roll was
/// appended after a `SetUntilPlayed(0)` ([`VarKey::FreeUntilPlayed`]). C#
/// folds local modifiers in insertion order (`CardEnergyCost.cs:110-115`), so
/// the roll owns the cost while it lives. The zero is `WhenPlayed` only and
/// outlives a roll that expires at end of turn, so the expiry brings the zero
/// back. A play drops both.
pub const SNECKO_ROLL_OVER_FREE_UNTIL_PLAYED: i32 = 4;

// Bead sts2-rs-k2y (P6-8): persistent card enchantments (`Card::enchantments`).
// Mirrors `sts2_env/cards/enchantments.py` at pin `01c094d` — these survive
// across combats, unlike `combat_vars` which resets at end-of-combat.
//
// The canonical Python file is name-keyed (`dict[str, int]`); we lift the
// string set to a strongly-typed enum. Variants are exhaustive against the
// names referenced in `apply_static_enchantment`, `can_enchant_card`,
// `enchant_damage_*`, `enchant_block_additive`, `enchant_play_count_bonus`,
// `on_card_drawn`, `after_player_turn_start`, `before_flush`,
// `modify_shuffle_order`, `on_card_played`, `after_card_played` plus the
// reward-object surface in `run/reward_objects.py`. Add new variants here
// when the Python pin grows.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum EnchantmentId {
    // --- Static (apply-time) keyword / cost mutators -------------------
    /// Adds `innate` + `retain`. Attack/Skill only.
    RoyallyApproved,
    /// Adds `retain`.
    Steady,
    /// Adds `eternal`, sets cost to 0. Basic Strikes only.
    TezcatarasEmber,
    /// Removes `exhaust`.
    SoulsPower,
    /// Reduces cost by 1 (non-X attacks).
    Instinct,
    /// Adds `exhaust`. Defend-tagged only.
    Goopy,
    // --- Dynamic damage triplet ---------------------------------------
    /// +N base damage (additive). Attack only.
    Sharp,
    /// +N damage once played, persists for this combat. Attack only.
    Momentum,
    /// ×1.5 damage; self-damage 2 on play. Attack only.
    Corrupted,
    /// ×2.0 damage. Attack only.
    Favored,
    /// +N damage first play per combat. Attack only.
    Vigorous,
    // --- Dynamic block ------------------------------------------------
    /// +N base block. Block-bearing only.
    Nimble,
    // --- Play-count / draw / energy ----------------------------------
    /// +N extra play counts on play. Basic Strike/Defend only.
    Spiral,
    /// +N extra play counts first play per combat.
    Glam,
    /// Gain N block on play. Any card.
    Adroit,
    /// Draw N cards on play (first play per combat).
    Swift,
    /// Gain N energy on play (first play per combat).
    Sown,
    /// Auto-play from draw on turn 1. Skill only.
    Imbued,
    /// Cost randomized 0..=3 on draw. Non-X only.
    Slither,
    /// Reduces cost by 1 each turn until played (non-X). Hand-side.
    SlumberingEssence,
    /// Top-of-shuffle ordering hint.
    PerfectFit,
    /// `CLONE` enchantment — added at bead `sts2-rs-226v` as a no-op
    /// marker so .run-corpus fixtures containing `HAVOC+@CLONE` (and
    /// any other base-card @CLONE pair) parse instead of bouncing the
    /// scenario loader. Python pin `01c094d` does not declare a
    /// `CLONE` enchantment kind; the token appears in later sts2log
    /// dumps. Real semantics (duplicate-on-play) will land with the
    /// C#-canon enchantment-port bead.
    Clone,
    /// `Inky` — attached to every Shiv generated by Blade of Ink
    /// (C# `BladeOfInk.cs:36` `CardCmd.Enchant<Inky>(item, 1m)`). On the
    /// enchanted card's play it adds `+2` to a powered attack's damage
    /// (`Inky.cs:EnchantDamageAdditive` → `DamageVar(2)`) and applies `1`
    /// Weak to the target(s) (`Inky.cs:OnPlay` → `PowerVar<WeakPower>(1)`).
    /// `ShowAmount => false`, so the bonus is flat (not stack-scaled). Inky
    /// is only ever applied to Shivs, so its two legs are modeled directly in
    /// `cards::status::shiv::play_shiv` rather than through the (still
    /// half-wired) generic enchantment damage/on-play dispatch.
    Inky,
}

impl EnchantmentId {
    /// The wire spelling for this enchantment: the English localization
    /// title (`localization_eng/enchantments.json`, `<ENTRY>.title`), which
    /// is exactly what both C# producers put on a card's `enchantment`
    /// field. `Favored` and `Inky` have no localized title in v0.107.1, so
    /// they fall back to their class names.
    #[must_use]
    pub fn wire_name(self) -> &'static str {
        match self {
            EnchantmentId::RoyallyApproved => "Royally Approved",
            EnchantmentId::Steady => "Steady",
            EnchantmentId::TezcatarasEmber => "Tezcatara's Ember",
            EnchantmentId::SoulsPower => "Soul's Power",
            EnchantmentId::Instinct => "Instinct",
            EnchantmentId::Goopy => "Goopy",
            EnchantmentId::Sharp => "Sharp",
            EnchantmentId::Momentum => "Momentum",
            EnchantmentId::Corrupted => "Corrupted",
            EnchantmentId::Favored => "Favored",
            EnchantmentId::Vigorous => "Vigorous",
            EnchantmentId::Nimble => "Nimble",
            EnchantmentId::Spiral => "Spiral",
            EnchantmentId::Glam => "Glam",
            EnchantmentId::Adroit => "Adroit",
            EnchantmentId::Swift => "Swift",
            EnchantmentId::Sown => "Sown",
            EnchantmentId::Imbued => "Imbued",
            EnchantmentId::Slither => "Slither",
            EnchantmentId::SlumberingEssence => "Slumbering Essence",
            EnchantmentId::PerfectFit => "Perfect Fit",
            EnchantmentId::Clone => "Clone",
            EnchantmentId::Inky => "Inky",
        }
    }

    /// Parse a wire spelling back to an id, `None` if unknown.
    ///
    /// Deliberately spelling-insensitive: the same enchantment reaches us as
    /// a localized title (`"Soul's Power"`), a C# class name
    /// (`"SoulsPower"`), and a scenario token (`"SOULS_POWER"`). All three
    /// normalize to the same alphanumeric key, so one table serves every
    /// dialect instead of three that can drift apart.
    ///
    /// A fourth dialect: the headless producer resolves the title through
    /// localization (`_loc.Bilingual("enchantments", id + ".title")`), and a
    /// MISSING loc entry comes back as the raw KEY — v0.107.1's English data
    /// has no `enchantments/INKY.title`, so an Inky card arrives as
    /// `"INKY.title"` (v36wr seed 1002 died on it). Strip that suffix before
    /// normalizing; the entry id underneath is already the table's spelling.
    #[must_use]
    pub fn from_wire_name(name: &str) -> Option<Self> {
        let name = name.strip_suffix(".title").unwrap_or(name);
        let key: String = name
            .chars()
            .filter(char::is_ascii_alphanumeric)
            .map(|c| c.to_ascii_uppercase())
            .collect();
        Some(match key.as_str() {
            "ROYALLYAPPROVED" => EnchantmentId::RoyallyApproved,
            "STEADY" => EnchantmentId::Steady,
            "TEZCATARASEMBER" => EnchantmentId::TezcatarasEmber,
            "SOULSPOWER" => EnchantmentId::SoulsPower,
            "INSTINCT" => EnchantmentId::Instinct,
            "GOOPY" => EnchantmentId::Goopy,
            "SHARP" => EnchantmentId::Sharp,
            "MOMENTUM" => EnchantmentId::Momentum,
            "CORRUPTED" => EnchantmentId::Corrupted,
            "FAVORED" => EnchantmentId::Favored,
            "VIGOROUS" => EnchantmentId::Vigorous,
            "NIMBLE" => EnchantmentId::Nimble,
            "SPIRAL" => EnchantmentId::Spiral,
            "GLAM" => EnchantmentId::Glam,
            "ADROIT" => EnchantmentId::Adroit,
            "SWIFT" => EnchantmentId::Swift,
            "SOWN" => EnchantmentId::Sown,
            "IMBUED" => EnchantmentId::Imbued,
            "SLITHER" => EnchantmentId::Slither,
            "SLUMBERINGESSENCE" => EnchantmentId::SlumberingEssence,
            "PERFECTFIT" => EnchantmentId::PerfectFit,
            "CLONE" => EnchantmentId::Clone,
            "INKY" => EnchantmentId::Inky,
            _ => return None,
        })
    }

    /// Every enchantment, in DECLARATION order.
    ///
    /// Declaration order, not alphabetical, because this feeds the PPO
    /// enchantment embedding through an append-only pin — see
    /// `sts2_vocab` (re-exported as `sts2_runai::ppo::vocab`). A new variant goes at the END of the enum
    /// and the END of the pin file; inserting one mid-enum would be a silent
    /// re-index of rows a deployed champion has learned (GH #544's lesson,
    /// applied before it can bite here).
    pub const ALL: [EnchantmentId; 23] = [
        EnchantmentId::RoyallyApproved,
        EnchantmentId::Steady,
        EnchantmentId::TezcatarasEmber,
        EnchantmentId::SoulsPower,
        EnchantmentId::Instinct,
        EnchantmentId::Goopy,
        EnchantmentId::Sharp,
        EnchantmentId::Momentum,
        EnchantmentId::Corrupted,
        EnchantmentId::Favored,
        EnchantmentId::Vigorous,
        EnchantmentId::Nimble,
        EnchantmentId::Spiral,
        EnchantmentId::Glam,
        EnchantmentId::Adroit,
        EnchantmentId::Swift,
        EnchantmentId::Sown,
        EnchantmentId::Imbued,
        EnchantmentId::Slither,
        EnchantmentId::SlumberingEssence,
        EnchantmentId::PerfectFit,
        EnchantmentId::Clone,
        EnchantmentId::Inky,
    ];

    /// The canonical UPPER_SNAKE registry name — what
    /// `list_registry_names("enchantment")` returns and what the PPO vocab
    /// keys on. Distinct from [`Self::wire_name`], which is the localized
    /// display title (`"Soul's Power"`) two C# producers emit.
    #[must_use]
    pub fn python_name(self) -> &'static str {
        match self {
            EnchantmentId::RoyallyApproved => "ROYALLY_APPROVED",
            EnchantmentId::Steady => "STEADY",
            EnchantmentId::TezcatarasEmber => "TEZCATARAS_EMBER",
            EnchantmentId::SoulsPower => "SOULS_POWER",
            EnchantmentId::Instinct => "INSTINCT",
            EnchantmentId::Goopy => "GOOPY",
            EnchantmentId::Sharp => "SHARP",
            EnchantmentId::Momentum => "MOMENTUM",
            EnchantmentId::Corrupted => "CORRUPTED",
            EnchantmentId::Favored => "FAVORED",
            EnchantmentId::Vigorous => "VIGOROUS",
            EnchantmentId::Nimble => "NIMBLE",
            EnchantmentId::Spiral => "SPIRAL",
            EnchantmentId::Glam => "GLAM",
            EnchantmentId::Adroit => "ADROIT",
            EnchantmentId::Swift => "SWIFT",
            EnchantmentId::Sown => "SOWN",
            EnchantmentId::Imbued => "IMBUED",
            EnchantmentId::Slither => "SLITHER",
            EnchantmentId::SlumberingEssence => "SLUMBERING_ESSENCE",
            EnchantmentId::PerfectFit => "PERFECT_FIT",
            EnchantmentId::Clone => "CLONE",
            EnchantmentId::Inky => "INKY",
        }
    }
}

// ---------------------------------------------------------------------------
// CardTag — bead `sts2-rs-3f8` (P7-surf)
// ---------------------------------------------------------------------------

/// Card-tag mirror of `sts2-rl-agent@01c094d:sts2_env/core/enums.py::CardTag`.
///
/// Python's `CardTag` is an `Enum` and `CardInstance.tags: frozenset[CardTag]`.
/// Here we expose the discriminant set as a `repr(u8)` enum and pair it with
/// [`CardTags`] (a tiny bitflag set) so the common membership query stays
/// `O(1)` and `Copy`. Variant order matches the Python enum exactly so the
/// bit positions are deterministic across pin bumps.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
#[repr(u8)]
pub enum CardTag {
    /// Basic Strike-family tag (`FakeStrikeDummy`, etc.).
    Strike = 0,
    /// Basic Defend-family tag (`Goopy` enchant gate, etc.).
    Defend = 1,
    /// Minion summoned-card tag.
    Minion = 2,
    /// `Osty` character attack tag.
    OstyAttack = 3,
    /// Shiv-family tag (e.g. Silent's generated `Shiv`).
    Shiv = 4,
}

impl CardTag {
    /// Bit position used by [`CardTags`] for this tag.
    #[inline]
    #[must_use]
    pub const fn bit(self) -> u8 {
        1u8 << (self as u8)
    }
}

/// Bit-packed set of [`CardTag`]s. Mirrors Python's
/// `CardInstance.tags: frozenset[CardTag]`.
///
/// Five variants today fit in a `u8`; widen to `u16` when the Python pin
/// grows the `CardTag` enum past 8 entries.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash, PartialOrd, Ord)]
#[repr(transparent)]
pub struct CardTags(pub u8);

impl CardTags {
    /// Empty set.
    pub const NONE: Self = Self(0);

    /// Single-tag set.
    #[inline]
    #[must_use]
    pub const fn one(tag: CardTag) -> Self {
        Self(tag.bit())
    }

    /// Membership test.
    #[inline]
    #[must_use]
    pub const fn contains(self, tag: CardTag) -> bool {
        self.0 & tag.bit() != 0
    }

    /// Insert `tag` into the set, returning the new value.
    #[inline]
    #[must_use]
    pub const fn with(self, tag: CardTag) -> Self {
        Self(self.0 | tag.bit())
    }

    /// `true` if the set is empty (matches Python `len(tags) == 0`).
    #[inline]
    #[must_use]
    pub const fn is_empty(self) -> bool {
        self.0 == 0
    }

    /// Iterate over the contained tags in [`CardTag`] discriminant order.
    /// Allocates a small fixed-size buffer; intended for tests / debug.
    #[must_use]
    pub fn to_vec(self) -> SmallVec<[CardTag; 4]> {
        let mut out: SmallVec<[CardTag; 4]> = SmallVec::new();
        for &tag in &[
            CardTag::Strike,
            CardTag::Defend,
            CardTag::Minion,
            CardTag::OstyAttack,
            CardTag::Shiv,
        ] {
            if self.contains(tag) {
                out.push(tag);
            }
        }
        out
    }
}

// ---------------------------------------------------------------------------
// Card POD + supporting enums
// ---------------------------------------------------------------------------

/// Card type. Mirrors C# `CardType` (`Entities.Cards/CardType.cs`) minus
/// its `None` placeholder.
///
/// `Quest` is the type of the four Quest cards (ByrdonisEgg, LanternKey,
/// SpoilsMap and v0.111.0's Dowsing — each `base(.., CardType.Quest, ..)`).
/// It used to be folded into `Skill`, which made every `== Skill` check
/// match them where C#'s `Type == CardType.Skill` does not (GH #1111).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum CardType {
    Attack,
    Skill,
    Power,
    Curse,
    Status,
    Quest,
}

impl CardType {
    /// Stable, contiguous discriminant index used by the
    /// per-turn cards-played counter in
    /// [`crate::PlayerCombatState::cards_played_this_turn`] (bead
    /// `sts2-rs-r6l9`). Matches enum declaration order:
    /// `Attack=0`, `Skill=1`, `Power=2`, `Curse=3`, `Status=4`, `Quest=5`.
    #[must_use]
    pub const fn index(self) -> usize {
        match self {
            CardType::Attack => 0,
            CardType::Skill => 1,
            CardType::Power => 2,
            CardType::Curse => 3,
            CardType::Status => 4,
            CardType::Quest => 5,
        }
    }
}

/// Targeting kind. Mirrors `sts2_env/core/enums.py::TargetType` collapsed to
/// the five distinct semantics relevant for Phase-1 starter cards. The
/// `Self_` spelling avoids the `Self` keyword.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum TargetType {
    Enemy,
    AllEnemies,
    Self_,
    None,
    Random,
}

/// True while a Shiv's dynamic C# `TargetType` resolves to `AllEnemies`
/// instead of `AnyEnemy` — i.e. while the player holds `FanOfKnives`
/// (C# `Shiv.cs:23-32`, mirrored by `Shiv.OnPlay`'s `TargetingAllOpponents`
/// arm at `Shiv.cs:60-72`).
///
/// GH #335: this predicate used to be copy-pasted at four sites — legal-action
/// generation, the manual play path, Catastrophe/DistilledChaos autoplay, and
/// `play_shiv` itself. The first three decide whether a target is *required*,
/// the fourth whether a target is *used*; when the copies disagreed (the power
/// lapsing between surfacing and resolution) `play_shiv` aborted the process on
/// an `expect`. Keep every site on this one function so the arms cannot drift.
#[inline]
#[must_use]
pub fn shiv_hits_all_enemies(state: &crate::CombatState) -> bool {
    state.player_power_amount(crate::PowerKind::FanOfKnives) > 0
}

/// A card's *effective* [`TargetType`], folding in Shiv's dynamic override.
///
/// The card spec stores Shiv's static `Enemy`; C# recomputes `TargetType` on
/// every read, so callers that gate targeting on the spec must go through this
/// instead. Every other card returns its spec value unchanged.
#[inline]
#[must_use]
pub fn effective_target_type(state: &crate::CombatState, card: &Card) -> TargetType {
    if card.card_id == CardId::Shiv && shiv_hits_all_enemies(state) {
        TargetType::AllEnemies
    } else {
        card.target_type
    }
}

/// Per-instance *absolute* keyword set that overrides the engine-side
/// `CardId`-keyed keyword registries ([`crate::card_effects`]) when a
/// card's upgrade changes its keywords — e.g. BurningPact drops `EXHAUST`,
/// Aggression/Afterimage/Entropy gain `INNATE`, some cards gain `RETAIN`.
///
/// `None` on the [`Card`] means "defer to the `CardId` registry" — the
/// un-upgraded default that holds for every card whose keyword set does
/// not change on upgrade (the overwhelming majority). Only the ~27 cards
/// with a [`keyword`](crate::cards::Card) delta in
/// `sts2-content`'s `card_upgrades_generated::upgrade_delta` carry a
/// `Some(..)` override, set by `apply_spec_upgrade` / the card factory's
/// upgraded build from `CardUpgradeDelta.keywords`. Bead `sts2-rs-59atd`
/// (follow-up to `sts2-rs-vd6pf`).
///
/// Bit positions intentionally mirror `sts2-content`'s
/// `cards::types::CardKeywords` so the content-side conversion is a flat
/// bit copy. Keep the two in sync if either grows.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
#[repr(transparent)]
pub struct KeywordOverride(pub u8);

impl KeywordOverride {
    /// Empty set (card has none of the tracked keywords after upgrade).
    pub const NONE: Self = Self(0);
    /// Card cannot be played from hand.
    pub const UNPLAYABLE: Self = Self(1 << 0);
    /// Card discards itself at end of turn.
    pub const ETHEREAL: Self = Self(1 << 1);
    /// Card stays in hand at end of turn.
    pub const RETAIN: Self = Self(1 << 2);
    /// Card play exhausts the card.
    pub const EXHAUST: Self = Self(1 << 3);
    /// Card is drawn at the start of combat.
    pub const INNATE: Self = Self(1 << 6);
    /// Card cannot be removed from the deck (C# `Eternal` keyword), and
    /// this is THE removal gate — content's
    /// `card_is_removable_instance` tests this bit and nothing else, per
    /// `CardModel.IsRemovable` (`CardModel.cs:738`). Registered into core
    /// through [`crate::register_card_removable`], because core cannot read
    /// content's specs directly.
    /// Bit 7 — mirrors `sts2-content`'s `CardKeywords::ETERNAL`.
    pub const ETERNAL: Self = Self(1 << 7);

    /// Test whether this set contains every flag in `other`.
    #[inline]
    #[must_use]
    pub const fn contains(self, other: Self) -> bool {
        (self.0 & other.0) == other.0
    }

    /// Union of two flag sets. `const`-friendly.
    #[inline]
    #[must_use]
    pub const fn with(self, other: Self) -> Self {
        Self(self.0 | other.0)
    }
}

// The "may be nonzero" mask has 24 bits. VarKey has 26 variants, so the two
// last share a bit with the first two (WireCostStable with RampageDamage,
// Generic with ClawBuff): a superset filter, so that only costs a false
// "maybe". No key a sweep gates on aliases.
impl crate::inline_kv::InlineKvKey for VarKey {
    const FILL: Self = VarKey::RampageDamage;
    #[inline]
    fn nz_index(self) -> usize {
        self as usize % crate::inline_kv::NZ_BITS
    }
}

impl crate::inline_kv::InlineKvKey for EnchantmentId {
    const FILL: Self = EnchantmentId::RoyallyApproved;
    #[inline]
    fn nz_index(self) -> usize {
        self as usize % crate::inline_kv::NZ_BITS
    }
}

/// `Card::combat_vars` storage: fixed-capacity `Copy` map (was
/// `SmallVec<[(VarKey, i32); 4]>` with rare heap spill). Capacity 16 covers
/// the PROVABLE worst case, not just the typical one: slots are never
/// reclaimed (clearing a var writes 0 in place — the live prefix is
/// equality/hash-visible), so a card accumulates one slot per distinct key
/// it EVER touches in a combat. The maximum distinct-key set is 16: the 11
/// generic flags any card can carry (`FreeThisTurn`, `EtherealThisCombat`,
/// `StarCostFreeThisCombat`, `SneckoCostDeltaThisTurn`, `SneckoRollLive`,
/// `CostAbsolutelySet`, `IsDupe`, `GeneratedInCombat`,
/// `PendingBatchAutoPlay`, `DampenDowngradedMarker`, `EnchantmentUsed`) +
/// the wire-reconstruction cost trio + at most 2 card-specific keys on one
/// card (Thrash's remainder pair; every other card-specific key excludes
/// the rest — `Generic` is one of them now that the enchantment bits moved
/// to `EnchantmentUsed`: MadScience's variant, Dowsing's and Guilty's
/// counters). The previous capacity 8 sized for "1–2 scaling keys + a few
/// flags" and panicked mid-run on a legitimate 9th distinct key (GH #474:
/// Ironclad A10 seed 41100016, `CostAbsolutelySet` via net_search forks).
/// Overflow still panics loudly (see [`crate::inline_kv`]); the guard test
/// is `combat_vars_capacity_holds_worst_case_distinct_key_set`.
pub type CombatVars = crate::inline_kv::InlineKv<VarKey, 16>;

/// [`VarKey::GeneratedInCombat`] value of a card generated fresh mid-combat.
pub const GENERATED_FRESH: i32 = 1;
/// [`VarKey::GeneratedInCombat`] value of a [`Card::create_clone`] copy (C#
/// `CardModel.IsClone`). A clone is generated mid-combat too, so it reuses
/// that flag's slot rather than adding a key: the inline var store's
/// worst-case key count stays at its capacity of 16.
pub const GENERATED_AS_CLONE: i32 = 2;

/// `Card::enchantments` storage: fixed-capacity `Copy` map (was
/// `SmallVec<[(EnchantmentId, i32); 2]>` with rare heap spill). Capacity 6:
/// enchantments accumulate per-card across a whole run (shop enchant +
/// event enchants + relic stamps), so this carries generous headroom over
/// the 2-inline typical stack. Overflow panics loudly.
pub type CardEnchantments = crate::inline_kv::InlineKv<EnchantmentId, 6>;

/// Concrete card POD. Mirrors the load-bearing fields of
/// `sts2_env/cards/card.py::CardInstance`. Bead sts2-rs-ov4 (P6-1) added
/// `combat_vars` (per-combat scratch state for Rampage / Claw / etc.) and
/// `enchantments` (run-persistent enchantment stacks).
///
/// `Card` is `Copy` (again): it was `Copy` through Phase 5, lost it when
/// P6-1 stored `combat_vars`/`enchantments` in `SmallVec`, and regained it
/// when those moved to the fixed-capacity [`crate::inline_kv::InlineKv`]
/// (Card-as-Copy, 2026-08). `Copy` is load-bearing for performance: the
/// card arena `CombatState.cards: Vec<Card>` is deep-cloned 2–3× per MCTS
/// simulation, and `Vec<T: Copy>::clone` compiles to one `memcpy` instead
/// of an element-wise clone loop. Equality, `Hash`, and `Debug` output of
/// the two map fields are observationally identical to the old `SmallVec`
/// (all three feed search hashes — see `inline_kv`'s module docs).
///
/// `Hash` is derived so [`crate::hashing`]'s `card_observational_key` can
/// hash a sentinel-uid copy directly instead of Debug-formatting it (the
/// format-and-hash encoding was ~38% of all MCTS search instructions under
/// the PR #467 EndTurn-widening fan-out — callgrind 2026-08-17). The derive
/// keeps the same stay-in-lockstep property the Debug string had: a new
/// field is automatically part of the hash, and a non-`Hash` field fails to
/// compile here rather than silently dropping out of the observational key.
/// `InlineKv`'s manual `Hash` hashes its live prefix as a slice, exactly
/// like the `SmallVec` it replaced, so the hash stream is unchanged.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Card {
    pub uid: CardUid,
    pub card_id: CardId,
    pub cost: i8,
    pub card_type: CardType,
    pub target_type: TargetType,
    pub upgraded: bool,
    pub base_damage: i32,
    pub base_block: i32,
    /// Per-combat persistent scratch state (cleared at end-of-combat).
    /// Mirrors Python's `CardInstance.combat_vars: dict[str, int]`.
    pub combat_vars: CombatVars,
    /// Run-persistent enchantment stacks. Mirrors Python's
    /// `CardInstance.enchantments: dict[str, int]`.
    pub enchantments: CardEnchantments,
    /// Bit-packed [`CardTag`] set. Mirrors Python's
    /// `CardInstance.tags: frozenset[CardTag]`. Defaults to
    /// [`CardTags::NONE`]; per-card factories (sts2-content) populate this
    /// from the static spec.
    pub tags: CardTags,
    /// Energy value of this card's most recent play (C#
    /// `ResourceInfo.EnergyValue`), stamped by
    /// [`crate::combat_loop::play_card`] before dispatch: the raw energy an
    /// X-cost card captured (C# `CapturedXValue`; its handlers resolve X
    /// through [`crate::card_effects::resolving_card_x_value`], which adds
    /// ChemicalX), the paid cost for any other card (GH #741: read by
    /// RightHandHand's late effect and IvoryTile). An auto-play stamps the
    /// captured energy / modifier-resolved cost the same way. 0 before the
    /// first play. Reset on `reset_combat_vars` since the state does not
    /// survive end-of-combat (the card itself is returned to the run-pool).
    /// A non-X card's value is not part of its observational identity — see
    /// [`observational_energy_spent`].
    pub energy_spent: i32,
    /// Extra play repetitions for this specific card instance. Mirrors
    /// Python's `CardInstance.base_replay_count: int` (default 0).
    /// Read by [`crate::combat_loop::play_card`] as the additive base
    /// for the per-play repeat loop:
    ///
    /// ```py
    /// play_count = 1 + getattr(card, "base_replay_count", 0)
    ///              + enchant_play_count_bonus(card)
    /// ```
    ///
    /// Mutated by HiddenGem (colorless, `sts2_env/cards/colorless.py::
    /// hidden_gem`: `selected.base_replay_count += effect_vars.get(
    /// "replay", 2)`) and SoldiersStew (Ironclad rare relic potion,
    /// `sts2_env/potions/effects.py::_soldiers_stew`:
    /// `card.base_replay_count += 1` for Strike-tagged cards). Other
    /// mutators may follow as Phase-7 wires more replay-count surfaces
    /// (e.g. HiddenGem's upgrade-form `+= 4`). Bead `sts2-rs-6ynt.8.4`.
    pub base_replay_count: i32,
    /// Per-instance absolute keyword set, set when this card's upgrade
    /// changes its keywords (see [`KeywordOverride`]). `None` for every
    /// un-upgraded card and every upgrade that leaves keywords intact —
    /// in that case the engine-side `CardId`-keyed registries in
    /// [`crate::card_effects`] remain authoritative. Populated by
    /// `sts2-content`'s `apply_spec_upgrade` (creation path) and copied
    /// forward by [`Card::upgrade`] (runtime path). Bead `sts2-rs-59atd`.
    pub keyword_override: Option<KeywordOverride>,
    /// Per-instance card affliction (Devoured, Bound, Entangled, …).
    /// Mirrors C# `CardModel.Affliction : AfflictionModel?`
    /// (`MegaCrit.Sts2.Core.Models/CardModel.cs:515`) — at most one
    /// affliction per card at a time. `None` for every card not
    /// currently afflicted. The variant payload (stack count +
    /// Devoured's `applied_exhaust` flag) lives on
    /// [`crate::card_afflictions::CardAffliction`]. Bead
    /// `sts2-rs-96546` (7n7tb sub-1; scope at
    /// `docs/audits/2026-05-29-7n7tb-card-affliction-port-scope.md`).
    pub affliction: Option<crate::card_afflictions::CardAffliction>,
}

// Layout tripwire: the card arena (`CombatState.cards: Vec<Card>`) is
// memcpy-cloned 2–3× per MCTS simulation, so every byte here is hot. 224 =
// 40 (scalar fields) + 132 (CombatVars, cap 16) + 52 (CardEnchantments,
// cap 6). The 160→224 growth is the deliberate GH #474 capacity raise
// (clone bench 2026-08-18: combatstate_clone_grown_arena_48 3.03→3.05µs,
// +0.5%; the isolated card_arena_clone_48 memcpy 94→116ns).
// If this fires, you grew `Card` — decide deliberately (and re-run the
// grown-arena clone bench in sts2-bench) rather than letting it drift.
const _: () = assert!(
    core::mem::size_of::<Card>() == 224,
    "size_of::<Card>() changed — see the comment above this assert"
);

impl Card {
    /// Returns a `Card` POD with placeholder identity (uid=1, StrikeIronclad,
    /// Attack/Enemy/cost=1) and zero-default scratch fields. Intended for
    /// the `..Card::pod_defaults()` spread pattern in tests and helpers, so
    /// new scratch fields added to `Card` (most recently `energy_spent` per
    /// bead `sts2-rs-n4wd`) don't break every literal across the workspace.
    ///
    /// Production code should set every field explicitly — the placeholder
    /// identity is intentionally a sentinel that would fail any meaningful
    /// equality check.
    #[must_use]
    pub fn pod_defaults() -> Self {
        Card {
            uid: CardUid::new(1).expect("non-zero"),
            card_id: CardId::StrikeIronclad,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 0,
            base_block: 0,
            combat_vars: CombatVars::new(),
            enchantments: CardEnchantments::new(),
            tags: CardTags::NONE,
            energy_spent: 0,
            base_replay_count: 0,
            keyword_override: None,
            affliction: None,
        }
    }

    /// Set `affliction` to `Some(a)` if it is allowed on this card's
    /// type per [`crate::card_afflictions::CardAffliction::can_afflict_card_type`].
    /// Returns `true` on success, `false` when the type filter rejects
    /// (mirrors C# `AfflictionModel.CanAfflictCardType` — see e.g.
    /// `Devoured.cs:26-33` rejecting Power cards).
    ///
    /// Overwrites any existing affliction (the flat one-affliction-per-card
    /// model matches `CardModel.Affliction` semantics at this pin).
    /// Bead `sts2-rs-cd1zg` (7n7tb sub-2).
    #[must_use]
    pub fn set_affliction(&mut self, a: crate::card_afflictions::CardAffliction) -> bool {
        if !crate::card_afflictions::CardAffliction::can_afflict_card_type(a.kind, self.card_type) {
            return false;
        }
        self.affliction = Some(a);
        true
    }

    /// Take the affliction off the card, returning the prior value.
    /// Mirrors C# `CardCmd.ClearAffliction(card)` at the call sites of
    /// `HungerPower.AfterRemoved` (`HungerPower.cs:72`). The Exhaust-keyword
    /// revert (if `applied_exhaust` was set) is left to the caller —
    /// `Card` deliberately does not own the keyword side effect so this
    /// surface composes cleanly with whatever keyword model the caller
    /// uses (see [`crate::card_effects::card_exhausts_inst`] +
    /// [`KeywordOverride`]). Bead `sts2-rs-cd1zg` (7n7tb sub-2).
    pub fn clear_affliction(&mut self) -> Option<crate::card_afflictions::CardAffliction> {
        self.affliction.take()
    }

    /// `true` iff this card currently carries a [`CardAfflictionKind::Devoured`]
    /// affliction whose `applied_exhaust` flag is set. Convenience read
    /// used by the [`HungerPower::AfterRemoved`] revert path (bead
    /// `sts2-rs-9l5c2`) to decide whether to strip the Exhaust keyword.
    /// Bead `sts2-rs-cd1zg` (7n7tb sub-2).
    #[must_use]
    pub fn devoured_added_exhaust(&self) -> bool {
        matches!(
            self.affliction,
            Some(crate::card_afflictions::CardAffliction {
                kind: crate::card_afflictions::CardAfflictionKind::Devoured,
                applied_exhaust: true,
                ..
            })
        )
    }

    /// Look up a `combat_vars` slot, returning the current amount or 0. One
    /// bit test when the key has never held a nonzero value on this card
    /// ([`crate::inline_kv::InlineKv::get`]).
    #[inline]
    #[must_use]
    pub fn combat_var(&self, key: VarKey) -> i32 {
        self.combat_vars.get(key)
    }

    /// Set / overwrite a `combat_vars` slot. Inserts a new entry if absent.
    #[inline]
    pub fn set_combat_var(&mut self, key: VarKey, value: i32) {
        self.combat_vars.set(key, value);
    }

    /// C# `CardModel.CreateClone()` of this card: a field-for-field copy that
    /// is a NEW instance. Everything the clone deep-copies stays — cost
    /// modifiers, enchantment amounts and their `Status` (Swift / Sown already
    /// `Disabled` by the played card's own `OnPlay`, EnchantmentModel.cs:309-314
    /// keeps `_status`). What does not carry over is state the engine derives
    /// from the card INSTANCE's play history: Bolas / ThrummingHatchet return
    /// only a card whose own play is in `History.CardPlaysFinished`
    /// (Bolas.cs:41-46, ThrummingHatchet.cs:35-40), so the copy loses the
    /// `ReturnIfPlayedRound` stamp. Callers spawn the result (which assigns the
    /// new uid).
    ///
    /// The copy is marked as a clone ([`Self::is_clone`], C#
    /// `CardModel.IsClone`: `CreateClone` sets `_cloneOf`, CardModel.cs).
    /// Every clone a C# `IsClone` reader can see goes through here: Stomp /
    /// Pinpoint copies (Juggling, Nightmare, Dual Wield, Music Box, Burning
    /// Sticks) and Heirloom Hammer's Sovereign Blade (SwordSage). The cards
    /// that copy THEMSELVES (Anger, Undeath, Adaptive Strike) still copy the
    /// raw POD: no `IsClone` reader looks at them in either build, and the
    /// extra var slots would only move the search hashes (GH #1094).
    #[must_use]
    pub fn create_clone(&self) -> Self {
        let mut clone = *self;
        clone.set_combat_var(VarKey::ReturnIfPlayedRound, 0);
        clone.set_combat_var(VarKey::GeneratedInCombat, GENERATED_AS_CLONE);
        clone
    }

    /// Append a local `Absolute(0)` — C# `SetToFreeThisTurn`
    /// (`SetThisTurnOrUntilPlayed(0)`, [`VarKey::FreeThisTurn`]) or
    /// `SetUntilPlayed(0)` ([`VarKey::FreeUntilPlayed`]). Local modifiers fold
    /// in order (`CardEnergyCost.cs:110-115`), so the new zero also overrides
    /// a Transfigure `+1` appended after an earlier zero
    /// ([`VarKey::CostAddedAfterLocalZero`], GH #1150).
    pub fn set_locally_free(&mut self, key: VarKey) {
        debug_assert!(matches!(
            key,
            VarKey::FreeThisTurn | VarKey::FreeUntilPlayed
        ));
        self.set_combat_var(key, 1);
        self.combat_vars.zero(VarKey::CostAddedAfterLocalZero);
    }

    /// C# `CardModel.IsClone` (`CloneOf != null`): this card was made by
    /// [`Self::create_clone`] (or is a copy of such a card). Stomp, Pinpoint
    /// and Banshee's Cry skip their entered-combat cost catch-up for a clone.
    #[must_use]
    pub fn is_clone(&self) -> bool {
        self.combat_var(VarKey::GeneratedInCombat) == GENERATED_AS_CLONE
    }

    /// C# `EnergyCost.AddUntilPlayed(-amount)`: bank `amount` more energy off
    /// this card until it is played ([`VarKey::CostReductionUntilPlayed`]).
    pub fn add_cost_reduction_until_played(&mut self, amount: i32) {
        let banked = self.combat_var(VarKey::CostReductionUntilPlayed);
        self.set_combat_var(VarKey::CostReductionUntilPlayed, banked + amount);
    }

    /// C# `EnergyCost.AddThisCombat(delta)`: a Relative local modifier for the
    /// rest of combat, unclamped until the final cost read. `cost` holds the
    /// part at or above 0 and [`VarKey::CostDebtThisCombat`] the part below
    /// it, so a later `+n` pays the debt off first. X-cost cards are skipped.
    pub fn add_cost_this_combat(&mut self, delta: i32) {
        if self.is_x_cost() {
            return;
        }
        let debt = self.combat_var(VarKey::CostDebtThisCombat);
        let raw = i32::from(self.cost) - debt + delta;
        if raw >= 0 {
            self.cost = i8::try_from(raw).unwrap_or(i8::MAX);
            self.combat_vars.zero(VarKey::CostDebtThisCombat);
        } else {
            self.cost = 0;
            self.set_combat_var(VarKey::CostDebtThisCombat, -raw);
        }
    }

    /// C# `CardModel.SetToFreeThisCombat` (TouchOfInsanity): energy cost 0 and
    /// star cost 0 for the rest of combat. `EnergyCost.SetThisCombat(0)` adds an
    /// *Absolute* local modifier ([`VarKey::CostAbsolutelySet`]) AFTER any live
    /// Snecko Oil roll, and `GetWithModifiers` applies local modifiers in order
    /// (CardEnergyCost.cs:110-115), so the later Absolute(0) owns the cost and the
    /// roll's expiry reveals 0, not the pre-roll base. Drop the Snecko bank so
    /// [`Self::expire_snecko_roll`] does not subtract it from the new 0 (a -1
    /// cost reads as X-cost and drained all energy: Defect full seed 3863).
    pub fn set_free_this_combat(&mut self) {
        self.set_combat_var(VarKey::StarCostFreeThisCombat, 1);
        self.set_cost_this_combat(0);
    }

    /// C# `EnergyCost.SetThisCombat(cost)` (`CardEnergyCost.cs:238-244`): an
    /// Absolute local modifier that lasts the combat. Local modifiers apply in
    /// insertion order (`CardEnergyCost.cs:110-115`), so this later Absolute
    /// owns the cost even while an earlier Snecko Oil roll is live, and the
    /// roll's expiry (on play or at end of turn) reveals `cost`. Drop the
    /// Snecko bank so [`Self::expire_snecko_roll`] does not shift the new
    /// cost. MomentumStrike played at a Snecko-rolled 0 stayed 0 in C# but
    /// came back as 1 here (Defect-1000 act-3 `hand_costs`, GH #1054).
    ///
    /// The same ordering supersedes the relative `AddThisTurn(-n)` shaves
    /// Stomp / Pinpoint banked earlier this turn: once `EndOfTurnCleanup`
    /// drops them (`CardEnergyCost.cs:331-335`) the Absolute still yields
    /// `cost`, so their banks are dropped too or the next turn-start restore
    /// re-adds them (Ironclad-2031: Touch-of-Insanity'd Stomp C# 0, Rust 2).
    ///
    /// It also supersedes the earlier local riders the collapsed model keeps
    /// beside `cost`: the `SetThisTurnOrUntilPlayed(0)` / `SetUntilPlayed(0)`
    /// Absolutes ([`VarKey::FreeThisTurn`], [`VarKey::FreeUntilPlayed`]) and an
    /// `AddUntilPlayed(-n)` reduction ([`VarKey::CostReductionUntilPlayed`]) —
    /// all folded BEFORE this Absolute, so it owns the cost (loadout Defect
    /// v0.107.1 2008: a RocketPunch made free until played, then drawn under
    /// Confused, cost the Confused roll in C#, 0 in Rust). `SetToFreeThisTurn`'s
    /// star half survives (it is a separate star cost).
    pub fn set_cost_this_combat(&mut self, cost: i8) {
        self.cost = cost;
        // The later Absolute also supersedes the earlier Relative
        // `AddThisCombat` reductions.
        self.combat_vars.zero(VarKey::CostDebtThisCombat);
        self.combat_vars.zero(VarKey::CostDebtThisTurn);
        self.set_combat_var(VarKey::CostAbsolutelySet, 1);
        self.set_combat_var(VarKey::SneckoCostDeltaThisTurn, 0);
        self.set_combat_var(VarKey::SneckoRollLive, 0);
        self.set_combat_var(VarKey::StompCostReductionThisTurn, 0);
        self.set_combat_var(VarKey::PinpointCostReductionThisTurn, 0);
        if self.combat_vars.maybe_nonzero(VarKey::FreeThisTurn)
            && self.combat_var(VarKey::FreeThisTurn) != 0
        {
            self.set_combat_var(VarKey::StarCostFreeThisTurn, 1);
            self.combat_vars.zero(VarKey::FreeThisTurn);
        }
        self.combat_vars.zero(VarKey::FreeUntilPlayed);
        self.combat_vars.zero(VarKey::CostReductionUntilPlayed);
    }

    /// C# `EnergyCost.SetThisTurnOrUntilPlayed(cost, reduceOnly: true)`
    /// (`CardEnergyCost.cs:197-203`): an Absolute modifier that drops at the
    /// owner's end-of-turn cleanup or when the card is played. It rides the
    /// same banked-delta slots as a Snecko Oil roll (the identical C#
    /// modifier), so [`Self::expire_snecko_roll`] reverts it on either edge.
    /// Reduce-only: a card already at or below `cost` is left alone. X-cost
    /// cards are skipped.
    ///
    /// An earlier `AddUntilPlayed(-n)` reduction
    /// ([`VarKey::CostReductionUntilPlayed`]) folds BEFORE this Absolute
    /// (local modifiers apply in insertion order, `CardEnergyCost.cs:110-115`;
    /// reduce-only Absolute = `min(current, cost)`, `LocalCostModifier.cs:91`),
    /// so both the reduce-only test and the result see the reduced cost: a
    /// 3-cost Reap retained with a 1-reduction (2) reads `min(2, 1) = 1`, not
    /// `1 - 1 = 0`. The collapsed model subtracts the reduction after `cost`,
    /// so `cost` is set to `cost + reduction`; past turn end (the reduction is
    /// `WhenPlayed` only) the cap's expiry restores the old `cost` and the
    /// reduction applies again, as in C#. Loadout Necrobinder v0.107.1 1386.
    pub fn set_this_turn_or_until_played_reduce_only(&mut self, cost: i8) {
        if self.is_x_cost() {
            return;
        }
        // The below-zero debts of earlier Relative shaves fold before it too
        // (see `CombatState::snecko_randomize_hand_costs`).
        let reduction = self.combat_var(VarKey::CostReductionUntilPlayed)
            + self.combat_var(VarKey::CostDebtThisCombat)
            + self.combat_var(VarKey::CostDebtThisTurn);
        if i32::from(self.cost) - reduction <= i32::from(cost) {
            return;
        }
        let new_cost = i32::from(cost) + reduction;
        let delta = new_cost - i32::from(self.cost);
        self.cost = i8::try_from(new_cost).unwrap_or(i8::MAX);
        let banked = self.combat_var(VarKey::SneckoCostDeltaThisTurn);
        self.set_combat_var(
            VarKey::SneckoCostDeltaThisTurn,
            banked.saturating_add(delta),
        );
        if self.combat_var(VarKey::SneckoRollLive) == 0 {
            let owner = if self.combat_var(VarKey::CostAbsolutelySet) != 0 {
                SNECKO_ROLL_FLAG_PREOWNED
            } else {
                SNECKO_ROLL_RAISED_FLAG
            };
            self.set_combat_var(VarKey::SneckoRollLive, owner);
        }
        self.set_combat_var(VarKey::CostAbsolutelySet, 1);
    }

    /// C# `EnergyCost.SetThisCombat(cost, reduceOnly: true)` (Enlightenment+,
    /// `CardEnergyCost.cs:238-244`): `cost` caps the card for the rest of
    /// combat. X-cost cards are skipped.
    ///
    /// The modifier is appended after any live this-turn-or-until-played
    /// rider (plain Enlightenment, a Snecko Oil roll), and local modifiers
    /// fold in order (`CardEnergyCost.cs:110-115`, reduce-only Absolute =
    /// `min(current, cost)`, `LocalCostModifier.cs:91`). So the displayed
    /// cost is `min(cost_now, cap)` and, once the rider expires, the cap
    /// still applies to the revealed cost: re-bank the rider so
    /// [`Self::expire_snecko_roll`] reveals `min(revealed, cap)` and keeps
    /// `CostAbsolutelySet`. Plain-then-upgraded Enlightenment left a 2-cost
    /// Cinder at 1 in C# but back at 2 here after it was played
    /// (Ironclad-2026 act 3).
    pub fn set_this_combat_reduce_only(&mut self, cost: i8) {
        if self.is_x_cost() {
            return;
        }
        // The cap is the LAST local modifier, so C# reads `min(x, cap)` for
        // whatever `x` the earlier modifiers give at each moment:
        // * now: the shown cost, `cost - reduction`;
        // * once a live roll expires (end of turn): the pre-roll base less
        //   the `AddUntilPlayed(-n)` reduction, which outlives it;
        // * once the card is played (roll and reduction both gone): the base.
        // Re-bank the roll and the reduction so the collapsed model yields
        // all three. A reduction added after a live roll was ignored in the
        // roll branch (GH #1150).
        let live = self.combat_var(VarKey::SneckoRollLive);
        let banked = self.combat_var(VarKey::SneckoCostDeltaThisTurn);
        let reduction = self.combat_var(VarKey::CostReductionUntilPlayed);
        let cap = i32::from(cost);
        let base = i32::from(self.cost) - banked;
        let capped_base = base.min(cap);
        let new_reduction = capped_base - (base - reduction).min(cap);
        let new_cost = (i32::from(self.cost) - reduction).min(cap) + new_reduction;
        let lowered = new_cost < i32::from(self.cost);
        self.cost = i8::try_from(new_cost).unwrap_or(i8::MAX);
        if reduction != 0 || new_reduction != 0 {
            self.set_combat_var(VarKey::CostReductionUntilPlayed, new_reduction);
        }
        if live == 0 && banked == 0 {
            // A cap that lowered the card owns its cost like any Absolute
            // modifier: a later in-combat upgrade lowers only `_base`
            // (`CardEnergyCost.UpgradeBy`, CardEnergyCost.cs:351-370) and the
            // cap keeps `min(new base, cap)` (`GetWithModifiers` :110-121).
            // Enlightenment+ then Armaments+ on a 2-cost card is 1, not 0
            // (Ironclad 5915 v0.107.1 @637).
            if lowered {
                self.set_combat_var(VarKey::CostAbsolutelySet, 1);
            }
            return;
        }
        self.set_combat_var(VarKey::SneckoCostDeltaThisTurn, new_cost - capped_base);
        self.set_combat_var(
            VarKey::SneckoRollLive,
            SNECKO_ROLL_FLAG_PREOWNED | (live & SNECKO_ROLL_OVER_FREE_UNTIL_PLAYED),
        );
        self.set_combat_var(VarKey::CostAbsolutelySet, 1);
    }

    /// Expire this card's Snecko Oil roll, if one is live: C#'s
    /// `SetThisTurnOrUntilPlayed` modifier dropping at `EndOfTurnCleanup` or
    /// `AfterCardPlayedCleanup` (`CardEnergyCost.cs:331-345`). Subtracts the
    /// banked delta (possibly 0) and releases `CostAbsolutelySet` unless
    /// another absolute modifier owned it before the roll (GH #759).
    ///
    /// A bank without the [`VarKey::SneckoRollLive`] marker (a state that
    /// predates it) expires as a roll that raised the flag.
    ///
    /// A roll laid over a `SetUntilPlayed(0)`
    /// ([`SNECKO_ROLL_OVER_FREE_UNTIL_PLAYED`]) reveals that zero again: it is
    /// `WhenPlayed` only, so it outlives the end-of-turn expiry. The play edge
    /// drops both ([`Self::expire_snecko_roll_on_play`]).
    pub fn expire_snecko_roll(&mut self) {
        let live = self.combat_var(VarKey::SneckoRollLive);
        let banked = self.combat_var(VarKey::SneckoCostDeltaThisTurn);
        if live == 0 && banked == 0 {
            return;
        }
        let restored = i32::from(self.cost) - banked;
        if restored < 0 {
            // A Relative shave taken below the roll (`AddThisCombat(-1)` while
            // it was live) outlives it: its below-zero part stays a debt.
            self.cost = 0;
            let debt = self.combat_var(VarKey::CostDebtThisCombat);
            self.set_combat_var(VarKey::CostDebtThisCombat, debt - restored);
        } else {
            self.cost = i8::try_from(restored).unwrap_or(i8::MAX);
        }
        self.set_combat_var(VarKey::SneckoCostDeltaThisTurn, 0);
        self.set_combat_var(VarKey::SneckoRollLive, 0);
        self.combat_vars.zero(VarKey::FlattenOstyAttacksAtRoll);
        if live & SNECKO_ROLL_OVER_FREE_UNTIL_PLAYED != 0 {
            self.set_combat_var(VarKey::FreeUntilPlayed, 1);
        }
        if live & !SNECKO_ROLL_OVER_FREE_UNTIL_PLAYED != SNECKO_ROLL_FLAG_PREOWNED {
            self.set_combat_var(VarKey::CostAbsolutelySet, 0);
        }
    }

    /// [`Self::expire_snecko_roll`] on the play edge (C#
    /// `AfterCardPlayedCleanup`, `CardEnergyCost.cs:341-345`): every
    /// `WhenPlayed` modifier drops, so a `SetUntilPlayed(0)` under the roll
    /// goes with it instead of coming back.
    pub fn expire_snecko_roll_on_play(&mut self) {
        let live = self.combat_var(VarKey::SneckoRollLive);
        if live & SNECKO_ROLL_OVER_FREE_UNTIL_PLAYED != 0 {
            self.set_combat_var(
                VarKey::SneckoRollLive,
                live & !SNECKO_ROLL_OVER_FREE_UNTIL_PLAYED,
            );
        }
        self.expire_snecko_roll();
    }

    /// Look up an enchantment stack, returning the current amount or 0.
    #[inline]
    #[must_use]
    pub fn enchantment(&self, id: EnchantmentId) -> i32 {
        self.enchantments.get(id)
    }

    /// `true` iff this card has at least one stack of `id`.
    #[must_use]
    pub fn has_enchantment(&self, id: EnchantmentId) -> bool {
        self.enchantment(id) > 0
    }

    /// Set / overwrite an enchantment stack. Inserts a new entry if absent.
    /// Mirrors `card.enchantments[name] = amount` from `enchantments.py`.
    pub fn set_enchantment(&mut self, id: EnchantmentId, amount: i32) {
        self.enchantments.set(id, amount);
    }

    /// Add `delta` to an enchantment stack (creating if absent).
    /// Mirrors `card.add_enchantment(name, amount)` in Python's run state.
    pub fn add_enchantment(&mut self, id: EnchantmentId, delta: i32) {
        self.enchantments.add(id, delta);
    }

    /// `true` iff `tag` is set on this card. Mirrors Python
    /// `CardInstance.has_card_tag(tag)` at
    /// `sts2-rl-agent@01c094d:sts2_env/cards/base.py:96-97`.
    #[inline]
    #[must_use]
    pub fn has_tag(&self, tag: CardTag) -> bool {
        self.tags.contains(tag)
    }

    /// Borrowed view of the tag set. Mirrors the read-side of Python's
    /// `CardInstance.tags`. The Python-side `has_tag` (no argument)
    /// property maps to [`CardTags::is_empty`] on the returned set.
    #[inline]
    #[must_use]
    pub fn card_tags(&self) -> CardTags {
        self.tags
    }

    /// Idempotent upgrade flip. Mirrors the early-return in Python's
    /// `RunState.upgrade_card_instance` at
    /// `sts2-rl-agent@01c094d:sts2_env/run/run_state.py:259-261`:
    ///
    /// ```python
    /// if card is None or card.upgraded:
    ///     return card
    /// ```
    ///
    /// The full Python body then re-fetches the upgraded variant from
    /// `create_card(card_id, upgraded=True)` and copies its fields back
    /// onto `card` (`cost`, `base_damage`, `base_block`, `keywords`, ...).
    ///
    /// Implemented under bead `sts2-rs-vd6pf`: this flips `upgraded = true`
    /// AND rewrites the spec-level POD stats (`cost` / `base_damage` /
    /// `base_block`) to their upgraded values via the registered card
    /// factory (see the body). Card creation is also covered —
    /// `sts2-content` `card_pod_from_id(id, true)` applies the same
    /// `upgrade_delta` at build time.
    ///
    /// **Remaining gap (follow-up):** keyword upgrades (Aggression gaining
    /// `INNATE`, BurningPact dropping `EXHAUST`, …) are NOT yet applied —
    /// keyword behaviour is resolved by an un-upgrade-aware spec-lookup by
    /// `card_id`, not stored on the `Card` POD, so reflecting keyword
    /// upgrades needs a separate change. The upgraded keyword sets are
    /// already harvested into `card_upgrades_generated` (the `keywords`
    /// field of `CardUpgradeDelta`); wiring them is tracked separately.
    ///
    /// Whether this card can still be upgraded — the decomp's
    /// `CardModel.IsUpgradable` (`!IsUpgraded && CurrentUpgradeLevel <
    /// MaxUpgradeLevel`). C#'s default `MaxUpgradeLevel => 1`; only
    /// curses/statuses override it to `0` (`Infection.cs:17`,
    /// `Burn`/`Dazed`/`Slimed`/`Wound`/`Void`/… — every combat-relevant
    /// `MaxUpgradeLevel => 0` card is a `Curse` or `Status`). So an
    /// un-upgraded non-curse/non-status card is upgradable; a curse/status
    /// never is. Bead `sts2-rs-tye89` (R3 lever 2): the ARMAMENTS upgrade
    /// pick was offering INFECTION (Status) into the choice set, shifting
    /// option-0 and wasting the upgrade vs C#.
    #[must_use]
    pub fn is_upgradable(&self) -> bool {
        // C# `IsUpgradable => !IsUpgraded && CurrentUpgradeLevel <
        // MaxUpgradeLevel`. Curses/statuses override `MaxUpgradeLevel => 0`,
        // but so do the Quest cards (`ByrdonisEgg`, `LanternKey`,
        // `SpoilsMap`, `Dowsing` — `MaxUpgradeLevel => 0`). Before GH #1111
        // they were typed `Skill` and slipped into `WarPaint`'s Skill
        // candidate set (A9P1: SpoilsMap counted as a 7th candidate); the
        // guard stays because an upgrade path need not filter by type.
        !self.upgraded
            && !matches!(self.card_type, CardType::Curse | CardType::Status)
            && !self.is_quest()
    }

    /// C# `Type == CardType.Quest`: the four Quest cards (`ByrdonisEgg`,
    /// `LanternKey`, `SpoilsMap`, and v0.111.0's `Dowsing` — each
    /// `base(.., CardType.Quest, ..)`). Their specs carry
    /// [`CardType::Quest`] (GH #1111); this keys on the id so it also holds
    /// for a hand-built `Card` whose `card_type` was left at a default.
    #[must_use]
    pub fn is_quest(&self) -> bool {
        matches!(
            self.card_id,
            CardId::ByrdonisEgg | CardId::LanternKey | CardId::SpoilsMap | CardId::Dowsing
        )
    }

    /// C# `CardModel.GainsBlock` (`CardModel.cs:671`, `virtual => false`),
    /// which `Nimble.CanEnchant` gates on. 76 v0.107.1 cards override it to
    /// `true`. Almost all of them are exactly the cards with a base block, so
    /// that is the default here. The exceptions (GH #1021):
    /// - block that is not a `BlockVar` (Entrench doubles, Second Wind / Stack
    ///   / ... compute it): `true` with `base_block == 0`;
    /// - Pillar of Creation and Shroud carry a block value but do not
    ///   override `GainsBlock`: `false`;
    /// - Mad Science gains block in its Skill mode (`TinkerTimeType ==
    ///   Skill`; `set_mad_science_variant` stamps that onto `card_type`);
    /// - Sovereign Blade only while its owner has Parry, which no deck card's
    ///   owner has outside combat: `false`.
    /// - Expect a Fight is build-dependent: v0.111.0 reworked it into a
    ///   `CalculatedBlockVar` card with `GainsBlock => true`
    ///   (v0.111.0 `ExpectAFight.cs:17,21-23`), so `base_block` stays 0;
    ///   v0.107.1's energy card has no override.
    #[must_use]
    pub fn gains_block_for(&self, version: crate::GameVersion) -> bool {
        match self.card_id {
            CardId::ExpectAFight => version >= crate::GameVersion::V0_111_0,
            CardId::MadScience => self.card_type == CardType::Skill,
            CardId::SovereignBlade | CardId::PillarOfCreation | CardId::Shroud => false,
            CardId::DemonicShield
            | CardId::Entrench
            | CardId::Fisticuffs
            | CardId::Mimic
            | CardId::Mirage
            | CardId::Sacrifice
            | CardId::SecondWind
            | CardId::Stack => true,
            _ => self.base_block > 0,
        }
    }

    /// The downstream relic bodies (`BoneTea`, `HistoryCourse`,
    /// `FragrantMushroom`) can still call `card.upgrade()` unconditionally for
    /// the flag flip. Returns `true` iff this call flipped the flag (Python
    /// returns the (possibly mutated) card).
    pub fn upgrade(&mut self) -> bool {
        self.upgrade_with(|id, up| crate::lookup_card_factory().and_then(|f| f(id, up)))
    }

    /// [`Self::upgrade`] in game build `version` (GH #793): the delta is the
    /// difference between that build's un-upgraded and upgraded factory
    /// builds, so a card whose `OnUpgrade` changed between builds (v0.111.0
    /// Reave +3 instead of +2, Mirage drops Exhaust instead of costing 1
    /// less, …) upgrades by the right amount. The default build is exactly
    /// [`Self::upgrade`].
    pub fn upgrade_for(&mut self, version: crate::GameVersion) -> bool {
        if version.is_default() {
            return self.upgrade();
        }
        // A card minted by a v0.107.1-only path first takes this build's
        // base values, so the build's delta lands on the build's base.
        self.normalize_for_version(version);
        self.upgrade_with(|id, up| crate::build_card_for_version(id, up, version))
    }

    /// Move a card POD minted with v0.107.1 values onto game build
    /// `version`'s values (GH #793): every POD field (cost, base damage,
    /// base block, type, target, keyword override) that still holds the
    /// v0.107.1 factory value for `(card_id, upgraded)` takes `version`'s
    /// factory value. A field the game already changed (a cost set to 0 for
    /// this turn, a Claw-buffed damage, …) is left alone.
    ///
    /// Idempotent: it only rewrites fields whose two build values differ, so
    /// a second call (or a copy of an already-moved card) finds nothing
    /// equal to the v0.107.1 value. No-op for the default build, for an id
    /// with no registered factory, and for every card whose POD did not
    /// change. Called where cards enter a combat (deck → draw pile, the
    /// spawn helpers) and before [`Self::upgrade_for`] applies its delta, so
    /// card construction sites that predate the multi-version port stay
    /// correct.
    pub fn normalize_for_version(&mut self, version: crate::GameVersion) {
        if version.is_default() {
            return;
        }
        let Some(factory) = crate::lookup_card_factory_for_version() else {
            return;
        };
        let Some(old) = factory(self.card_id, self.upgraded, crate::GameVersion::V0_107_1) else {
            return;
        };
        let Some(new) = factory(self.card_id, self.upgraded, version) else {
            return;
        };
        // v0.111.0: a cost an effect SET this combat (Confused / Snecko's
        // `EnergyCost.SetThisCombat(roll)`, decomp ConfusedPower.cs:42) is a
        // local absolute modifier, not the build's base cost, so it is never
        // re-based even when the roll happens to equal the v0.107.1 cost. An
        // in-combat upgrade (Bellows, `upgrade_for`) normalizes first and was
        // turning a rolled 1 on BeaconOfHope+ into the build's 2 (Ironclad mid
        // seed 1809, hand_costs[0] cs=1 rs=2). The default build never gets
        // here.
        if self.cost == old.cost && self.combat_var(VarKey::CostAbsolutelySet) == 0 {
            self.cost = new.cost;
        }
        if self.base_damage == old.base_damage {
            self.base_damage = new.base_damage;
        }
        if self.base_block == old.base_block {
            self.base_block = new.base_block;
        }
        if self.card_type == old.card_type {
            self.card_type = new.card_type;
        }
        if self.target_type == old.target_type {
            self.target_type = new.target_type;
        }
        if self.keyword_override == old.keyword_override {
            self.keyword_override = new.keyword_override;
        }
    }

    /// [`Self::downgrade`] in game build `version` — the exact inverse of
    /// [`Self::upgrade_for`]. The default build is exactly [`Self::downgrade`].
    pub fn downgrade_for(&mut self, version: crate::GameVersion) -> bool {
        if version.is_default() {
            return self.downgrade();
        }
        self.downgrade_with(|id, up| crate::build_card_for_version(id, up, version))
    }

    fn upgrade_with(&mut self, factory: impl Fn(CardId, bool) -> Option<Card>) -> bool {
        // C# `CardCmd.Upgrade` skips a card that isn't `IsUpgradable`
        // (`CardCmd.cs:273-276`), and every gameplay upgrade goes through it
        // (Bellows, Bone Tea, Armaments+, Apotheosis, the potions, the rest
        // site, …). Gating here rather than at each caller means a curse,
        // status or Quest card is never upgraded on ANY path: Bellows used to
        // upgrade Ascender's Bane (`MaxUpgradeLevel => 0`,
        // `AscendersBane.cs:10`) along with the rest of the opening hand.
        if !self.is_upgradable() {
            return false;
        }
        self.upgraded = true;
        // Apply the upgrade as an additive *delta* on top of the current
        // POD stats, rather than overwriting them with the freshly built
        // upgraded spec. The delta is the difference between the
        // un-upgraded and upgraded factory builds (sts2-content's
        // `card_pod_from_id(id, _)`, which applies the generated
        // `upgrade_delta`). Mirrors the C# decomp (authoritative), where
        // `OnUpgrade` calls `DynamicVar.UpgradeValueBy(n)` /
        // `EnergyCost.UpgradeBy(n)` — additive on the *current* base value,
        // not a reset to the upgraded constant. See
        // `MegaCrit.Sts2.Core.Models.Cards/{Claw,StrikeRegent,Zap}.cs`.
        //
        // Why delta, not overwrite (bead `sts2-rs-55nxa`): a handful of
        // cards permanently mutate `base_damage` *during* combat — Claw
        // (`+Increase` per play, defect.rs) and Sovereign Blade forge
        // (regent.rs). Overwriting from the fresh factory discarded those
        // accumulated stacks if the card was upgraded after the buff (e.g.
        // an Armaments-style upgrade-in-hand). Applying the delta preserves
        // them: `current_base + (upgraded_spec - base_spec)`. For an
        // un-buffed card the result is identical to the old overwrite, so
        // this is a strict superset of the prior behaviour. Instance state
        // (uid, combat_vars, enchantments, energy_spent, base_replay_count)
        // is preserved as before. Bead `sts2-rs-vd6pf` introduced the
        // rewrite; `sts2-rs-55nxa` made it additive.
        //
        // If no factory is registered (e.g. core-only unit tests) or the id
        // is unknown, the flag flip alone is the graceful fallback — exactly
        // the prior behaviour.
        {
            if let (Some(base), Some(upgraded)) =
                (factory(self.card_id, false), factory(self.card_id, true))
            {
                self.apply_upgrade_delta(&base, &upgraded);
            }
        }
        true
    }

    /// The additive upgrade delta shared by [`Self::upgrade`] and
    /// [`Self::upgrade_for`]: `base` / `upgraded` are the un-upgraded and
    /// upgraded factory builds of this card's id.
    fn apply_upgrade_delta(&mut self, base: &Card, upgraded: &Card) {
        let cost_delta = upgraded.cost - base.cost;
        if self.combat_var(VarKey::CostAbsolutelySet) != 0 {
            // C# `CardEnergyCost.UpgradeBy` (CardEnergyCost.cs:179-200):
            // the upgrade mutates the BASE; an Absolute local modifier
            // (Confused/SneckoOil roll, held in `self.cost` in the
            // collapsed model) keeps owning the evaluated cost, except
            // that a LOWERED base clamps every absolute modifier above
            // it down to the new base. Re-point any banked Snecko
            // delta at the new base so the WhenPlayed / turn-start
            // expiry restores to it (C#: dropping the modifier reveals
            // `_base`).
            if cost_delta < 0 {
                let new_base = upgraded.cost.max(0);
                self.cost = self.cost.min(new_base);
                if self.combat_var(VarKey::SneckoRollLive) != 0
                    || self.combat_var(VarKey::SneckoCostDeltaThisTurn) != 0
                {
                    self.set_combat_var(
                        VarKey::SneckoCostDeltaThisTurn,
                        i32::from(self.cost) - i32::from(new_base),
                    );
                }
            }
            // cost_delta >= 0: the absolute modifier still owns the
            // evaluated cost — leave `self.cost` untouched.
        } else if base.cost >= 0 {
            // C# `UpgradeBy` moves `_base` and keeps the Relative
            // `AddThisCombat` modifiers, then resolves `max(0, base +
            // modifiers)`: the shift lands on the unclamped sum, which the
            // collapsed model holds as `cost - CostDebtThisCombat`. A
            // negative `cost` is the X-cost sentinel, so it never goes below
            // 0 (act23 Necrobinder:1014: Banshee's Cry at 0 upgraded to -2
            // and the play spent all 4 energy as an X cost).
            self.add_cost_this_combat(i32::from(cost_delta));
        } else {
            self.cost = self.cost.saturating_add(cost_delta);
        }
        self.base_damage = self
            .base_damage
            .saturating_add(upgraded.base_damage - base.base_damage);
        self.base_block = self
            .base_block
            .saturating_add(upgraded.base_block - base.base_block);
        // Bead `sts2-rs-59atd`: carry the upgrade-aware keyword set
        // forward. The factory's upgraded build runs
        // `apply_spec_upgrade`, which stamps `keyword_override` from
        // the `CardUpgradeDelta.keywords` table for the ~27 cards
        // whose keywords change on upgrade (Aggression gains INNATE,
        // BurningPact drops EXHAUST, …). Cards with no keyword delta
        // leave `keyword_override == None` and continue to defer to
        // the `CardId`-keyed registries. Unlike the stat fields this
        // is an absolute set, not an additive delta — the upgraded
        // build already encodes the final keyword set.
        //
        // C# `UpgradeInternal` only runs the card's `OnUpgrade`, which
        // adds/removes the keywords it names (Rainbow: `RemoveKeyword(
        // Exhaust)`) on the LIVE set: a keyword gained in combat (Choices
        // Paradox's Retain) survives the upgrade (loadout Defect v0.111.0
        // 2015: a Bellows-upgraded Retain Rainbow lost its Retain). Apply
        // the base -> upgraded keyword diff to the current set.
        if let Some(up) = upgraded.keyword_override {
            let registry = |c: &Card| crate::card_effects::registry_keyword_override(c.card_id);
            let base_kw = base.keyword_override.unwrap_or_else(|| registry(base));
            let current = self.keyword_override.unwrap_or(base_kw);
            let removed = base_kw.0 & !up.0;
            let added = up.0 & !base_kw.0;
            self.keyword_override = Some(KeywordOverride((current.0 & !removed) | added));
        }
    }

    /// Revert a previously-upgraded card to its un-upgraded form. The
    /// exact inverse of [`Self::upgrade`]: it subtracts the same
    /// `upgrade_delta` (built from the registered card factory) that
    /// `upgrade` added, and restores the un-upgraded keyword set.
    /// Instance state (uid, combat_vars, enchantments, …) is preserved.
    ///
    /// Used by the `Reflections` event (`downgrade 2, upgrade 4`),
    /// which is the only deck-mutation surface that downgrades. STS2
    /// cards carry a single `upgraded` flag (no multi-level upgrades),
    /// so a downgrade is always a full revert. Returns `true` iff this
    /// call flipped the flag (no-op + `false` for an already-base card).
    ///
    /// If no factory is registered (core-only unit tests) or the id is
    /// unknown, the flag flip alone is the graceful fallback — the
    /// symmetric counterpart of [`Self::upgrade`]'s fallback.
    pub fn downgrade(&mut self) -> bool {
        self.downgrade_with(|id, up| crate::lookup_card_factory().and_then(|f| f(id, up)))
    }

    fn downgrade_with(&mut self, factory: impl Fn(CardId, bool) -> Option<Card>) -> bool {
        if !self.upgraded {
            return false;
        }
        self.upgraded = false;
        {
            if let (Some(base), Some(upgraded)) =
                (factory(self.card_id, false), factory(self.card_id, true))
            {
                self.revert_upgrade_delta(&base, &upgraded);
            }
        }
        // C# `DowngradeInternal` (`CardModel.cs:2149-2162`) resets `_keywords`
        // to the canonical Local set, so a keyword `CardCmd.ApplyKeyword`
        // added (Ghost Seed's / Music Box's Ethereal, modelled as this combat
        // var) is gone and nothing re-applies it.
        self.combat_vars.zero(VarKey::EtherealThisCombat);
        true
    }

    fn revert_upgrade_delta(&mut self, base: &Card, upgraded: &Card) {
        if base.cost >= 0 && self.combat_var(VarKey::CostAbsolutelySet) == 0 {
            // C# `ResetForDowngrade` restores `_base = Canonical` and keeps the
            // Relative `AddThisCombat` modifiers, so the cost re-resolves to
            // `max(0, base + modifiers)` (CardEnergyCost.cs GetWithModifiers).
            // The shift lands on the unclamped sum, `cost - CostDebtThisCombat`:
            // adding it to the floored `cost` alone over-charged a Banshee's
            // Cry shaved below 0 (loadout Necrobinder 1006, Dampen), and
            // resetting `cost` but keeping the debt under-charged it
            // (v0.107.1 3241: 9 - 4 x 2 = 1 in C#, 0 in Rust).
            self.add_cost_this_combat(i32::from(base.cost) - i32::from(upgraded.cost));
        } else {
            self.cost = self.cost.saturating_sub(upgraded.cost - base.cost);
        }
        self.base_damage = self
            .base_damage
            .saturating_sub(upgraded.base_damage - base.base_damage);
        self.base_block = self
            .base_block
            .saturating_sub(upgraded.base_block - base.base_block);
        // Restore the un-upgraded keyword set (absolute, not a
        // delta) — `None` for all but the ~27 keyword-changing
        // cards, which is exactly the base build's value.
        self.keyword_override = base.keyword_override;
    }

    /// Deterministic deep-clone with a caller-supplied `seed` used as the
    /// new instance UID. Mirrors Python
    /// `CardInstance.clone(new_id)` at
    /// `sts2-rl-agent@01c094d:sts2_env/cards/base.py:115-140` — Python
    /// passes a fresh `instance_id` (from `_get_next_id()`) so the
    /// clone is distinguishable from its source in pile bookkeeping.
    ///
    /// We accept a `u64` seed rather than wrapping a [`CardUid`]
    /// directly because the relics that exercise this surface
    /// (`FakeStrikeDummy`, `BoneTea`, `HistoryCourse`) drive cloning from
    /// the engine RNG (`Xoshiro256PlusPlus::next_u64()`). The seed is
    /// reduced via wrapping to a non-zero `u32` so the resulting
    /// [`CardUid`] is always constructible; the engine's UID generator
    /// (`combat_loop`) remains the canonical source for production code.
    ///
    /// **Determinism**: same `self` + same `seed` always produces the
    /// same clone (load-bearing for parity fixtures).
    #[must_use]
    pub fn clone_with_seed(&self, seed: u64) -> Self {
        // Reduce `seed` to a non-zero u32. The XOR with the high half
        // spreads entropy; the `.max(1)` keeps the value non-zero (a
        // pathological `seed = 0` would otherwise produce `0`).
        let folded = ((seed & 0xFFFF_FFFF) as u32) ^ ((seed >> 32) as u32);
        let nz =
            std::num::NonZeroU32::new(folded.max(1)).expect("folded seed forced non-zero above");
        let mut cloned = *self;
        cloned.uid = crate::CardUid(nz);
        cloned
    }

    /// Drop every per-combat scratch variable. Mirrors
    /// `reset_combat_enchantments` in `enchantments.py:76-79` (which clears
    /// keys prefixed with `_enchant_`) — in Rust we keyed those via
    /// `VarKey`, so the equivalent is the broader combat-vars reset.
    pub fn reset_combat_vars(&mut self) {
        self.combat_vars.clear();
        self.energy_spent = 0;
    }

    /// `true` iff this card uses the X-cost energy-spend convention
    /// (`cost == -1` AND not an `UNPLAYABLE` Curse/Status sentinel).
    /// Used by `play_card` to decide whether to drain `state.player.energy`
    /// into [`Self::energy_spent`] prior to dispatch. Mirrors Python's
    /// `cost == -1` X-cost shape across `cards/silent.py:Skewer`,
    /// `cards/regent.py:HeavenlyDrill`, `cards/defect.py:Tempest /
    /// MultiCast`, and `cards/ironclad.py:Whirlwind`.
    #[inline]
    #[must_use]
    pub const fn is_x_cost(&self) -> bool {
        self.cost == -1 && !matches!(self.card_type, CardType::Curse | CardType::Status)
    }
}

impl CardId {
    /// True iff this card's C# `CanonicalTags` include `CardTag.OstyAttack`
    /// — the 13 Necrobinder cards whose damage is dealt **by the Osty**
    /// (`DamageCmd.Attack(...).FromOsty(...)`), not the player.
    ///
    /// The OstyAttack tag is a cosmetic glow flag that isn't carried on the
    /// runtime `CardSpec`, so this `CardId` predicate stands in for C#
    /// `card.Tags.Contains(CardTag.OstyAttack)`. It is the single source of
    /// truth shared by `sts2-content`'s `card_is_osty_attack` and the
    /// `after_card_played` Vigor/Gigantification consume gate in `hooks.rs`:
    /// `VigorPower.BeforeAttack`/`AfterAttack` only latch+consume when
    /// `command.Attacker == Owner` (the player), so an Osty-dealt attack
    /// must NOT consume the player's Vigor (Necrobinder Osty-attack cards
    /// SQUEEZE/RIGHT_HAND/… wrongly spent Akabeko Vigor end-to-end).
    #[inline]
    #[must_use]
    pub const fn is_osty_attack(self) -> bool {
        matches!(
            self,
            CardId::BoneShards
                | CardId::Fetch
                | CardId::Flatten
                | CardId::HighFive
                | CardId::Poke
                | CardId::Protector
                | CardId::Rattle
                | CardId::RightHandHand
                | CardId::SicEm
                | CardId::Snap
                | CardId::Squeeze
                | CardId::SweepingGaze
                | CardId::Unleash
        )
    }
}

/// The card ids [`CardStore`] tracks presence of (J02), one bit each. Every
/// one gates an O(cards) sweep that acts only on cards with that id: the
/// Stomp / Pinpoint discounts and their turn-start restores, Melancholy's
/// on-death discount, the Bolas / ThrummingHatchet return-to-hand scan, and
/// Banshee's Cry's Ethereal-play discount.
const fn card_gate_bit(id: CardId) -> u8 {
    match id {
        CardId::Stomp => 1,
        CardId::Pinpoint => 1 << 1,
        CardId::Melancholy => 1 << 2,
        CardId::Bolas => 1 << 3,
        CardId::ThrummingHatchet => 1 << 4,
        CardId::BansheesCry => 1 << 5,
        _ => 0,
    }
}

/// The OR of [`card_gate_bit`] over `cards`.
fn card_gate_bits_of(cards: &[Card]) -> u8 {
    cards
        .iter()
        .fold(0, |acc, c| acc | card_gate_bit(c.card_id))
}

/// Vector-backed arena over [`Card`]. Indexed by [`CardUid`] in pile
/// commands; UIDs are 1-based so `cards[uid.get() as usize - 1]` is the
/// canonical lookup pattern (formalised in bead P1-2).
///
/// Replaces the former `type CardStore = Vec<Card>` (J02) to carry one view
/// derived from the arena: which of the gate ids (`card_gate_bit`) some
/// card holds, so [`CardStore::holds_id`] answers "is there a Stomp anywhere
/// in this combat" with one bit test instead of an arena scan. The arena is
/// append-only during a combat, and a transform allocates a fresh row rather
/// than rewriting `card_id`, so every structural write goes through a method
/// here that keeps the bits (`push`, `extend`, `clear`, `From<Vec<Card>>`, …)
/// and the read side derefs to `[Card]`, not `Vec`. `card_id` is still a
/// public field, so `&mut [Card]` could rewrite it in place; nothing in
/// production does, and debug builds recompute the bits at every
/// [`crate::apply`] entry and on every [`CardStore::holds_id`] and assert
/// they match ([`CardStore::debug_assert_gate_bits`]).
///
/// [`PartialEq`] and [`Debug`](std::fmt::Debug) look at the cards only (the
/// bits are derived), so equality and the printed form are those of the old
/// `Vec<Card>`.
#[derive(Clone, Default)]
pub struct CardStore {
    cards: Vec<Card>,
    gate_bits: u8,
}

impl PartialEq for CardStore {
    #[inline]
    fn eq(&self, other: &Self) -> bool {
        self.cards == other.cards
    }
}
impl Eq for CardStore {}

impl std::fmt::Debug for CardStore {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        std::fmt::Debug::fmt(&self.cards, f)
    }
}

impl core::ops::Deref for CardStore {
    type Target = [Card];
    #[inline]
    fn deref(&self) -> &[Card] {
        &self.cards
    }
}
impl core::ops::DerefMut for CardStore {
    #[inline]
    fn deref_mut(&mut self) -> &mut [Card] {
        // Element mutation only. No structural op is reachable through a
        // slice; a `card_id` write through it is caught by the debug drift
        // assert at `apply` entry.
        &mut self.cards
    }
}

impl CardStore {
    /// Empty store.
    #[inline]
    #[must_use]
    pub const fn new() -> Self {
        Self {
            cards: Vec::new(),
            gate_bits: 0,
        }
    }

    /// Empty store with arena capacity reserved.
    #[inline]
    #[must_use]
    pub fn with_capacity(cap: usize) -> Self {
        Self {
            cards: Vec::with_capacity(cap),
            gate_bits: 0,
        }
    }

    /// Append a card (the next arena row).
    #[inline]
    pub fn push(&mut self, card: Card) {
        self.gate_bits |= card_gate_bit(card.card_id);
        self.cards.push(card);
    }

    /// Drop every card.
    #[inline]
    pub fn clear(&mut self) {
        self.cards.clear();
        self.gate_bits = 0;
    }

    /// Shorten the arena to `len` cards (no-op if it is not longer).
    pub fn truncate(&mut self, len: usize) {
        self.cards.truncate(len);
        self.gate_bits = card_gate_bits_of(&self.cards);
    }

    /// True iff some card in the arena has `card_id == id`, answered by one
    /// bit test. `id` must be a tracked gate id (`card_gate_bit`).
    ///
    /// # Panics
    /// In debug builds, if `id` is not tracked, or if the stored bits
    /// disagree with an arena scan (a `card_id` write bypassed the store).
    #[inline]
    #[must_use]
    pub fn holds_id(&self, id: CardId) -> bool {
        let bit = card_gate_bit(id);
        debug_assert!(bit != 0, "CardStore does not track {id:?}");
        let held = self.gate_bits & bit != 0;
        #[cfg(debug_assertions)]
        assert_eq!(
            held,
            self.cards.iter().any(|c| c.card_id == id),
            "CardStore gate bit for {id:?} disagrees with the arena scan"
        );
        held
    }

    /// Debug drift guard: the gate bits still equal a recompute from the
    /// arena. Fires if a `card_id` write bypassed the store's methods
    /// through `&mut [Card]`.
    ///
    /// # Panics
    /// If the bits drifted.
    #[cfg(debug_assertions)]
    pub fn debug_assert_gate_bits(&self) {
        assert_eq!(
            self.gate_bits,
            card_gate_bits_of(&self.cards),
            "CardStore gate bits drifted from the arena: a `card_id` write went \
             through `&mut [Card]` instead of a CardStore method"
        );
    }

    /// Borrow the arena as a slice (explicit form of the `Deref`).
    #[inline]
    #[must_use]
    pub fn as_slice(&self) -> &[Card] {
        &self.cards
    }

    /// Unwrap into the card `Vec`.
    #[inline]
    #[must_use]
    pub fn into_vec(self) -> Vec<Card> {
        self.cards
    }
}

impl From<Vec<Card>> for CardStore {
    #[inline]
    fn from(cards: Vec<Card>) -> Self {
        let gate_bits = card_gate_bits_of(&cards);
        Self { cards, gate_bits }
    }
}

impl<const N: usize> From<[Card; N]> for CardStore {
    #[inline]
    fn from(cards: [Card; N]) -> Self {
        Self::from(Vec::from(cards))
    }
}

impl FromIterator<Card> for CardStore {
    fn from_iter<I: IntoIterator<Item = Card>>(iter: I) -> Self {
        Self::from(iter.into_iter().collect::<Vec<Card>>())
    }
}

impl Extend<Card> for CardStore {
    fn extend<I: IntoIterator<Item = Card>>(&mut self, iter: I) {
        for card in iter {
            self.push(card);
        }
    }
}

impl IntoIterator for CardStore {
    type Item = Card;
    type IntoIter = std::vec::IntoIter<Card>;
    #[inline]
    fn into_iter(self) -> Self::IntoIter {
        self.cards.into_iter()
    }
}

impl<'a> IntoIterator for &'a CardStore {
    type Item = &'a Card;
    type IntoIter = core::slice::Iter<'a, Card>;
    #[inline]
    fn into_iter(self) -> Self::IntoIter {
        self.cards.iter()
    }
}

impl<'a> IntoIterator for &'a mut CardStore {
    type Item = &'a mut Card;
    type IntoIter = core::slice::IterMut<'a, Card>;
    #[inline]
    fn into_iter(self) -> Self::IntoIter {
        self.cards.iter_mut()
    }
}

// ---------------------------------------------------------------------------
// Pile primitives
// ---------------------------------------------------------------------------

/// Which pile a card lives in. `Play` is the transient "currently resolving"
/// pile — Python keeps cards there for the duration of `play()` so that
/// triggers fired mid-resolution can observe the played card.
///
/// The exhaustiveness of this enum is load-bearing: every primitive below
/// matches on every variant, so adding a new pile causes a compile error
/// (asserted by `pile_kind_exhaustive_match` in tests).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum PileKind {
    Hand,
    Draw,
    Discard,
    Exhaust,
    Play,
}

/// Hard limit on hand size. Mirrors Python's `MAX_HAND_SIZE = 10`. Cards
/// drawn while at the limit are discarded immediately; this is implemented
/// in bead P1-2.
pub const HAND_LIMIT: usize = 10;

/// Errors returned by pile primitives.
#[derive(Debug, thiserror::Error, PartialEq, Eq)]
pub enum PileError {
    #[error("card uid {0:?} not found in pile {1:?}")]
    NotInPile(CardUid, PileKind),
}

/// Number of cards currently in `pile`.
#[inline]
#[must_use]
pub fn pile_len(player: &PlayerCombatState, pile: PileKind) -> usize {
    match pile {
        PileKind::Hand => player.hand.len(),
        PileKind::Draw => player.draw.len(),
        PileKind::Discard => player.discard.len(),
        PileKind::Exhaust => player.exhaust.len(),
        PileKind::Play => player.play.len(),
    }
}

/// Iterate over the [`CardUid`]s currently in `pile`, in pile order.
pub fn pile_iter(player: &PlayerCombatState, pile: PileKind) -> impl Iterator<Item = CardUid> + '_ {
    let slice: &[CardUid] = match pile {
        PileKind::Hand => &player.hand,
        PileKind::Draw => &player.draw,
        PileKind::Discard => &player.discard,
        PileKind::Exhaust => &player.exhaust,
        PileKind::Play => &player.play,
    };
    slice.iter().copied()
}

/// Move `uid` from `from` to `to`. Order within `from` is preserved for the
/// remaining cards (we use `remove`, not `swap_remove`, since pile order is
/// observable — discard pile order matters for shuffle parity, and hand
/// order is the Python convention for `hand_index` in `Action::PlayCard`).
///
/// `to == from` is treated as a no-op (still validates that `uid` is in
/// `from`).
pub fn move_card(
    player: &mut PlayerCombatState,
    uid: CardUid,
    from: PileKind,
    to: PileKind,
) -> Result<(), PileError> {
    // Locate index in `from` first so we can fail fast without mutating.
    let idx = pile_slice(player, from)
        .iter()
        .position(|&c| c == uid)
        .ok_or(PileError::NotInPile(uid, from))?;

    // Remove from source, then push to destination. Two separate mutable
    // borrows because the SmallVec inline capacities differ between piles
    // (16/32/8), so we cannot return a single concrete `&mut SmallVec` type.
    let removed = pop_index(player, from, idx);
    debug_assert_eq!(removed, uid);
    push_pile(player, to, uid);
    Ok(())
}

/// Whether the player's hand is at or above [`HAND_LIMIT`].
#[inline]
#[must_use]
pub fn is_hand_full(player: &PlayerCombatState) -> bool {
    player.hand.len() >= HAND_LIMIT
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/// Immutable view of a pile as a slice. Kept private; callers go through
/// [`pile_iter`] / [`pile_len`].
fn pile_slice(player: &PlayerCombatState, pile: PileKind) -> &[CardUid] {
    match pile {
        PileKind::Hand => &player.hand,
        PileKind::Draw => &player.draw,
        PileKind::Discard => &player.discard,
        PileKind::Exhaust => &player.exhaust,
        PileKind::Play => &player.play,
    }
}

/// Remove the element at `idx` from `pile`. Caller must ensure `idx` is in
/// bounds (validated by [`move_card`] beforehand). Order of remaining cards
/// is preserved (matters for shuffle parity / play-order of hand).
fn pop_index(player: &mut PlayerCombatState, pile: PileKind, idx: usize) -> CardUid {
    match pile {
        PileKind::Hand => player.hand.remove(idx),
        PileKind::Draw => player.draw.remove(idx),
        PileKind::Discard => player.discard.remove(idx),
        PileKind::Exhaust => player.exhaust.remove(idx),
        PileKind::Play => player.play.remove(idx),
    }
}

/// Push `uid` onto the back of `pile`.
fn push_pile(player: &mut PlayerCombatState, pile: PileKind, uid: CardUid) {
    match pile {
        PileKind::Hand => player.hand.push(uid),
        PileKind::Draw => player.draw.push(uid),
        PileKind::Discard => player.discard.push(uid),
        PileKind::Exhaust => player.exhaust.push(uid),
        PileKind::Play => player.play.push(uid),
    }
}

// ---------------------------------------------------------------------------
// Pile commands (P1-2 / sts2-rs-8l3)
// ---------------------------------------------------------------------------

/// Whether pile tracing is on (env `STS2_TRACE_PILES` set). Cached once so
/// the gate is a single load on the hot `move_card` path — the previous
/// per-call `env::var_os` was a real `getenv(3)` syscall-free-but-linear
/// environ scan showing at ~0.6% of MCTS-search instructions
/// (2026-07-03 realistic-deck callgrind). Mirrors `rng_trace_enabled`.
pub(crate) fn pile_trace_enabled() -> bool {
    use std::sync::OnceLock;
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| std::env::var_os("STS2_TRACE_PILES").is_some())
}

/// Emit a `PILETRACE` line (gated on `STS2_TRACE_PILES`) mirroring the C#
/// headless `RngTracePatches.{AutoPlayPilePrefix,ShufflePilePrefix}`. Keyed by
/// the player's `shuffle`-stream counter so the two engines' per-sub-step pile
/// snapshots align by the SAME (shuffle ctr, event-ordinal) the RNG trace uses.
/// Built to diagnose the auto-play-from-draw pool-divergence family (Cascade /
/// Catastrophe / Havoc / Mayhem / DistilledChaos), where the RNG stream can
/// match yet the draw-pile *contents* diverge — invisible to `RNGTRACE` alone
/// (#184). Zero-cost when the env var is unset.
pub fn emit_pile_trace(
    player: &PlayerCombatState,
    cards: &CardStore,
    evt: &str,
    shufctr: u32,
    card: Option<CardUid>,
) {
    if !pile_trace_enabled() {
        return;
    }
    let name = |uid: &CardUid| -> String {
        cards
            .get(uid.get() as usize - 1)
            .map_or_else(String::new, |c| {
                format!(
                    "{}{}",
                    c.card_id.to_python_name(),
                    if c.upgraded { "+" } else { "" }
                )
            })
    };
    let pile = |p: &[CardUid]| -> String {
        format!("[{}]", p.iter().map(&name).collect::<Vec<_>>().join(","))
    };
    let cardstr = card.map_or_else(String::new, |u| name(&u));
    eprintln!(
        "PILETRACE evt={evt} shufctr={shufctr} card={cardstr} draw={} hand={} discard={} exhaust={} play={}",
        pile(&player.draw),
        pile(&player.hand),
        pile(&player.discard),
        pile(&player.exhaust),
        pile(&player.play),
    );
}

/// Shuffle the player's draw pile in place using the engine RNG.
///
/// Direct port of `rand.shuffle(state.draw)` invocations in
/// `sts2-rl-agent@01c094d:sts2_env/core/combat.py:1139` — used by
/// `_shuffle_if_needed` after copying discard into draw, and by any
/// effect that explicitly shuffles the draw pile (cards/relics that
/// "shuffle the draw pile").
///
/// No-op when the draw pile has fewer than two cards.
///
/// **Pinned-position preservation** (bead `sts2-rs-o6xw`): cards listed in
/// `player.pinned_top` and `player.pinned_bottom` retain their
/// declared positions across the shuffle. The non-pinned subset is
/// shuffled in-place and the pinned cards are re-inserted at their
/// declared offsets. This is critical for MCTS PIMC determinization:
/// effects like Headbutt (top-of-draw) make positions KNOWN, and a
/// naive shuffle would scramble them — mis-ranking pinning-card
/// combos in the search.
///
/// Stale pin entries (UIDs no longer in `draw` because the card was
/// drawn or moved between piles outside of [`draw`] / the
/// pile-command path) are silently filtered out — pin lifetime is
/// best-effort and a defensive shuffle pass is the natural cleanup
/// site. Real consumers (Headbutt's PendingChoice resolver,
/// [`draw`] itself, [`discard_pile_into_draw_pile`]) maintain the
/// invariant in the common path.
pub fn shuffle(player: &mut PlayerCombatState, rng: &mut CombatRng) {
    if player.draw.len() < 2 {
        return;
    }
    // Bead `sts2-rs-09x5n` (F2 `HiddenInfoMode::BeliefDraw`, lightspeed
    // `CardPile` port): an order-dissolving mutation on a deferred-draw-order
    // pile re-sorts the unknown middle segment into its canonical
    // (uid-ascending) form instead of physically shuffling it, consuming NO
    // RNG — the random CHOICE of draw order is deferred to draw time
    // (`crate::cards::draw`), never sampled here. This covers every caller
    // of `shuffle` uniformly: the auto-reshuffle
    // (`discard_pile_into_draw_pile_signaling`) and the explicit `Shuffle`
    // command (`shuffle_draw_and_discard`, Reboot/BottledPotential) both
    // delegate here, so both order-dissolving events get the same treatment
    // for free. Reuses [`crate::blindfold::canonicalize_unknown_middle`] —
    // the SAME canonicalization [`crate::blindfold::belief_root`] uses for
    // the root — so there is exactly one canonical ordering in the engine,
    // not two competing definitions.
    if player.deferred_draw_order {
        crate::blindfold::canonicalize_unknown_middle(player);
        return;
    }
    // Fast path: no pins -> identical to the legacy single-call shuffle.
    if player.pinned_top.is_empty() && player.pinned_bottom.is_empty() {
        rng.shuffle(player.draw.as_mut_slice());
        return;
    }
    // Drop stale pin entries (not currently in draw). This is the
    // canonical sweep site; the common-case insert/remove paths keep
    // the invariant cheaply.
    player.pinned_top.retain(|uid| player.draw.contains(uid));
    player.pinned_bottom.retain(|uid| player.draw.contains(uid));
    // Snapshot ordering for re-insertion. Stack-allocated for typical
    // pin counts (<=4 each).
    let top: SmallVec<[CardUid; 4]> = player.pinned_top.clone();
    let bot: SmallVec<[CardUid; 4]> = player.pinned_bottom.clone();
    // Build the unpinned middle in original draw order. SmallVec inline
    // 32 keeps the typical sub-60-card draw on the stack.
    let mut middle: SmallVec<[CardUid; 32]> = SmallVec::new();
    for &uid in &player.draw {
        if !top.contains(&uid) && !bot.contains(&uid) {
            middle.push(uid);
        }
    }
    if middle.len() >= 2 {
        rng.shuffle(middle.as_mut_slice());
    }
    // Reconstruct `top + middle + bot` in place.
    player.draw.clear();
    player.draw.extend(top.iter().copied());
    player.draw.extend(middle.iter().copied());
    player.draw.extend(bot.iter().copied());
}

/// Returns the UIDs of the "unknown middle" segment of `player.draw` —
/// the sub-sequence NOT covered by `pinned_top` / `pinned_bottom` — in
/// their current draw-pile order. This is exactly the segment [`shuffle`]
/// permutes (and the [`crate::blindfold`] canonicalization sorts). Bead
/// `sts2-rs-i8bgu` (F1 `HiddenInfoMode::DrawChance`) draw-order detection,
/// per-outcome pile realization, and chance-outcome dedup all extract
/// this same segment — they must agree with [`shuffle`] on exactly which
/// cards are "unknown" or the guarantees decouple.
///
/// Read-only: unlike [`shuffle`], this does not sweep stale pin entries
/// (UIDs listed in `pinned_top`/`pinned_bottom` that are no longer in
/// `draw`) — a stale entry never matches any UID actually iterated here,
/// so the result is correct regardless.
#[must_use]
pub fn unknown_middle_uids(player: &PlayerCombatState) -> SmallVec<[CardUid; 32]> {
    if player.pinned_top.is_empty() && player.pinned_bottom.is_empty() {
        return player.draw.iter().copied().collect();
    }
    player
        .draw
        .iter()
        .copied()
        .filter(|uid| !player.pinned_top.contains(uid) && !player.pinned_bottom.contains(uid))
        .collect()
}

/// Pop the next card off a non-empty draw pile, honoring
/// [`PlayerCombatState::deferred_draw_order`] (bead `sts2-rs-09x5n`, F2
/// `HiddenInfoMode::BeliefDraw`, lightspeed `CardPile::drawTop` port).
///
/// When the flag is `false` (every pre-bead / env-visible state —
/// `#[derive(Default)]`), this is byte-identical to the historical
/// `player.draw.remove(0)`.
///
/// When `true`: [`PlayerCombatState::pinned_top`] still pops first
/// (player-KNOWN information — deterministic, no RNG), and
/// [`PlayerCombatState::pinned_bottom`] still pops last once the middle is
/// exhausted; but the "unknown" middle segment (kept CANONICAL —
/// uid-sorted, never physically shuffled — by [`shuffle`] and every other
/// order-dissolving mutation) draws a uniformly random ELEMENT instead of
/// always taking the front. A singleton unknown segment draws
/// deterministically with **no** RNG read (mirrors
/// [`crate::belief_pile::BeliefDrawPile::draw_top`]'s singleton
/// normalization) — this is exactly what makes the existing RNG-counter-
/// fingerprint chance detector in `sts2-mcts` (`combat_counter_fingerprint`)
/// fire precisely when a draw is genuinely uncertain (segment len >= 2) and
/// never for a forced/deterministic draw, with zero new detector code
/// (see `lightspeed-findings.md`).
///
/// Consumes the SAME RNG stream (`rng`, i.e. `run_rng.shuffle` at every real
/// call site) the empty-pile auto-reshuffle uses, so a chance node born from
/// a deferred draw and one born from a reshuffle are indistinguishable to
/// the detector — both are "the shuffle stream moved".
///
/// Panics if `player.draw` is empty — callers check first, mirroring the
/// unchecked `draw.remove(0)` this replaces.
pub(crate) fn pop_next_card(player: &mut PlayerCombatState, rng: &mut CombatRng) -> CardUid {
    if !player.deferred_draw_order {
        return player.draw.remove(0);
    }
    // Staleness guard (final-review finding, bead `sts2-rs-ztl78`): a raw
    // `draw.remove(pos)` elsewhere that bypasses this function (and forgets
    // to call `unpin`) can leave a `pinned_top`/`pinned_bottom` entry whose
    // uid no longer physically exists in `player.draw` — e.g. a content
    // resolver that raw-removes a card sitting at the pinned slot. Sweep
    // both pin lists before trusting them — mirrors the retain-sweep already
    // used by `shuffle` / `crate::blindfold::canonicalize_unknown_middle` /
    // `insert_into_unknown_sorted`. A valid pin still pops deterministically
    // with zero RNG below; a swept-empty pin list falls through to the
    // normal middle-segment logic, so the RNG contract is unchanged.
    player.pinned_top.retain(|uid| player.draw.contains(uid));
    player.pinned_bottom.retain(|uid| player.draw.contains(uid));
    if !player.pinned_top.is_empty() {
        return player.draw.remove(0);
    }
    let bottom_len = player.pinned_bottom.len();
    let middle_len = player.draw.len().saturating_sub(bottom_len);
    if middle_len == 0 {
        // Unknown segment exhausted; only the known-bottom stack remains.
        return player.draw.remove(0);
    }
    let idx = if middle_len == 1 {
        0
    } else {
        // Fresh RNG consumption per draw — the random choice is deferred to
        // HERE, never pre-committed by a shuffle. Removing from a sorted
        // sub-range preserves the sortedness of what remains.
        rng.next_int(0, (middle_len - 1) as i32) as usize
    };
    player.draw.remove(idx)
}

/// Pop the PHYSICAL TOP card of a non-empty draw pile for an effect that
/// takes "the top card" without drawing it — C#
/// `CardPileCmd.AutoPlayFromDrawPile(.., CardPilePosition.Top, ..)`'s
/// `drawPile.Cards.FirstOrDefault()` (Havoc, Cascade, Distilled Chaos,
/// Mayhem, I Am Invincible) and ToastyMittens' exhaust-top. GH #785.
///
/// Under [`PlayerCombatState::deferred_draw_order`] the physical top of
/// the unknown middle is not `draw[0]`: that segment is kept CANONICAL
/// (uid-sorted), so `draw[0]` is merely its lowest-uid card. "The top
/// card" is the same random variable "the next card drawn" is, so this
/// delegates to [`pop_next_card`] — a known `pinned_top` card pops
/// deterministically with no RNG, a >=2-card unknown middle samples
/// uniformly and consumes the shuffle stream (the search's chance node),
/// and the known-bottom stack goes last. It then clears the popped card's
/// pin, exactly as a draw does.
///
/// With the flag clear (every clairvoyant / parity / fixture state) this is
/// `draw.remove(0)` plus the `unpin` — byte-identical to the raw pop each
/// call site used to hand-write, with no RNG read.
///
/// Panics if `player.draw` is empty — callers check first.
pub(crate) fn pop_top_card(player: &mut PlayerCombatState, rng: &mut CombatRng) -> CardUid {
    let uid = pop_next_card(player, rng);
    unpin(player, uid);
    uid
}

/// PEEK at the physical top of the draw pile for an effect that only acts
/// when that card satisfies `pred`, leaving the card where it is: C#
/// `IAmInvincible.AfterAutoPostPlayPhaseEntered`'s
/// `drawPile.Cards.FirstOrDefault() == this`. Returns the top card when it
/// satisfies `pred`, `None` otherwise (or when the pile is empty). GH #785.
///
/// With [`PlayerCombatState::deferred_draw_order`] clear this reads
/// `draw[0]` and never mutates or touches RNG.
///
/// Under a deferred-order pile the top is only known when it is pinned, or
/// when the unknown middle has at most one card (the top is then that card,
/// or the first of the known-bottom stack). Otherwise "what is on top?" is
/// a chance event, resolved the way [`pop_next_card`] resolves a draw: one
/// RNG read picks a card from the unknown middle, which is then MOVED to
/// the physical top and PINNED there. The pin is what keeps the later draw
/// consistent with the peek: the card the peek saw on top is the card the
/// next pop takes, with no second RNG read.
///
/// If no card of the unknown middle satisfies `pred`, every possible top
/// gives the same answer, so this returns `None` WITHOUT reading RNG or
/// pinning anything. That matters because the I Am Invincible peek runs at
/// every turn end, whatever the deck: only a pile that can actually hold an
/// I Am Invincible on top forms a chance node.
///
/// Two caveats about the SAMPLED pin (the player only learns "the top is
/// not a match", never which card it is):
///
/// - **No player decision may see it.** The pinned uid is visible to the
///   search, so a decision node that saw it would know the exact top card.
///   The only caller, the I Am Invincible rider, runs where C# runs it
///   (`AfterAutoPostPlayPhaseEntered`, the first step of
///   `EndPlayerTurnPhaseOneInternal`, `CombatManager.cs:1168-1170`; GH #894),
///   ahead of `BeforeTurnEnd` and every turn-end choice. So it hands a
///   sampled miss back, and its call site drops the pin at once with
///   [`drop_sampled_top_pin`], before anything can surface a choice.
///   Dropping forgets that the top is not a match: the next draw can take
///   an I Am Invincible that C# could not have had on top (probability k/n
///   for k copies in an n-card unknown middle). That only affects decks
///   holding an I Am Invincible in the unknown middle, and it errs toward
///   the search knowing less than the player, never more.
/// - **Random inserts land below it.** A pinned top is treated as known,
///   so [`insert_into_unknown_sorted`] (enemy status shuffles during the
///   enemy turn) and the deferred [`shuffle`] keep it on top, while C#
///   `CardPileCmd.Add(.., Random)` lands above the top card with
///   probability `1/(n+1)`. The Headbutt / Thinking Ahead pins carry this
///   approximation. The I Am Invincible pin no longer does: it is dropped
///   before the enemy turn (above), so an inserted status joins the unknown
///   middle and can be the next draw, as in C#.
pub(crate) fn peek_top_card_if(
    player: &mut PlayerCombatState,
    rng: &mut CombatRng,
    pred: impl Fn(CardUid) -> bool,
) -> Option<CardUid> {
    let &top = player.draw.first()?;
    if !player.deferred_draw_order {
        return pred(top).then_some(top);
    }
    // Same staleness sweep as `pop_next_card`: a stale pin must not make
    // the top look known.
    player.pinned_top.retain(|uid| player.draw.contains(uid));
    player.pinned_bottom.retain(|uid| player.draw.contains(uid));
    let middle_len = player.draw.len().saturating_sub(player.pinned_bottom.len());
    if !player.pinned_top.is_empty() || middle_len <= 1 {
        // The top is known: a pinned card, the only unknown card, or the
        // first card of the known-bottom stack.
        let top = player.draw[0];
        return pred(top).then_some(top);
    }
    if !player.draw[..middle_len].iter().any(|&uid| pred(uid)) {
        return None;
    }
    let idx = rng.next_int(0, (middle_len - 1) as i32) as usize;
    let uid = player.draw.remove(idx);
    player.draw.insert(0, uid);
    pin_top(player, uid);
    pred(uid).then_some(uid)
}

/// Undo the PIN of a top card that [`peek_top_card_if`] SAMPLED and that did
/// not satisfy its predicate: take it off the physical top, clear its pin and
/// fold it back into the canonical (uid-sorted) unknown middle. The pile is
/// then laid out exactly as before the peek; only the RNG cursor moved, and
/// `chance_outcome_hash` ignores that, so every miss of one peek is the same
/// search outcome. GH #785 / #894.
///
/// The pin named a hidden card (the player learned only "the top is not a
/// match"), so a caller whose next steps can surface a player choice drops it
/// first — see the caveat on [`peek_top_card_if`] for what that forgets.
///
/// Pass only a card the caller's own peek sampled: a KNOWN pin (Headbutt,
/// Nostalgia) is information the player has and must never be dropped. As a
/// guard, this is a no-op unless `uid` is the pinned physical top of a
/// deferred-order pile.
pub(crate) fn drop_sampled_top_pin(player: &mut PlayerCombatState, uid: CardUid) {
    if !player.deferred_draw_order
        || player.draw.first() != Some(&uid)
        || !player.pinned_top.contains(&uid)
    {
        return;
    }
    player.draw.remove(0);
    unpin(player, uid);
    insert_into_unknown_sorted(player, uid);
}

/// Remove and return the FIRST draw-pile card, counting from the physical
/// top, that satisfies `pred`; `None` if no card does. C#
/// `drawPile.Cards.FirstOrDefault(pred)` followed by a move out of the
/// pile — ToastyMittens' round-1 "first non-Innate card" exhaust. GH #785.
///
/// With [`PlayerCombatState::deferred_draw_order`] clear this is
/// `draw.iter().position(pred)` + `draw.remove(..)`, with no RNG read.
///
/// Under a deferred-order pile, the pile is walked as the player knows it:
/// the pinned top cards in order first; then the unknown middle, where the
/// first match in a uniformly random order is a uniformly random match, so
/// one RNG read picks among the matching middle cards when there are two or
/// more (a single match is taken with no RNG read); then the known-bottom
/// stack in order. The removed card's pin, if any, is cleared.
pub(crate) fn pop_first_card_matching(
    player: &mut PlayerCombatState,
    rng: &mut CombatRng,
    pred: impl Fn(CardUid) -> bool,
) -> Option<CardUid> {
    let idx = if player.deferred_draw_order {
        player.pinned_top.retain(|uid| player.draw.contains(uid));
        player.pinned_bottom.retain(|uid| player.draw.contains(uid));
        let top_len = player.pinned_top.len();
        let middle_end = player.draw.len().saturating_sub(player.pinned_bottom.len());
        if let Some(i) = player.draw[..top_len].iter().position(|&uid| pred(uid)) {
            i
        } else {
            let matches: SmallVec<[usize; 32]> = (top_len..middle_end)
                .filter(|&i| pred(player.draw[i]))
                .collect();
            match matches.len() {
                0 => {
                    middle_end
                        + player.draw[middle_end..]
                            .iter()
                            .position(|&uid| pred(uid))?
                }
                1 => matches[0],
                n => matches[rng.next_int(0, (n - 1) as i32) as usize],
            }
        }
    } else {
        player.draw.iter().position(|&uid| pred(uid))?
    };
    let uid = player.draw.remove(idx);
    unpin(player, uid);
    Some(uid)
}

/// Insert `uid` into the unknown middle segment of `player.draw`,
/// preserving canonical (uid-ascending) sortedness, consuming NO RNG (bead
/// `sts2-rs-09x5n`, F2 `HiddenInfoMode::BeliefDraw`).
///
/// Shared by every "gh#181-family" random-position-into-draw call site
/// (`CombatState::insert_card_into_draw_pile`,
/// `card_effects::spawn_card_into_draw_pile_random`,
/// `card_effects::spawn_card_into_draw_pile_random_position`) once gated on
/// [`PlayerCombatState::deferred_draw_order`] — under a deferred-draw-order
/// pile there is no physical position for a "random index" to land in (the
/// whole point of the belief representation), so the card is folded into
/// the canonical multiset at its sorted slot instead of the RNG-sampled
/// physical index those call sites use on a materialized-order pile.
///
/// Callers are responsible for gating on the flag themselves — this
/// function unconditionally inserts sorted (it has no "legacy" branch of
/// its own).
pub(crate) fn insert_into_unknown_sorted(player: &mut PlayerCombatState, uid: CardUid) {
    // Stale-pin sweep FIRST — same retain-against-draw sweep
    // [`crate::blindfold::canonicalize_unknown_middle`] and [`shuffle`]
    // perform. Without it, a pin whose card left the pile WITHOUT an
    // `unpin` (e.g. a raw `draw.remove(pos)` at some content call site;
    // the Havoc/Cascade top pop was one before GH #785 routed it through
    // `pop_top_card`) would be RESURRECTED by
    // the rebuild below: `draw.extend(top)` re-inserts a uid that now
    // also lives in play/exhaust — duplicating the card across piles.
    // Reviewer-caught (bead `sts2-rs-09x5n` re-review).
    player.pinned_top.retain(|u| player.draw.contains(u));
    player.pinned_bottom.retain(|u| player.draw.contains(u));
    if player.pinned_top.is_empty() && player.pinned_bottom.is_empty() {
        let pos = player.draw.partition_point(|&u| u < uid);
        player.draw.insert(pos, uid);
        return;
    }
    let top: SmallVec<[CardUid; 4]> = player.pinned_top.clone();
    let bot: SmallVec<[CardUid; 4]> = player.pinned_bottom.clone();
    let mut middle: SmallVec<[CardUid; 32]> = player
        .draw
        .iter()
        .copied()
        .filter(|u| !top.contains(u) && !bot.contains(u))
        .collect();
    let pos = middle.partition_point(|&u| u < uid);
    middle.insert(pos, uid);
    player.draw.clear();
    player.draw.extend(top);
    player.draw.extend(middle);
    player.draw.extend(bot);
}

/// Whether `a` and `b` are the same card from a player's perspective —
/// every field [`Card`] carries EXCEPT the instance [`CardUid`]. Bead
/// `sts2-rs-i8bgu` (F1 `HiddenInfoMode::DrawChance`): two distinct
/// physical card instances (e.g. two un-upgraded Strikes) can be
/// completely indistinguishable to the player, but `Card`'s derived
/// `PartialEq` includes `uid` and would call them "different" — exactly
/// the ambiguity the draw-chance detector's homogeneity check and the
/// chance-outcome dedup hash both need to collapse.
///
/// Implemented by unifying `uid` on a clone and delegating to the
/// derived `PartialEq` rather than hand-listing fields, so a future
/// field added to [`Card`] is covered automatically — conservative by
/// construction (there is no field this helper could forget to check).
///
/// A non-X card's `energy_spent` is excluded too: see
/// [`observational_energy_spent`].
#[must_use]
pub fn cards_observationally_equal(a: &Card, b: &Card) -> bool {
    if a.uid == b.uid {
        return true;
    }
    let mut a2 = *a;
    a2.uid = b.uid;
    a2.energy_spent = observational_energy_spent(a);
    let mut b2 = *b;
    b2.energy_spent = observational_energy_spent(b);
    a2 == b2
}

/// C# `CardPlay.Resources.EnergyValue` of this card's latest play:
/// `energy_spent`, unless [`VarKey::AutoPlayEnergyValue`] overrides it (an
/// X-cost card the Whispering Earring paid for and auto-played).
#[must_use]
pub fn play_energy_value(card: &Card) -> i32 {
    match card.combat_var(VarKey::AutoPlayEnergyValue) {
        0 => card.energy_spent,
        stamped => stamped - 1,
    }
}

/// `card.energy_spent` as the observational identity sees it: the stamped
/// value for an X-cost card, `0` for every other card.
///
/// GH #741: `play_card` stamps a non-X card's paid cost into `energy_spent`
/// (C# `ResourceInfo.EnergyValue`) for its late effects to read. The value is
/// a per-play transient, overwritten at the start of every play before anything
/// reads it, so a Strike that was played earlier is the same card as one that
/// was not. Before #741 a non-X card always read `0` here, so masking it keeps
/// the MCTS draw-chance and pile hashes exactly as they were. X-cost cards were
/// already stamped and keep their value.
#[must_use]
pub fn observational_energy_spent(card: &Card) -> i32 {
    if card.is_x_cost() {
        card.energy_spent
    } else {
        0
    }
}

/// Whether every card instance named by `segment` (e.g. from
/// [`unknown_middle_uids`]) is [`cards_observationally_equal`] to every
/// other. A homogeneous segment (all copies of one observable card) is
/// deterministic for the player — every possible draw from it looks the
/// same — so the draw-chance detector (bead `sts2-rs-i8bgu`) skips
/// chance-noding it: doing so would only widen the tree with outcomes a
/// player could never distinguish.
///
/// Conservative on lookup failure: a `uid` not found in `cards` makes the
/// segment count as heterogeneous (the safe direction — it only widens
/// the tree, never causes a leak) rather than panicking or silently
/// skipping the entry.
#[must_use]
pub fn segment_is_observationally_homogeneous(segment: &[CardUid], cards: &CardStore) -> bool {
    let Some(first) = segment.first().and_then(|uid| find_card(cards, *uid)) else {
        return false;
    };
    segment
        .iter()
        .skip(1)
        .all(|uid| find_card(cards, *uid).is_some_and(|c| cards_observationally_equal(first, c)))
}

fn find_card(cards: &CardStore, uid: CardUid) -> Option<&Card> {
    cards.iter().find(|c| c.uid == uid)
}

/// Pin `uid` to the top of the draw pile. Mirrors Headbutt-style
/// "insert at front of draw" semantics: subsequent calls push prior
/// pins down (the new pin becomes `Top(0)`, the old becomes `Top(1)`).
///
/// Bead `sts2-rs-o6xw`. Idempotently removes any prior pin for `uid`
/// from either the top or bottom pin list before inserting at the
/// front of `pinned_top`.
pub fn pin_top(player: &mut PlayerCombatState, uid: CardUid) {
    player.pinned_top.retain(|u| *u != uid);
    player.pinned_bottom.retain(|u| *u != uid);
    player.pinned_top.insert(0, uid);
}

/// Pin `uid` to the bottom of the draw pile. Symmetric to
/// [`pin_top`] for Forethought-style "insert at bottom of draw"
/// semantics. Bead `sts2-rs-o6xw`.
pub fn pin_bottom(player: &mut PlayerCombatState, uid: CardUid) {
    player.pinned_top.retain(|u| *u != uid);
    player.pinned_bottom.retain(|u| *u != uid);
    player.pinned_bottom.insert(0, uid);
}

/// Forget any pin associated with `uid`. Called when a card is
/// drawn / moved between piles so stale pins don't survive past
/// their card's tenure in the draw pile. Bead `sts2-rs-o6xw`.
pub fn unpin(player: &mut PlayerCombatState, uid: CardUid) {
    // Early-out: called once per card drawn (~hundreds of thousands of
    // times per MCTS search) but pins are rare — skip the two `retain`
    // walks entirely in the overwhelmingly common no-pins case.
    // Perf-investigation 2026-06-07.
    if player.pinned_top.is_empty() && player.pinned_bottom.is_empty() {
        return;
    }
    player.pinned_top.retain(|u| *u != uid);
    player.pinned_bottom.retain(|u| *u != uid);
}

/// Drain the discard pile, shuffle, push the result onto the draw pile.
///
/// Ports `_shuffle_if_needed` from `sts2-rl-agent@01c094d:sts2_env/core/combat.py:1131-1141`:
///
/// ```python
/// if not state.draw and state.discard:
///     state.draw[:] = list(state.discard)
///     state.discard.clear()
///     self.rng.shuffle(state.draw)
///     # apply_enchantment_shuffle_order(...) — Phase 6+, no-op for Phase 1
///     fire_after_shuffle(self)  # hook firing deferred to a later bead
/// ```
///
/// Phase 1 leaves the `apply_enchantment_shuffle_order` call as a no-op
/// (no enchantments in scope) and intentionally does not fire the
/// `after_shuffle` hook here — hook wiring lands in P1-3 / P2-x once
/// `hooks.rs` exposes a typed dispatcher. The TODO is tracked in the
/// downstream parity bead (sts2-rs-yr4).
///
/// This helper is called from [`draw`] when the draw pile runs dry mid-draw
/// and the discard pile is non-empty. It is also exposed publicly because
/// the Python sim invokes the equivalent shuffle in several places (e.g.
/// `exhaust_from_draw_pile` at `combat.py:1274-1284`); future beads that
/// port those paths can call this directly. Ported by bead
/// `sts2-rs-6ynt.6.8.1` as [`crate::CombatState::exhaust_from_draw_pile`].
pub fn discard_pile_into_draw_pile(
    player: &mut PlayerCombatState,
    cards: &CardStore,
    rng: &mut CombatRng,
) {
    let _ = discard_pile_into_draw_pile_signaling(player, cards, rng);
}

/// Resolve a [`CardUid`] to its canonical C# `ModelId.Entry` string
/// (e.g. `"BASH"`, `"DEFEND_IRONCLAD"`). Used as the PRIMARY pre-shuffle
/// sort key replicating C# `StableShuffle`. Returns `""` for a uid not
/// present in the store (defensive — should not occur for live piles).
/// Test-only: the original `&str` primary sort key. Production reshuffle
/// now sorts on the O(1) [`card_rank`]; the `dotnet_list_sort` parity tests
/// recompute the expected order through this name-compare and assert it
/// matches, pinning `card_rank`'s ordering to `to_python_name()` ordinal.
#[cfg(test)]
#[inline]
fn card_entry(cards: &CardStore, uid: CardUid) -> &str {
    cards
        .get(uid.get() as usize - 1)
        .map_or("", |c| card_model_entry(c.card_id))
}

/// A card's C# `ModelId.Entry`: `ModelDb.GetEntry(type)` =
/// `StringHelper.Slugify(type.Name)` (v0.111.0 `ModelDb.cs:535-538`), the
/// SCREAMING_SNAKE class name. That is `to_python_name()` minus the `_CARD` /
/// `_STATUS` disambiguation suffix the Rust name table adds where a card
/// shares its class name with a power (`VICIOUS_CARD`) or a monster/other
/// model (`SLOTH_STATUS`); no card class name ends in `Card`/`Status` (only
/// the unused `DeprecatedCard`). The suffix matters for every ordinal
/// `ModelId` compare (`ModelId.CompareTo`, `ModelId.cs:43-51`): `THUNDER_CARD`
/// sorts AFTER `THUNDERCLAP` (`'_'` > `'C'`) while C#'s `THUNDER` sorts before
/// it (act23 Ironclad:2068 reshuffle).
#[must_use]
pub fn card_model_entry(card_id: CardId) -> &'static str {
    let name = card_id.to_python_name();
    name.strip_suffix("_CARD")
        .or_else(|| name.strip_suffix("_STATUS"))
        .unwrap_or(name)
}

/// Ordinal rank of every [`CardId`] by its C# `ModelId.Entry`
/// ([`card_model_entry`]), assigned by
/// sorting all names once in byte order (the rule .NET's
/// `StringComparison.Ordinal` uses, which Rust `str::cmp` matches). Real
/// cards rank `1..=N`; the `0` sentinel is reserved so a uid with no backing
/// `Card` (the `card_entry == ""` defensive case) still sorts BEFORE every
/// real card — `"".cmp(name)` is always `Less`, and `0 < 1..=N`.
///
/// Card entries are unique, so the rank is a faithful O(1) `u16` substitute for
/// the per-comparison `&str` compare in the reshuffle pre-sort
/// ([`discard_pile_into_draw_pile_signaling`] / [`shuffle_draw_and_discard`]).
/// Built at runtime from the name table itself, so it cannot drift as
/// cards are added — no `@generated` table to keep in sync. (Item 1,
/// `docs/plans/2026-06-07-mcts-single-threaded-perf-plan.md`.)
fn reshuffle_rank(card_id: CardId) -> u16 {
    use std::sync::OnceLock;
    static RANKS: OnceLock<Vec<u16>> = OnceLock::new();
    let ranks = RANKS.get_or_init(|| {
        // The UNION of every build's cards (GH #792): v0.111.0-only ids
        // (`CardId::V0111_ONLY`) sit past `all()` in declaration order, so
        // the table must cover them. Adding names only shifts ranks
        // uniformly; the relative order of v0.107.1 cards, which is all the
        // sort compares, is unchanged.
        let all = CardId::all_for(crate::GameVersion::V0_111_0);
        let mut by_name: Vec<CardId> = all.clone();
        by_name.sort_by(|a, b| card_model_entry(*a).cmp(card_model_entry(*b)));
        let mut table = vec![0u16; all.len()];
        for (rank, cid) in by_name.iter().enumerate() {
            // `cid as usize` is the declaration-order discriminant, which is
            // exactly its index in `all()`; rank+1 reserves 0 for "missing".
            table[*cid as usize] = u16::try_from(rank + 1).expect("card count fits u16");
        }
        table
    });
    ranks[card_id as usize]
}

/// C# `CardModel.CompareTo` (`CardModel.cs:1745-1766`): `ModelId` first
/// (ordinal [`card_model_entry`], via the O(1) [`reshuffle_rank`]), then
/// `CurrentUpgradeLevel` ascending (base before upgraded). The `list.Sort()`
/// key of every card `StableShuffle` (Catastrophe, Beat Down, Uproar, Seeker
/// Strike, Stone Cracker, Power Cell). Keying on the raw python name instead
/// misorders the `_CARD`/`_STATUS`-suffixed ids: `THUNDER_CARD` sorts after
/// `THUNDERCLAP`, while C#'s `THUNDER` sorts before it.
#[must_use]
pub fn card_model_compare(a: &Card, b: &Card) -> std::cmp::Ordering {
    reshuffle_rank(a.card_id)
        .cmp(&reshuffle_rank(b.card_id))
        .then_with(|| u8::from(a.upgraded).cmp(&u8::from(b.upgraded)))
}

/// Reshuffle pre-sort PRIMARY key: the O(1) ordinal rank of a uid's card name
/// (see [`reshuffle_rank`]). Returns `0` for a uid with no backing `Card`,
/// matching the `""`-sorts-first semantics of [`card_entry`].
#[inline]
fn card_rank(cards: &CardStore, uid: CardUid) -> u16 {
    cards
        .get(uid.get() as usize - 1)
        .map_or(0, |c| reshuffle_rank(c.card_id))
}

/// Resolve a [`CardUid`] to C# `CardModel.CurrentUpgradeLevel`, the
/// SECONDARY pre-shuffle sort key. C# `CardModel.CompareTo`
/// (`MegaCrit.Sts2.Core.Models/CardModel.cs:1745`) overrides the base
/// `ModelId` comparator: after equal Category+Entry it compares
/// `CurrentUpgradeLevel` ascending, so a base copy sorts BEFORE an
/// upgraded copy of the same card. Rust models upgrade as a bool, so
/// this collapses to `0` (base) / `1` (upgraded). Missing uids rank `0`
/// (defensive). See bead `sts2-rs-5aelq`.
#[inline]
fn card_upgrade_rank(cards: &CardStore, uid: CardUid) -> u8 {
    u8::from(
        cards
            .get(uid.get() as usize - 1)
            .is_some_and(|c| c.upgraded),
    )
}

/// Faithful port of .NET's `ArraySortHelper<T>.IntrospectiveSort` — the
/// algorithm behind `List<T>.Sort()` / `Array.Sort`, which C#
/// `ListExtensions.StableShuffle` invokes (`list.Sort()`) BEFORE the
/// Fisher-Yates pass. Unlike a stable sort, .NET's introsort reorders
/// EQUAL-key elements: insertion sort (used for partitions ≤16) is
/// stable, but quicksort partitioning above 16 is NOT. So when a
/// reshuffled pile exceeds 16 cards and contains identical instances
/// (same Entry + upgrade) carrying divergent per-instance state — e.g.
/// FRANTIC_ESCAPE copies with different accumulated `AddThisCombat` cost
/// bumps — the tied run lands in C#'s introsort order, which a stable
/// `sort_by` does not reproduce. For DISTINCT keys the sorted order is
/// unique, so this is byte-identical to the prior stable sort; behaviour
/// changes only within equal-key runs. C# ref: .NET 9
/// `System.Collections.Generic.ArraySortHelper` (`IntroSort` /
/// `PickPivotAndPartition` / `InsertionSort` / `DownHeap`).
pub fn dotnet_list_sort<T, F>(s: &mut [T], cmp: &F)
where
    T: Copy,
    F: Fn(T, T) -> core::cmp::Ordering,
{
    let n = s.len();
    if n > 1 {
        // depthLimit = 2 * (floor(log2(n)) + 1)
        let depth = 2 * (usize::BITS - 1 - (n as u32).leading_zeros() + 1) as usize;
        dnls_intro(s, 0, n - 1, depth, cmp);
    }
}

#[inline]
fn dnls_swap_if_greater<T, F>(s: &mut [T], cmp: &F, i: usize, j: usize)
where
    T: Copy,
    F: Fn(T, T) -> core::cmp::Ordering,
{
    if i != j && cmp(s[i], s[j]) == core::cmp::Ordering::Greater {
        s.swap(i, j);
    }
}

fn dnls_intro<T, F>(s: &mut [T], lo: usize, mut hi: usize, mut depth: usize, cmp: &F)
where
    T: Copy,
    F: Fn(T, T) -> core::cmp::Ordering,
{
    use core::cmp::Ordering;
    while hi > lo {
        let size = hi - lo + 1;
        if size <= 16 {
            match size {
                1 => {}
                2 => dnls_swap_if_greater(s, cmp, lo, hi),
                3 => {
                    dnls_swap_if_greater(s, cmp, lo, hi - 1);
                    dnls_swap_if_greater(s, cmp, lo, hi);
                    dnls_swap_if_greater(s, cmp, hi - 1, hi);
                }
                _ => {
                    // InsertionSort over [lo..=hi].
                    for i in lo..hi {
                        let t = s[i + 1];
                        let mut j = i as isize;
                        while j >= lo as isize && cmp(t, s[j as usize]) == Ordering::Less {
                            s[(j + 1) as usize] = s[j as usize];
                            j -= 1;
                        }
                        s[(j + 1) as usize] = t;
                    }
                }
            }
            return;
        }
        if depth == 0 {
            dnls_heap_sort(s, lo, hi, cmp);
            return;
        }
        depth -= 1;
        let p = dnls_partition(s, lo, hi, cmp);
        dnls_intro(s, p + 1, hi, depth, cmp);
        hi = p - 1;
    }
}

fn dnls_partition<T, F>(s: &mut [T], lo: usize, hi: usize, cmp: &F) -> usize
where
    T: Copy,
    F: Fn(T, T) -> core::cmp::Ordering,
{
    use core::cmp::Ordering;
    let mid = lo + (hi - lo) / 2;
    dnls_swap_if_greater(s, cmp, lo, mid);
    dnls_swap_if_greater(s, cmp, lo, hi);
    dnls_swap_if_greater(s, cmp, mid, hi);
    let pivot = s[mid];
    s.swap(mid, hi - 1);
    let mut left = lo;
    let mut right = hi - 1;
    while left < right {
        loop {
            left += 1;
            if cmp(s[left], pivot) != Ordering::Less {
                break;
            }
        }
        loop {
            right -= 1;
            if cmp(pivot, s[right]) != Ordering::Less {
                break;
            }
        }
        if left >= right {
            break;
        }
        s.swap(left, right);
    }
    if left != hi - 1 {
        s.swap(left, hi - 1);
    }
    left
}

fn dnls_heap_sort<T, F>(s: &mut [T], lo: usize, hi: usize, cmp: &F)
where
    T: Copy,
    F: Fn(T, T) -> core::cmp::Ordering,
{
    let n = hi - lo + 1;
    let mut i = n / 2;
    while i >= 1 {
        dnls_down_heap(s, i, n, lo, cmp);
        i -= 1;
    }
    let mut i = n;
    while i > 1 {
        s.swap(lo, lo + i - 1);
        dnls_down_heap(s, 1, i - 1, lo, cmp);
        i -= 1;
    }
}

fn dnls_down_heap<T, F>(s: &mut [T], mut i: usize, n: usize, base: usize, cmp: &F)
where
    T: Copy,
    F: Fn(T, T) -> core::cmp::Ordering,
{
    use core::cmp::Ordering;
    let d = s[base + i - 1];
    while i <= n / 2 {
        let mut child = 2 * i;
        if child < n && cmp(s[base + child - 1], s[base + child]) == Ordering::Less {
            child += 1;
        }
        if cmp(d, s[base + child - 1]) != Ordering::Less {
            break;
        }
        s[base + i - 1] = s[base + child - 1];
        i = child;
    }
    s[base + i - 1] = d;
}

/// Pre-sort the (already discard-merged) draw pile by the C#
/// `CardModel.CompareTo` key — `(Entry ordinal rank, upgrade level)` — via the
/// .NET introsort replica [`dotnet_list_sort`]. Shared by
/// [`discard_pile_into_draw_pile_signaling`] and [`shuffle_draw_and_discard`].
///
/// Perf (2026-07-04, MCTS hot path — one call per reshuffle): the keys are
/// resolved ONCE per uid up front and the sort runs over `(rank, upgrade,
/// uid)` tuples, instead of re-resolving `card_rank` / `card_upgrade_rank`
/// inside every comparison (O(n log n) arena+table lookups per reshuffle).
/// Bit-identical to the old uid-keyed closure: the comparator ignores the uid
/// component, so every comparison returns exactly the `Ordering` the old
/// closure returned at the same algorithm step, and the introsort permutes
/// whole tuples — the final uid order is the same permutation.
fn presort_draw_for_reshuffle(player: &mut PlayerCombatState, cards: &CardStore) {
    let mut keyed: SmallVec<[(u16, u8, CardUid); 32]> = player
        .draw
        .iter()
        .map(|&uid| (card_rank(cards, uid), card_upgrade_rank(cards, uid), uid))
        .collect();
    let cmp =
        |a: (u16, u8, CardUid), b: (u16, u8, CardUid)| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1));
    dotnet_list_sort(keyed.as_mut_slice(), &cmp);
    for (slot, k) in player.draw.iter_mut().zip(keyed.iter()) {
        *slot = k.2;
    }
}

/// Identical to [`discard_pile_into_draw_pile`] but returns `true` iff
/// a shuffle actually occurred (i.e. the precondition was met and
/// cards were moved from discard into draw). Bead `sts2-rs-jlc`
/// (n3w-b) — the `after_shuffle` relic-bus dispatcher consumes this
/// signal from
/// [`crate::CombatState::draw_into_hand`] /
/// [`crate::CombatState::shuffle_draw_pile`].
///
/// Kept as a sibling helper (rather than changing the public
/// signature of [`discard_pile_into_draw_pile`]) so that existing
/// callers in `sts2-content::enchantments` continue to compile
/// without a per-call return-value rebind.
pub fn discard_pile_into_draw_pile_signaling(
    player: &mut PlayerCombatState,
    cards: &CardStore,
    rng: &mut CombatRng,
) -> bool {
    if !player.draw.is_empty() || player.discard.is_empty() {
        return false;
    }
    emit_pile_trace(player, cards, "shuf", rng.counter(), None);
    // Bead `sts2-rs-o6xw`: a true reshuffle scrambles all knowledge of
    // draw-pile position. Drop any lingering pins before refilling so
    // the post-shuffle ordering is fully randomized (no card from the
    // refilled draw pile was pinned in any meaningful sense — the
    // pins were referring to the now-empty pre-reshuffle draw pile).
    player.pinned_top.clear();
    player.pinned_bottom.clear();
    player.draw.extend(player.discard.drain(..));
    // C# parity: the combat reshuffle uses `StableShuffle`
    // (`MegaCrit.Sts2.Core.Commands/CardPileCmd.cs:820` →
    // `ListExtensions.StableShuffle`), which `Sort()`s the list by
    // `CardModel.CompareTo` BEFORE the Fisher-Yates pass — making the
    // reshuffled order independent of the order cards entered the discard
    // pile. `CardModel.CompareTo` (`CardModel.cs:1745`) is:
    //   1. `ModelId.CompareTo` — Category then Entry, `StringComparison.
    //      Ordinal`. Within a single deck all cards share one category,
    //      so this reduces to the card-id Entry string in ordinal/byte
    //      order (`.cmp` on `&str` is a byte/ordinal compare).
    //   2. `CurrentUpgradeLevel.CompareTo` — ascending, so a base copy
    //      sorts BEFORE an upgraded copy of the SAME card id. This
    //      secondary key is essential: duplicate ids differing only in
    //      `upgraded` are NOT interchangeable, and omitting it let an
    //      in-hand-upgraded duplicate (e.g. an ARMAMENTS-upgraded
    //      TRUE_GRIT) follow its discard slot and land at a different
    //      draw position than C# (bead `sts2-rs-5aelq`, seed-52
    //      parity-fuzz divergence).
    // The *initial* shuffle is genuinely `UnstableShuffle`
    // (`CardPile.cs:69`) and is intentionally NOT pre-sorted; this
    // pre-sort lives ONLY on the reshuffle path. C# `list.Sort()` is
    // .NET's introspective sort, which is UNSTABLE for equal-key runs
    // once the pile exceeds 16 cards (quicksort partitioning). A stable
    // `sort_by` reproduced it only for ≤16-card piles; identical
    // instances carrying divergent per-instance state (FRANTIC_ESCAPE
    // cost bumps) drifted otherwise. [`dotnet_list_sort`] (inside
    // [`presort_draw_for_reshuffle`], which resolves the sort keys once per
    // uid instead of per comparison) replicates .NET's algorithm exactly so
    // the tied run lands at the C# slot.
    presort_draw_for_reshuffle(player, cards);
    shuffle(player, rng);
    // Phase 6+: apply_enchantment_shuffle_order(state.draw, is_initial_shuffle=False)
    // Bead `sts2-rs-jlc`: the caller now fires the `after_shuffle`
    // relic-bus channel based on the returned signal.
    true
}

/// Faithful port of C# `CardPileCmd.Shuffle`
/// (`MegaCrit.Sts2.Core.Commands/CardPileCmd.cs:804`): merge the **entire
/// discard pile into the draw pile** and `StableShuffle` the combined
/// list, leaving the discard pile empty. This is the *explicit* shuffle
/// command (Reboot, BottledPotential) — distinct from
/// [`discard_pile_into_draw_pile_signaling`], the *auto*-reshuffle that
/// only fires when the draw pile is already empty. C#'s `Shuffle`
/// unconditionally pulls discard in regardless of draw-pile contents, so
/// modelling it as a draw-pile-only `shuffle` dropped every discarded
/// card (e.g. STS2 Reboot draws hand+discard, not hand-only — verified
/// against the C# headless harness). Bead `sts2-rs-s2pr8`.
///
/// Pre-sort key matches [`discard_pile_into_draw_pile_signaling`] /
/// C# `CardModel.CompareTo` (`(Entry, CurrentUpgradeLevel)`) so a
/// duplicate id differing only in `upgraded` lands at the C#-faithful
/// slot regardless of pile order (bead `sts2-rs-5aelq`). The combat-start
/// initial shuffle remains `UnstableShuffle` (no pre-sort) and is
/// unaffected.
pub fn shuffle_draw_and_discard(
    player: &mut PlayerCombatState,
    cards: &CardStore,
    rng: &mut CombatRng,
) {
    emit_pile_trace(player, cards, "shuf", rng.counter(), None);
    // A full shuffle scrambles all draw-pile position knowledge.
    player.pinned_top.clear();
    player.pinned_bottom.clear();
    // C# `CardPileCmd.Shuffle` (`CardPileCmd.cs:1077-1088`) lists the DISCARD
    // pile first and appends the draw pile (`list.AddRange(drawPileCards)`).
    // The pre-sort orders distinct cards the same either way, but above 16
    // cards the introsort permutes identical copies by input position, so a
    // draw-first merge put an enchanted Defend 8 slots off C# (act23
    // Necrobinder:1018).
    let draw_before = core::mem::take(&mut player.draw);
    player.draw.extend(player.discard.drain(..));
    player.draw.extend(draw_before);
    // .NET introsort tie-order (see [`dotnet_list_sort`]); the explicit
    // `Shuffle` command (Reboot, BottledPotential) routes through the
    // same C# `StableShuffle` -> `list.Sort()` as the auto-reshuffle.
    presort_draw_for_reshuffle(player, cards);
    shuffle(player, rng);
}

/// Number of shuffles that occurred during the most recent
/// [`draw_signaling`] call. Identical to [`draw`] but returns the
/// shuffle count alongside the moved-card count.
///
/// Bead `sts2-rs-jlc` (n3w-b): consumed by
/// [`crate::CombatState::draw_into_hand`] to fire the `after_shuffle`
/// relic-bus channel once per auto-reshuffle. Note that pathological
/// loops can in principle reshuffle more than once per draw (if a
/// listener empties the draw pile mid-draw); the count reflects the
/// number of actual reshuffles so the bus fires once per event.
pub fn draw_signaling(
    player: &mut PlayerCombatState,
    n: i32,
    cards: &CardStore,
    rng: &mut CombatRng,
) -> (usize, u32) {
    let target = usize::try_from(n).unwrap_or(0);
    let mut moved = 0;
    let mut shuffles: u32 = 0;
    for _ in 0..target {
        if is_hand_full(player) {
            break;
        }
        if player.draw.is_empty() && discard_pile_into_draw_pile_signaling(player, cards, rng) {
            shuffles = shuffles.saturating_add(1);
        }
        if player.draw.is_empty() {
            break;
        }
        // Bead `sts2-rs-09x5n` (F2): `pop_next_card` defers the random
        // choice of which card is drawn to here when
        // `deferred_draw_order` is set — byte-identical `draw.remove(0)`
        // otherwise.
        let uid = pop_next_card(player, rng);
        // Bead `sts2-rs-o6xw`: drawing a pinned card consumes its pin.
        unpin(player, uid);
        player.hand.push(uid);
        moved += 1;
    }
    (moved, shuffles)
}

/// Move `uid` from a source pile to the discard pile.
///
/// Thin convenience wrapper over [`move_card`] that defaults the source to
/// [`PileKind::Hand`] (the overwhelmingly common case — Python's
/// `move_card_to_discard` from `sts2-rl-agent@01c094d:sts2_env/core/combat.py:1693-1702`
/// resolves the source dynamically by scanning every pile, but in practice
/// every Phase-1 caller discards from hand). Tests / future commands that
/// need to discard from a non-hand source should call [`move_card`] directly
/// with the explicit `from` pile.
///
/// Returns `Err(PileError::NotInPile)` if `uid` is not in the player's hand.
pub fn discard(player: &mut PlayerCombatState, uid: CardUid) -> Result<(), PileError> {
    move_card(player, uid, PileKind::Hand, PileKind::Discard)
}

/// Try to add `uid` to the hand. If the hand is at or above
/// [`HAND_LIMIT`], the card goes to the discard pile instead and the
/// function returns `false`.
///
/// Mirrors `move_card_to_creature_hand` from
/// `sts2-rl-agent@01c094d:sts2_env/core/combat.py:1682-1691`:
///
/// ```python
/// if len(zones["hand"]) < MAX_HAND_SIZE:
///     zones["hand"].append(card)
/// else:
///     zones["discard"].append(card)
/// ```
///
/// Returns `true` if the card landed in the hand, `false` if it was
/// redirected to the discard pile.
pub fn try_add_to_hand(player: &mut PlayerCombatState, uid: CardUid) -> bool {
    if is_hand_full(player) {
        player.discard.push(uid);
        false
    } else {
        player.hand.push(uid);
        true
    }
}

/// Draw up to `n` cards from the draw pile into the hand.
///
/// Ports `_draw_cards_for_creature` from
/// `sts2-rl-agent@01c094d:sts2_env/core/combat.py:1102-1129`. The Python
/// canonical loop reshuffles when the draw pile runs dry mid-draw (via
/// `_shuffle_if_needed` — see [`discard_pile_into_draw_pile`]).
///
/// **Full-hand semantics (matches Python — breaks on full hand)**:
///
/// Per `combat.py:1118-1120` at pin `01c094d`:
///
/// ```python
/// for _ in range(max(0, count)):
///     if len(state.hand) >= MAX_HAND_SIZE:
///         break
/// ```
///
/// When the hand is at or above [`HAND_LIMIT`] at the top of an iteration,
/// the loop terminates immediately. Cards remaining in the draw pile stay
/// there; nothing is redirected to the discard pile. This is required for
/// parity with the Python sim — the redirect-to-discard variant
/// previously implemented here diverged from Python at every full-hand
/// draw site (e.g. Rage's per-attack `+1 draw` once the hand is full).
///
/// Reconciled in bead `sts2-rs-yr4` (P1-5).
///
/// Returns the number of cards actually moved into the hand. When both
/// draw and (post-reshuffle) discard are empty, or the hand reaches
/// [`HAND_LIMIT`] mid-draw, the loop stops and returns the partial count.
///
/// `n <= 0` and `n` cast that overflows `usize` are treated as zero.
pub fn draw(
    player: &mut PlayerCombatState,
    n: i32,
    cards: &CardStore,
    rng: &mut CombatRng,
) -> usize {
    let target = usize::try_from(n).unwrap_or(0);
    let mut moved = 0;
    for _ in 0..target {
        // Python combat.py:1119-1120 — break if hand is at MAX_HAND_SIZE
        // BEFORE attempting the reshuffle / pop. This matches the order
        // of checks in the canonical Python loop.
        if is_hand_full(player) {
            break;
        }
        if player.draw.is_empty() {
            // Auto-reshuffle: discard -> draw, shuffle in place. If both
            // piles are empty, this is a no-op and the next branch breaks.
            discard_pile_into_draw_pile(player, cards, rng);
        }
        if player.draw.is_empty() {
            // Both draw and (post-reshuffle) discard are empty — bail.
            break;
        }
        // Pop from the FRONT to match Python's `state.draw.pop(0)` at
        // combat.py:1124. Draw piles in practice are <60 cards so the
        // O(n) shift is negligible (and the SmallVec inline-32 keeps
        // typical draws on the stack). Bead `sts2-rs-09x5n` (F2):
        // `pop_next_card` defers the random choice to here under
        // `deferred_draw_order` — byte-identical `draw.remove(0)` otherwise.
        let uid = pop_next_card(player, rng);
        // Bead `sts2-rs-o6xw`: drawing a pinned card consumes its pin.
        unpin(player, uid);
        // Hand is guaranteed to have room because of the is_hand_full
        // check above; push directly rather than going through
        // try_add_to_hand (which would silently redirect to discard, and
        // we've just established that's not the canonical Python
        // behaviour for this loop).
        player.hand.push(uid);
        moved += 1;
    }
    moved
}

/// C# `Hook.ShouldDraw(fromHandDraw = false)` — `true` when a CARD-EFFECT
/// draw must be vetoed. C# gates EVERY draw inside `CardPileCmd.Draw`
/// (`CardPileCmd.cs:753`); the vetoing listeners at this pin are:
///
/// * `NoDrawPower.ShouldDraw` (Battle Trance) — read off the mirror+legacy
///   power UNION (bead `sts2-rs-q6bix`): card-driven applies route through
///   the d03 player-creature mirror, so a legacy-only scan misses it.
/// * `Fiddle.ShouldDraw` (`Fiddle.cs:24-38`) — the downside half of the
///   relic. It draws 2 extra at turn start and, in exchange, vetoes every
///   card-effect draw taken on its owner's own side. Only the `+2` half was
///   ported, so a Battle Trance / Pommel Strike / Acrobatics under Fiddle
///   drew cards the real game refused: the DLL mirror's largest pure-draw
///   divergence class on the v11 sweep was 288 records where both sides held
///   the SAME cards split differently between hand and draw, and Fiddle
///   carried a 5.1x lift over its baseline rate in that class.
///
/// (`ScrutinyPower` was the Doormaker phase's draw-veto; Doormaker was
/// removed in v0.107.1 — bead `…wb8lk.2`.)
///
/// Only the turn-start hand draw (`fromHandDraw == true`) bypasses it.
pub(crate) fn card_effect_draw_blocked(state: &crate::CombatState) -> bool {
    if state.player_power_amount(crate::PowerKind::NoDraw) > 0 {
        return true;
    }
    // C# allows the draw when the owner's side is NOT the acting side
    // (`player.Creature.Side != CombatState.CurrentSide`), so the veto is
    // scoped to the player's own turn.
    state.side == crate::Side::Player && state.relics.owns(crate::RelicKind::Fiddle)
}

/// State-aware wrapper over [`draw`] that gates on the player-owned
/// `NoDraw` power.
///
/// Per `sts2-rl-agent@01c094d:sts2_env/powers/silent.py:NoDrawPower`,
/// `modify_draw_amount` returns `0` whenever the listener owner has at
/// least one stack of `NoDraw`. In the Python sim every card-effect
/// draw flows through `_draw_cards_for_creature`, which routes through
/// the modify-draw-amount listener bus before drawing — so a single
/// stack of `NoDraw` short-circuits *every* draw effect for the rest
/// of the turn (BattleTrance, Burning Pact, Pommel Strike, Acrobatics,
/// Coolheaded, …).
///
/// The Rust port has not yet wired the `modify_draw_amount` listener
/// channel (tracked under bead `sts2-rs-k37j`); until it does, every
/// card-effect draw site should call `draw_via_state` instead of the
/// raw [`draw`] primitive. The wrapper:
///
/// 1. Inspects the player's powers for an active `NoDraw` (amount > 0).
/// 2. Returns `0` immediately when present (no shuffle, no pop).
/// 3. Delegates to [`draw`] otherwise.
///
/// Low-level test fixtures and engine plumbing that need to draw
/// regardless of NoDraw should keep using [`draw`] directly.
///
/// The veto predicate itself lives in [`card_effect_draw_blocked`] — the
/// Rust analogue of C# `Hook.ShouldDraw(fromHandDraw = false)`
/// (`CardPileCmd.cs:753`), shared with
/// [`crate::CombatState::draw_into_hand_card_effect`].
pub fn draw_via_state(state: &mut crate::CombatState, n: i32) -> usize {
    draw_via_state_collecting(state, n, None)
}

/// The cards ONE `CardPileCmd.Draw` call returned, and how many it still owes.
///
/// C# `CardPileCmd.Draw` returns the cards its own loop took. A nested draw
/// started by a card's `AfterCardDrawn` rider (Iteration on the first Status,
/// Pagestorm on an Ethereal card), a Hellraiser auto-play's own draw, or a
/// Stratagem pick the reshuffle put in hand is not part of it, though all of
/// them land in hand between its cards. A card that filters what it drew
/// (Scrape, v0.111.0 Expertise) reads this.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct OwnDraw {
    /// The cards this draw took, in draw order (even if a rider moved one on).
    pub cards: smallvec::SmallVec<[CardUid; 10]>,
    /// The cards it still owes when it suspended on an open select: they
    /// continue once the select resolves ([`crate::PendingDrawResume`]).
    pub rest: i32,
}

/// [`draw_via_state`], reporting the draw's own cards ([`OwnDraw`]).
#[must_use]
pub fn draw_own_via_state(state: &mut crate::CombatState, n: i32) -> OwnDraw {
    let mut own = OwnDraw::default();
    let _ = draw_via_state_collecting(state, n, Some(&mut own));
    own
}

fn draw_via_state_collecting(
    state: &mut crate::CombatState,
    n: i32,
    own: Option<&mut OwnDraw>,
) -> usize {
    // Reset the single-card draw report (bead `sts2-rs-pillage-hellraiser`);
    // the per-card / batch branches below set it to the drawn card when one
    // moves, leaving it `None` when nothing is drawn (NoDraw veto, empty
    // piles, full hand) so a caller like Pillage can distinguish "no card
    // drawn" from "card drawn then auto-played out of hand by Hellraiser".
    state.last_drawn_card = None;
    // C# `CardPileCmd.Draw` returns an empty draw when
    // `CombatManager.IsOverOrEnding`, BEFORE `Hook.ShouldDraw`
    // (CardPileCmd.cs:822 v0.107.1, :1012 v0.111.0): a draw issued after the
    // lethal hit (Pommel Strike, Pillage) moves no card and fires no on-draw
    // rider.
    if crate::combat_loop::combat_is_ending(state) {
        return 0;
    }
    if card_effect_draw_blocked(state) {
        // C# `NoDrawPower.cs:29` flashes inside `ShouldDraw` on the path that
        // returns false — `!fromHandDraw && player == Owner.Player`.
        // `Hook.ShouldDraw` (Hook.cs:2413) short-circuits on the FIRST listener
        // to veto, and `card_effect_draw_blocked` checks NoDraw before Fiddle,
        // so NoDraw is the preventer exactly when it is present. The turn-start
        // hand draw never reaches here.
        if crate::event_log::armed(state) && state.player_power_amount(crate::PowerKind::NoDraw) > 0
        {
            crate::event_log::flash_player_power(state, crate::PowerKind::NoDraw);
        }
        return 0;
    }
    // Bead `sts2-rs-63mew`: with an `after_shuffle` choice listener
    // (Stratagem) active, card-effect draws (Slimed, Pommel Strike, …)
    // also route through the C#-faithful per-card loop: C# fires
    // `Hook.AfterShuffle` (and thus the Stratagem grid-select) inside
    // `CardPileCmd.Draw` regardless of the draw's origin, BEFORE the
    // remaining cards are taken.
    // Bead `sts2-rs-bsj93`: HellraiserPower also forces the per-card loop —
    // C# auto-plays drawn Strikes mid-draw on EVERY draw path, so the
    // played Strike can reshuffle back into the same draw.
    if state.per_card_draw_loop_required() || state.reshuffle_reorders_mid_draw(n) {
        return state.draw_suspending_collecting(n, false, own);
    }
    let hand_len_before = state.player.hand.len();
    let moved = draw(
        &mut state.player,
        n,
        &state.cards,
        &mut state.run_rng.shuffle,
    );
    // No rider draws mid-batch here (those force the per-card loop above), so
    // the batch's own cards are the hand's new tail.
    if let Some(own) = own {
        own.cards.extend(
            state
                .player
                .hand
                .get(hand_len_before..hand_len_before + moved)
                .unwrap_or_default()
                .iter()
                .copied(),
        );
    }
    // Report the last card drawn for the single-card path (bead
    // `sts2-rs-pillage-hellraiser`). This batch branch is only taken when no
    // per-card on-draw remover (Hellraiser) is active, so the drawn cards are
    // still in hand here; capture before `invoke_card_drawn_for_newly_drawn`
    // can append further draws (Pagestorm).
    if moved > 0 {
        state.last_drawn_card = state.player.hand.get(hand_len_before + moved - 1).copied();
    }
    // Bead `sts2-rs-lj36b`: card-effect draws (Slimed, Pommel Strike,
    // Battle Trance, …) must fire the same per-card on-draw riders the
    // combat-loop draw path (`draw_into_hand`) does. C# fires
    // `Hook.AfterCardDrawn` for EVERY card drawn from the draw pile
    // (`CardPileCmd.Draw`), regardless of whether the draw originated from
    // a turn-start hand draw or a card effect — so e.g. ConfusedPower
    // re-rolls the cost of a Slimed-drawn card. This path previously
    // bypassed the riders entirely, leaving the `combat_energy_costs`
    // cursor one read behind C# per card-effect draw under Confused
    // (FAKE_SNECKO_EYE coverage divergence). The rider walk is a no-op for
    // any combat without an on-draw power active. Deferred: the reshuffle
    // relic/`after_shuffle` buses are still only wired on the
    // `draw_into_hand` path.
    if moved > 0 {
        // C# `Slither.AfterCardDrawn` re-rolls the card's cost on EVERY
        // draw-pile draw regardless of origin — a Pommel Strike / Drum of
        // Battle / Pillage draw of a Slither card consumes a
        // `combat_energy_costs` read exactly like a turn-start draw (shadow
        // census v8: seeds 1003/1006/1042/1049). The rider walk below
        // dispatches the enchantment bus per card, after the power riders.
        let reported = state.last_drawn_card;
        state.invoke_card_drawn_for_newly_drawn(hand_len_before, false);
        // A rider's nested draw resets and re-sets the report; this draw
        // still returns its own card.
        state.last_drawn_card = reported;
    }
    // Bead `sts2-rs-od6vh`: keep `state.cards_drawn` (combat-wide
    // player-draw counter from sts2-rs-o05r) in sync with card-side
    // draws. `draw_into_hand` bumps it for combat-loop draws; before
    // this fix, card handlers that called `draw_via_state` directly
    // (e.g. Glow, Pillage, FlashOfSteel) silently bypassed the
    // counter. Murder's C# `CalculatedDamageVar` consumes this
    // counter as its multiplier — under-counted draws produced
    // under-counted damage.
    if let Ok(moved_u16) = u16::try_from(moved) {
        state.cards_drawn = state.cards_drawn.saturating_add(moved_u16);
    } else {
        state.cards_drawn = u16::MAX;
    }
    // Per-turn card-effect (non-hand) draw tally for Necrobinder DeathMarch's
    // `CalculatedDamageVar` multiplier (C# `CardDrawnEntry` count with
    // `!FromHandDraw`). Only the BATCH path lands here; the per-card loop
    // early-returns through `draw_suspending(n, false)` above, which tallies
    // each drawn card itself (so resumed-after-shuffle cards are not missed).
    if let Ok(moved_u16) = u16::try_from(moved) {
        state.combat_log.cards_drawn_by_effect_this_turn = state
            .combat_log
            .cards_drawn_by_effect_this_turn
            .saturating_add(moved_u16);
    }
    moved
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    /// `card_model_compare` is C# `CardModel.CompareTo`: slugified Entry
    /// (no `_CARD` suffix), then upgrade level.
    #[test]
    fn card_model_compare_keys_on_entry_then_upgrade() {
        let mk = |card_id, upgraded| Card {
            card_id,
            upgraded,
            ..Card::pod_defaults()
        };
        let thunder = mk(CardId::ThunderCard, false);
        let clap = mk(CardId::Thunderclap, false);
        assert_eq!(
            card_model_compare(&thunder, &clap),
            std::cmp::Ordering::Less,
            "THUNDER < THUNDERCLAP"
        );
        let clap_plus = mk(CardId::Thunderclap, true);
        assert_eq!(
            card_model_compare(&clap, &clap_plus),
            std::cmp::Ordering::Less
        );
        assert_eq!(card_model_compare(&clap, &clap), std::cmp::Ordering::Equal);
    }

    use super::*;

    /// C# `StableShuffle` pre-sorts with `CardModel.CompareTo` -> ordinal
    /// `ModelId.Entry` (`ModelDb.cs:535-538` Slugify of the class name):
    /// Defect's `Thunder` is `THUNDER`, which sorts before `THUNDERCLAP`. The
    /// Rust name `THUNDER_CARD` flipped that pair (act23 Ironclad seed 2068).
    #[test]
    fn reshuffle_rank_orders_by_csharp_entry_thunder_before_thunderclap() {
        assert_eq!(card_model_entry(CardId::ThunderCard), "THUNDER");
        assert_eq!(card_model_entry(CardId::Thunderclap), "THUNDERCLAP");
        assert!(reshuffle_rank(CardId::ThunderCard) < reshuffle_rank(CardId::Thunderclap));
        // Entries stay unique, so the rank is still a total order on cards.
        let all = CardId::all_for(crate::GameVersion::V0_111_0);
        let mut entries: Vec<&str> = all.iter().map(|&c| card_model_entry(c)).collect();
        entries.sort_unstable();
        let n = entries.len();
        entries.dedup();
        assert_eq!(entries.len(), n, "C# entries are unique");
    }
    use crate::{CardUid, PlayerCombatState};

    fn uid(n: u32) -> CardUid {
        CardUid::new(n).expect("non-zero")
    }

    /// `sts2-rs-pkpgr` (vxvvs.1): structural variant-count pin on
    /// [`EnchantmentId`]. The match arm below is exhaustive (the
    /// compiler enforces every variant is covered) and the assertion
    /// pins the total count at 23. Adding a 24th variant without
    /// updating either:
    ///   (a) the per-variant body-fill in the vxvvs umbrella, or
    ///   (b) this counter,
    /// fires this test BEFORE landing — turning a silent-no-handler
    /// regression into a build failure.
    ///
    /// Pairs with the vxvvs audit doc tracking which variants have
    /// non-stub production handlers. `Inky` (variant 23) is the first
    /// with a real production body — modeled directly in
    /// `cards::status::shiv::play_shiv` (Blade of Ink's generated Shivs).
    #[test]
    fn pkpgr_enchantment_id_variant_count_is_pinned_at_23() {
        // Helper that touches each variant exactly once; the compiler
        // refuses to compile if a variant is missing from the match.
        fn touch(id: EnchantmentId) -> u32 {
            match id {
                EnchantmentId::RoyallyApproved
                | EnchantmentId::Steady
                | EnchantmentId::TezcatarasEmber
                | EnchantmentId::SoulsPower
                | EnchantmentId::Instinct
                | EnchantmentId::Goopy
                | EnchantmentId::Sharp
                | EnchantmentId::Momentum
                | EnchantmentId::Corrupted
                | EnchantmentId::Favored
                | EnchantmentId::Vigorous
                | EnchantmentId::Nimble
                | EnchantmentId::Spiral
                | EnchantmentId::Glam
                | EnchantmentId::Adroit
                | EnchantmentId::Swift
                | EnchantmentId::Sown
                | EnchantmentId::Imbued
                | EnchantmentId::Slither
                | EnchantmentId::SlumberingEssence
                | EnchantmentId::PerfectFit
                | EnchantmentId::Clone
                | EnchantmentId::Inky => 1,
            }
        }
        // Enumerate every variant by listing each in an array. If a
        // new variant is added without updating this array, the
        // touch() match above still catches it via exhaustiveness;
        // this assertion locks the count in addition.
        let all: &[EnchantmentId] = &[
            EnchantmentId::RoyallyApproved,
            EnchantmentId::Steady,
            EnchantmentId::TezcatarasEmber,
            EnchantmentId::SoulsPower,
            EnchantmentId::Instinct,
            EnchantmentId::Goopy,
            EnchantmentId::Sharp,
            EnchantmentId::Momentum,
            EnchantmentId::Corrupted,
            EnchantmentId::Favored,
            EnchantmentId::Vigorous,
            EnchantmentId::Nimble,
            EnchantmentId::Spiral,
            EnchantmentId::Glam,
            EnchantmentId::Adroit,
            EnchantmentId::Swift,
            EnchantmentId::Sown,
            EnchantmentId::Imbued,
            EnchantmentId::Slither,
            EnchantmentId::SlumberingEssence,
            EnchantmentId::PerfectFit,
            EnchantmentId::Clone,
            EnchantmentId::Inky,
        ];
        let count: u32 = all.iter().map(|&id| touch(id)).sum();
        assert_eq!(
            count, 23,
            "EnchantmentId variant count drifted from 23 (got {count}); \
             update vxvvs body-fill audit + this pin in lockstep",
        );
        assert_eq!(
            all.len(),
            23,
            "EnchantmentId enumeration array out of sync with variant count"
        );
    }

    fn player_with_hand(uids: &[u32]) -> PlayerCombatState {
        let mut p = PlayerCombatState::default();
        for &n in uids {
            p.hand.push(uid(n));
        }
        p
    }

    #[test]
    fn move_card_uid_not_in_source_returns_err() {
        let mut p = player_with_hand(&[1, 2, 3]);
        let missing = uid(99);
        let res = move_card(&mut p, missing, PileKind::Hand, PileKind::Discard);
        assert_eq!(res, Err(PileError::NotInPile(missing, PileKind::Hand)));
        // Source pile untouched.
        assert_eq!(pile_len(&p, PileKind::Hand), 3);
        assert_eq!(pile_len(&p, PileKind::Discard), 0);
    }

    #[test]
    fn move_card_round_trip_preserves_pile_lens() {
        let mut p = player_with_hand(&[1, 2, 3, 4]);
        let target = uid(2);

        // Hand -> Discard.
        move_card(&mut p, target, PileKind::Hand, PileKind::Discard).expect("hand -> discard");
        assert_eq!(pile_len(&p, PileKind::Hand), 3);
        assert_eq!(pile_len(&p, PileKind::Discard), 1);
        assert!(pile_iter(&p, PileKind::Hand).all(|u| u != target));
        assert!(pile_iter(&p, PileKind::Discard).any(|u| u == target));

        // Order in remaining hand preserved.
        let rest: Vec<_> = pile_iter(&p, PileKind::Hand).map(CardUid::get).collect();
        assert_eq!(rest, vec![1, 3, 4]);

        // Discard -> Hand.
        move_card(&mut p, target, PileKind::Discard, PileKind::Hand).expect("discard -> hand");
        assert_eq!(pile_len(&p, PileKind::Hand), 4);
        assert_eq!(pile_len(&p, PileKind::Discard), 0);
        // After round trip, target is at the back of hand.
        let order: Vec<_> = pile_iter(&p, PileKind::Hand).map(CardUid::get).collect();
        assert_eq!(order, vec![1, 3, 4, 2]);
    }

    #[test]
    fn move_card_to_self_pile_is_idempotent_when_uid_present() {
        // Edge case: from == to. Validates uid is present, then performs
        // pop+push which moves the card to the back of its own pile.
        let mut p = player_with_hand(&[1, 2, 3]);
        move_card(&mut p, uid(1), PileKind::Hand, PileKind::Hand).expect("hand -> hand");
        let order: Vec<_> = pile_iter(&p, PileKind::Hand).map(CardUid::get).collect();
        assert_eq!(order, vec![2, 3, 1]);
    }

    #[test]
    fn is_hand_full_at_limit() {
        let mut p = PlayerCombatState::default();
        assert!(!is_hand_full(&p));

        let limit_u32 = u32::try_from(HAND_LIMIT).expect("HAND_LIMIT fits in u32");
        for i in 1..=limit_u32 {
            assert!(!is_hand_full(&p), "should not be full before {i}-th push");
            p.hand.push(uid(i));
        }
        assert_eq!(p.hand.len(), HAND_LIMIT);
        assert!(is_hand_full(&p));

        // Above the limit also reads as "full".
        p.hand.push(uid(limit_u32 + 1));
        assert!(is_hand_full(&p));
    }

    #[test]
    fn pile_len_consistent_with_iter_count() {
        let mut p = PlayerCombatState::default();
        p.hand.extend([uid(1), uid(2), uid(3)]);
        p.draw.extend([uid(10), uid(11)]);
        p.discard.push(uid(20));
        p.exhaust.extend([uid(30), uid(31), uid(32), uid(33)]);
        p.play.push(uid(40));

        for kind in [
            PileKind::Hand,
            PileKind::Draw,
            PileKind::Discard,
            PileKind::Exhaust,
            PileKind::Play,
        ] {
            let len = pile_len(&p, kind);
            let iter_count = pile_iter(&p, kind).count();
            assert_eq!(len, iter_count, "mismatch for {kind:?}");
        }
    }

    #[test]
    fn pile_kind_exhaustive_match() {
        // Compile-time check: every PileKind variant is handled in a
        // `match`. Adding a new variant without updating pile_len /
        // pile_iter / move_card will cause this test (and the primitives
        // themselves) to fail compilation, which is the safety property
        // we want.
        fn label(p: PileKind) -> &'static str {
            match p {
                PileKind::Hand => "hand",
                PileKind::Draw => "draw",
                PileKind::Discard => "discard",
                PileKind::Exhaust => "exhaust",
                PileKind::Play => "play",
            }
        }
        let all = [
            PileKind::Hand,
            PileKind::Draw,
            PileKind::Discard,
            PileKind::Exhaust,
            PileKind::Play,
        ];
        for k in all {
            assert!(!label(k).is_empty());
        }
    }

    #[test]
    fn card_pod_round_trips_clone_eq() {
        // The Card POD must satisfy Copy + Eq for use in arena stores.
        let c = Card {
            uid: uid(1),
            card_id: CardId::StrikeIronclad,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            combat_vars: CombatVars::new(),
            enchantments: CardEnchantments::new(),
            tags: CardTags::NONE,
            energy_spent: 0,
            base_replay_count: 0,
            keyword_override: None,
            affliction: None,
        };
        let c2 = c;
        assert_eq!(c, c2);
        assert_eq!(c.card_id, CardId::StrikeIronclad);
        assert_eq!(c.card_type, CardType::Attack);
        assert_eq!(c.target_type, TargetType::Enemy);
    }

    #[test]
    fn pile_error_message_includes_uid_and_pile() {
        let err = PileError::NotInPile(uid(7), PileKind::Hand);
        let msg = format!("{err}");
        assert!(msg.contains('7'), "msg = {msg}");
        assert!(msg.contains("Hand"), "msg = {msg}");
    }

    // -----------------------------------------------------------------
    // P1-2 (sts2-rs-8l3): draw / discard / shuffle / overflow tests
    // -----------------------------------------------------------------

    fn rng() -> crate::dotnet_rng::Rng {
        crate::dotnet_rng::Rng::new(0x00C0_FFEE_u32 as i32)
    }

    /// Empty card store for tests that drive draw/reshuffle on bare
    /// uids with no backing `Card` records. `card_entry` returns `""`
    /// for every uid against an empty store, so the reshuffle pre-sort
    /// is a stable no-op — preserving the set-equality semantics these
    /// tests assert. Tests that need the StableShuffle ordering build a
    /// populated store explicitly (see `reshuffle_uses_stable_shuffle_*`).
    fn empty_store() -> CardStore {
        CardStore::new()
    }

    #[test]
    fn draw_one_from_nonempty_draw_pile() {
        let mut p = PlayerCombatState::default();
        p.draw.extend([uid(1), uid(2), uid(3)]);
        let mut r = rng();
        let moved = draw(&mut p, 1, &empty_store(), &mut r);
        assert_eq!(moved, 1);
        assert_eq!(pile_len(&p, PileKind::Hand), 1);
        assert_eq!(pile_len(&p, PileKind::Draw), 2);
        // Python pops from index 0 — the "top" — so uid(1) should land in hand.
        assert_eq!(p.hand[0], uid(1));
    }

    #[test]
    fn draw_n_when_n_exceeds_draw_pile_size_triggers_reshuffle() {
        let mut p = PlayerCombatState::default();
        p.draw.extend([uid(1), uid(2), uid(3)]);
        p.discard.extend([uid(10), uid(11), uid(12), uid(13)]);
        let mut r = rng();
        let moved = draw(&mut p, 5, &empty_store(), &mut r);
        // 3 from draw + 4 reshuffled into draw, 2 more drawn = 5 total.
        assert_eq!(moved, 5);
        assert_eq!(pile_len(&p, PileKind::Hand), 5);
        // After reshuffle of 4 cards and drawing 2, 2 should remain in draw.
        assert_eq!(pile_len(&p, PileKind::Draw), 2);
        assert_eq!(pile_len(&p, PileKind::Discard), 0);

        // Set equality: every starting uid is now in (hand ∪ draw).
        let mut all: Vec<u32> = pile_iter(&p, PileKind::Hand)
            .chain(pile_iter(&p, PileKind::Draw))
            .map(CardUid::get)
            .collect();
        all.sort_unstable();
        assert_eq!(all, vec![1, 2, 3, 10, 11, 12, 13]);
    }

    #[test]
    fn draw_when_both_piles_empty_returns_actual_count() {
        let mut p = PlayerCombatState::default();
        let mut r = rng();
        let moved = draw(&mut p, 3, &empty_store(), &mut r);
        assert_eq!(moved, 0);
        assert_eq!(pile_len(&p, PileKind::Hand), 0);
        assert_eq!(pile_len(&p, PileKind::Draw), 0);
        assert_eq!(pile_len(&p, PileKind::Discard), 0);
    }

    #[test]
    fn draw_with_full_hand_breaks_loop() {
        // Mirrors `combat.py:1118-1120` at pin `01c094d`: when the hand is
        // already at MAX_HAND_SIZE at the top of an iteration, the draw
        // loop breaks. No cards are popped from the draw pile, no cards
        // are redirected to discard. This is the corrected behaviour
        // landed in bead sts2-rs-yr4 (P1-5).
        let mut p = PlayerCombatState::default();
        let limit_u32 = u32::try_from(HAND_LIMIT).expect("HAND_LIMIT fits");
        for i in 1..=limit_u32 {
            p.hand.push(uid(i));
        }
        for i in 100..105 {
            p.draw.push(uid(i));
        }
        let mut r = rng();
        let moved = draw(&mut p, 3, &empty_store(), &mut r);
        // Loop breaks immediately — no cards drawn, no cards redirected.
        assert_eq!(moved, 0);
        assert_eq!(pile_len(&p, PileKind::Hand), HAND_LIMIT);
        assert_eq!(pile_len(&p, PileKind::Draw), 5);
        assert_eq!(pile_len(&p, PileKind::Discard), 0);
        // Draw pile order untouched.
        let drawn: Vec<u32> = pile_iter(&p, PileKind::Draw).map(CardUid::get).collect();
        assert_eq!(drawn, vec![100, 101, 102, 103, 104]);
    }

    #[test]
    fn draw_stops_when_hand_fills_mid_loop() {
        // Hand has room for exactly 2 more cards; request 5. Should draw
        // 2 and break, leaving 3 cards in the draw pile (NOT redirected
        // to discard — this is the Python behaviour).
        let mut p = PlayerCombatState::default();
        let limit_u32 = u32::try_from(HAND_LIMIT).expect("HAND_LIMIT fits");
        // Fill hand to HAND_LIMIT - 2.
        for i in 1..=(limit_u32 - 2) {
            p.hand.push(uid(i));
        }
        for i in 100..105 {
            p.draw.push(uid(i));
        }
        let mut r = rng();
        let moved = draw(&mut p, 5, &empty_store(), &mut r);
        assert_eq!(moved, 2);
        assert_eq!(pile_len(&p, PileKind::Hand), HAND_LIMIT);
        assert_eq!(pile_len(&p, PileKind::Draw), 3);
        assert_eq!(pile_len(&p, PileKind::Discard), 0);
        // The two drawn cards should be the front of the original draw pile.
        let hand_tail: Vec<u32> = p.hand.iter().rev().take(2).map(|u| u.get()).collect();
        assert_eq!(hand_tail, vec![101, 100]);
        // Remaining draw pile order preserved.
        let remaining: Vec<u32> = pile_iter(&p, PileKind::Draw).map(CardUid::get).collect();
        assert_eq!(remaining, vec![102, 103, 104]);
    }

    #[test]
    fn discard_card_moves_to_discard() {
        let mut p = player_with_hand(&[1, 2, 3]);
        discard(&mut p, uid(2)).expect("discard from hand");
        assert_eq!(pile_len(&p, PileKind::Hand), 2);
        assert_eq!(pile_len(&p, PileKind::Discard), 1);
        let hand: Vec<u32> = pile_iter(&p, PileKind::Hand).map(CardUid::get).collect();
        assert_eq!(hand, vec![1, 3]);
        let disc: Vec<u32> = pile_iter(&p, PileKind::Discard).map(CardUid::get).collect();
        assert_eq!(disc, vec![2]);

        // Discarding a card not in hand returns the canonical NotInPile error.
        let err = discard(&mut p, uid(99));
        assert_eq!(err, Err(PileError::NotInPile(uid(99), PileKind::Hand)));
    }

    #[test]
    fn shuffle_preserves_card_set_and_count() {
        let mut p = PlayerCombatState::default();
        let originals: Vec<u32> = (1..=20).collect();
        for &n in &originals {
            p.draw.push(uid(n));
        }
        let before: Vec<u32> = pile_iter(&p, PileKind::Draw).map(CardUid::get).collect();

        let mut r = rng();
        shuffle(&mut p, &mut r);

        let after: Vec<u32> = pile_iter(&p, PileKind::Draw).map(CardUid::get).collect();
        // Same multiset.
        let mut a_sorted = after.clone();
        a_sorted.sort_unstable();
        assert_eq!(a_sorted, originals);
        // Same length.
        assert_eq!(after.len(), before.len());
        // With a seeded RNG and 20 cards, a shuffle should produce a
        // different ordering. (Probability of identity permutation on 20
        // distinct elements is 1/20!, vanishingly small.)
        assert_ne!(after, before, "seeded shuffle should permute the pile");

        // Determinism: same seed, same input -> same output.
        let mut p2 = PlayerCombatState::default();
        for &n in &originals {
            p2.draw.push(uid(n));
        }
        let mut r2 = rng();
        shuffle(&mut p2, &mut r2);
        let after2: Vec<u32> = pile_iter(&p2, PileKind::Draw).map(CardUid::get).collect();
        assert_eq!(after, after2, "same seed must produce same permutation");
    }

    /// Bead `sts2-rs-8ykzl`: when both draw AND discard are empty,
    /// discard_pile_into_draw_pile_signaling must return false (no
    /// shuffle happened) and leave both piles empty. This `false`
    /// signal drives whether the `after_shuffle` relic-bus channel
    /// fires (jlc), so a regression that returned true on the
    /// both-empty branch would spuriously fire downstream listeners.
    #[test]
    fn discard_pile_into_draw_pile_signaling_false_when_both_empty() {
        let mut p = PlayerCombatState::default();
        assert!(p.draw.is_empty());
        assert!(p.discard.is_empty());
        let mut r = rng();
        let shuffled = discard_pile_into_draw_pile_signaling(&mut p, &empty_store(), &mut r);
        assert!(
            !shuffled,
            "both-empty branch must signal false (no shuffle occurred)"
        );
        assert_eq!(pile_len(&p, PileKind::Draw), 0);
        assert_eq!(pile_len(&p, PileKind::Discard), 0);
    }

    #[test]
    fn discard_pile_into_draw_pile_noop_when_draw_nonempty() {
        let mut p = PlayerCombatState::default();
        p.draw.push(uid(1));
        p.discard.extend([uid(10), uid(11)]);
        let mut r = rng();
        discard_pile_into_draw_pile(&mut p, &empty_store(), &mut r);
        // No-op: draw was non-empty.
        assert_eq!(pile_len(&p, PileKind::Draw), 1);
        assert_eq!(pile_len(&p, PileKind::Discard), 2);
    }

    /// Build a [`CardStore`] where `cards[n-1].card_id == ids[n-1]` so a
    /// pile holding `uid(n)` resolves to `ids[n-1]`'s entry string.
    fn store_with_ids(ids: &[CardId]) -> CardStore {
        ids.iter()
            .enumerate()
            .map(|(i, &id)| Card {
                uid: uid(u32::try_from(i + 1).expect("fits")),
                card_id: id,
                ..Card::pod_defaults()
            })
            .collect()
    }

    /// F1 (2026-05-29 C#↔Rust parity-fuzz audit): the combat reshuffle
    /// must replicate C# `StableShuffle` —
    /// `MegaCrit.Sts2.Core.Commands/CardPileCmd.cs:820` →
    /// `ListExtensions.StableShuffle` does `Sort()` (by `ModelId`:
    /// Category then Entry, `StringComparison.Ordinal`) BEFORE the
    /// Fisher-Yates pass. The defining observable consequence is that the
    /// reshuffled draw pile is INDEPENDENT of the order cards entered the
    /// discard pile. This test pins both halves:
    ///
    /// 1. The output equals `sort-by-entry` then the same `rng.shuffle`
    ///    Fisher-Yates pass (computed independently here).
    /// 2. Two players with the same card multiset in DIFFERENT discard
    ///    orders, reshuffled with the SAME seed, produce IDENTICAL draw
    ///    piles — the property that was broken by the plain
    ///    `UnstableShuffle` (no pre-sort).
    #[test]
    fn reshuffle_uses_stable_shuffle_sort_by_id_then_fisher_yates() {
        // Entry strings (uid -> id): 1=BASH, 2=DEFEND_IRONCLAD,
        // 3=HEADBUTT, 4=PERFECTED_STRIKE, 5=SWORD_BOOMERANG. Ordinal
        // sort order is therefore exactly uid(1)..=uid(5).
        let ids = [
            CardId::Bash,
            CardId::DefendIronclad,
            CardId::Headbutt,
            CardId::PerfectedStrike,
            CardId::SwordBoomerang,
        ];
        let store = store_with_ids(&ids);

        // Player A: discard pushed in a scrambled order.
        let mut a = PlayerCombatState::default();
        a.discard.extend([uid(4), uid(1), uid(5), uid(2), uid(3)]);
        let mut ra = rng();
        let shuffled = discard_pile_into_draw_pile_signaling(&mut a, &store, &mut ra);
        assert!(shuffled);
        assert_eq!(pile_len(&a, PileKind::Discard), 0);

        // Independent recomputation: sort the multiset by entry string
        // (ordinal) -> [1,2,3,4,5], then run the identical Fisher-Yates
        // pass (same fresh seed). Must match the engine's output exactly.
        let mut expected: Vec<CardUid> = vec![uid(1), uid(2), uid(3), uid(4), uid(5)];
        expected.sort_by(|&x, &y| card_entry(&store, x).cmp(card_entry(&store, y)));
        let mut rb = rng();
        rb.shuffle(expected.as_mut_slice());
        let got: Vec<CardUid> = a.draw.iter().copied().collect();
        assert_eq!(
            got, expected,
            "reshuffle must be sort-by-entry then Fisher-Yates (StableShuffle)"
        );

        // Insertion-order independence: a different discard order with the
        // same seed yields the identical draw pile.
        let mut b = PlayerCombatState::default();
        b.discard.extend([uid(1), uid(2), uid(3), uid(4), uid(5)]);
        let mut rc = rng();
        discard_pile_into_draw_pile_signaling(&mut b, &store, &mut rc);
        assert_eq!(
            a.draw.as_slice(),
            b.draw.as_slice(),
            "StableShuffle output must be independent of discard insertion order"
        );

        // Sanity: the pre-sort actually reorders here — the plain
        // (no-presort) Fisher-Yates of A's original discard order would
        // differ, so the test is meaningful rather than vacuous.
        let mut raw: Vec<CardUid> = vec![uid(4), uid(1), uid(5), uid(2), uid(3)];
        let mut rd = rng();
        rd.shuffle(raw.as_mut_slice());
        assert_ne!(
            got, raw,
            "pre-sort must change the order vs a no-presort shuffle (regression guard)"
        );
    }

    /// Bead `sts2-rs-5aelq`: C# `CardModel.CompareTo`
    /// (`MegaCrit.Sts2.Core.Models/CardModel.cs:1745`) overrides the base
    /// `ModelId` comparator with a SECONDARY key — `CurrentUpgradeLevel`,
    /// ascending (base sorts before upgraded). The combat reshuffle's
    /// `StableShuffle` pre-sort (`CardPileCmd.cs:820`) uses that
    /// comparator, so two same-id cards that differ only in `upgraded`
    /// are NOT interchangeable in the pre-shuffle order: the base copy
    /// always sorts ahead of the upgraded copy, *independent* of the
    /// order they entered the discard pile.
    ///
    /// The Rust reshuffle pre-sorted by card-id entry ONLY, treating the
    /// two copies as equal and leaning on the stable sort to preserve
    /// discard order. That made the reshuffled slot of an in-hand-upgraded
    /// duplicate (e.g. an ARMAMENTS-upgraded TRUE_GRIT) depend on its
    /// discard position, diverging from C# — the seed-52 parity-fuzz
    /// divergence (C# drew TRUE_GRIT+ where Rust drew base TRUE_GRIT from
    /// the same id-identical pile). Pin it via the same insertion-order-
    /// independence property the entry sort already guarantees.
    #[test]
    fn reshuffle_orders_duplicate_ids_by_upgrade_level() {
        // Two TRUE_GRIT instances sharing one entry string: uid(1) base,
        // uid(2) upgraded. C#'s comparator ranks base < upgraded.
        let store: CardStore = [
            Card {
                uid: uid(1),
                card_id: CardId::TrueGrit,
                upgraded: false,
                ..Card::pod_defaults()
            },
            Card {
                uid: uid(2),
                card_id: CardId::TrueGrit,
                upgraded: true,
                ..Card::pod_defaults()
            },
        ]
        .into_iter()
        .collect();

        // Player A discards upgraded-then-base; player B base-then-upgraded
        // (the two copies swapped). Same seed for both reshuffles.
        let mut a = PlayerCombatState::default();
        a.discard.extend([uid(2), uid(1)]);
        let mut ra = rng();
        assert!(discard_pile_into_draw_pile_signaling(
            &mut a, &store, &mut ra
        ));

        let mut b = PlayerCombatState::default();
        b.discard.extend([uid(1), uid(2)]);
        let mut rb = rng();
        assert!(discard_pile_into_draw_pile_signaling(
            &mut b, &store, &mut rb
        ));

        // StableShuffle canonicalizes the pre-shuffle order by
        // (ModelId, CurrentUpgradeLevel), so the reshuffled draw pile is
        // independent of discard insertion order even for same-id cards
        // distinguished only by `upgraded`. The entry-only sort broke
        // this — the upgraded copy followed its discard position.
        assert_eq!(
            a.draw.as_slice(),
            b.draw.as_slice(),
            "reshuffle must order duplicate ids by upgrade level (base < upgraded), \
             independent of discard order"
        );
    }

    /// Bead `sts2-rs-s2pr8`: the explicit shuffle (C# `CardPileCmd.Shuffle`,
    /// used by Reboot / BottledPotential) merges the **discard pile** into
    /// draw — unconditionally, unlike the auto-reshuffle — and applies the
    /// same `(Entry, upgrade)` StableShuffle pre-sort.
    #[test]
    fn shuffle_draw_and_discard_merges_discard_and_presorts() {
        let store: CardStore = [
            Card {
                uid: uid(1),
                card_id: CardId::TrueGrit,
                upgraded: false,
                ..Card::pod_defaults()
            },
            Card {
                uid: uid(2),
                card_id: CardId::TrueGrit,
                upgraded: true,
                ..Card::pod_defaults()
            },
        ]
        .into_iter()
        .collect();

        // Draw pile non-empty (the auto-reshuffle would NOT fire here);
        // the explicit shuffle must still pull discard in and empty it.
        let mut a = PlayerCombatState::default();
        a.draw.push(uid(2)); // upgraded already in draw
        a.discard.push(uid(1)); // base in discard
        let mut ra = rng();
        shuffle_draw_and_discard(&mut a, &store, &mut ra);
        assert!(a.discard.is_empty(), "discard must be emptied into draw");
        assert_eq!(a.draw.len(), 2, "both cards end up in the draw pile");

        // Insertion-order independence: swap which pile each copy starts in.
        let mut b = PlayerCombatState::default();
        b.draw.push(uid(1)); // base in draw
        b.discard.push(uid(2)); // upgraded in discard
        let mut rb = rng();
        shuffle_draw_and_discard(&mut b, &store, &mut rb);
        assert_eq!(
            a.draw.as_slice(),
            b.draw.as_slice(),
            "explicit shuffle pre-sort must be independent of which pile each \
             duplicate-id copy started in"
        );
    }

    /// C# resolves a card's cost as `max(0, base + this-combat modifiers)`,
    /// so upgrading a Banshee's Cry its Ethereal discounts already took to 0
    /// (9 -> 7) leaves it at 0. Rust added the -2 delta to the stored 0 and
    /// the -2 read as the X-cost sentinel (act23 Necrobinder:1014).
    #[test]
    fn upgrade_keeps_a_fully_discounted_cost_at_zero() {
        let build = |cost: i8| Card {
            card_id: CardId::BansheesCry,
            cost,
            card_type: CardType::Attack,
            ..Card::pod_defaults()
        };
        let mut card = build(0);
        assert!(card.upgrade_with(|_, up| Some(build(if up { 7 } else { 9 }))));
        assert_eq!(card.cost, 0);

        // An X-cost card keeps its sentinel.
        let mut x = build(-1);
        assert!(x.upgrade_with(|_, _| Some(build(-1))));
        assert_eq!(x.cost, -1);
    }

    /// C# `CardPileCmd.Shuffle` merges DISCARD first, then draw
    /// (`CardPileCmd.cs:1077-1088`). Above 16 cards the introsort pre-sort
    /// permutes identical copies by input position, so the merge order picks
    /// which copy lands where (act23 Necrobinder:1018: an enchanted Defend 8
    /// slots off).
    #[test]
    fn shuffle_draw_and_discard_merges_discard_before_draw() {
        let store: CardStore = (1..=17)
            .map(|i| Card {
                uid: uid(i),
                card_id: CardId::TrueGrit,
                ..Card::pod_defaults()
            })
            .collect();
        let mut p = PlayerCombatState::default();
        p.draw.push(uid(1));
        p.discard.extend((2..=17).map(uid));
        let mut r = rng();
        shuffle_draw_and_discard(&mut p, &store, &mut r);

        let mut expected = PlayerCombatState::default();
        expected.draw.extend((2..=17).map(uid));
        expected.draw.push(uid(1));
        presort_draw_for_reshuffle(&mut expected, &store);
        let mut re = rng();
        shuffle(&mut expected, &mut re);
        assert_eq!(p.draw.as_slice(), expected.draw.as_slice());
    }

    #[test]
    fn try_add_to_hand_redirects_when_full() {
        let mut p = PlayerCombatState::default();
        let limit_u32 = u32::try_from(HAND_LIMIT).expect("HAND_LIMIT fits");
        for i in 1..=limit_u32 {
            assert!(try_add_to_hand(&mut p, uid(i)));
        }
        assert_eq!(pile_len(&p, PileKind::Hand), HAND_LIMIT);
        // The (limit+1)-th add returns false and lands in discard.
        assert!(!try_add_to_hand(&mut p, uid(limit_u32 + 1)));
        assert_eq!(pile_len(&p, PileKind::Hand), HAND_LIMIT);
        assert_eq!(pile_len(&p, PileKind::Discard), 1);
    }

    // -----------------------------------------------------------------
    // P7-surf (sts2-rs-3f8): CardInstance enchantment / upgrade / clone
    // -----------------------------------------------------------------

    fn sample_card(u: u32) -> Card {
        Card {
            uid: uid(u),
            card_id: CardId::StrikeIronclad,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            combat_vars: crate::cards::CombatVars::new(),
            enchantments: crate::cards::CardEnchantments::new(),
            tags: CardTags::one(CardTag::Strike),
            energy_spent: 0,
            base_replay_count: 0,
            keyword_override: None,
            affliction: None,
        }
    }

    /// Bead `sts2-rs-d7vsb`: set_combat_var overwrites an existing
    /// key in-place (cards.rs:398-405) and inserts a new entry when
    /// absent. Sibling to btj7k (set_enchantment) for the
    /// combat_vars vec. A drive-by that always pushed (no in-place
    /// mutation) would silently grow combat_vars unboundedly AND
    /// shadow newer values behind stale entries because combat_var()
    /// `find_map`s the FIRST match (line 393).
    #[test]
    fn set_combat_var_overwrites_existing_key_and_inserts_when_absent() {
        let mut c = sample_card(1);
        assert_eq!(
            c.combat_var(VarKey::RampageDamage),
            0,
            "default absent reads 0"
        );
        // Insert.
        c.set_combat_var(VarKey::RampageDamage, 7);
        assert_eq!(c.combat_var(VarKey::RampageDamage), 7);
        let len_after_insert = c.combat_vars.len();
        // Overwrite — combat_vars length must NOT grow.
        c.set_combat_var(VarKey::RampageDamage, 12);
        assert_eq!(c.combat_var(VarKey::RampageDamage), 12);
        assert_eq!(
            c.combat_vars.len(),
            len_after_insert,
            "overwrite must mutate in place — vec length must not grow"
        );
        // A distinct key inserts a separate slot, doesn't touch the first.
        c.set_combat_var(VarKey::ClawBuff, 3);
        assert_eq!(c.combat_var(VarKey::ClawBuff), 3);
        assert_eq!(
            c.combat_var(VarKey::RampageDamage),
            12,
            "unrelated key insert must not disturb existing slot"
        );
        assert_eq!(c.combat_vars.len(), len_after_insert + 1);
    }

    /// GH #474: `CombatVars` capacity must hold the worst-case set of
    /// DISTINCT keys one card can legitimately accumulate. Slots are never
    /// reclaimed — clearing a var writes 0 in place (the live prefix is
    /// equality/hash-visible, see `inline_kv` module docs) — so over a long
    /// combat a single card can collect every generic flag it ever touched
    /// (`FreeThisTurn`, `EtherealThisCombat`, `StarCostFreeThisCombat`,
    /// `SneckoCostDeltaThisTurn`, `SneckoRollLive`, `CostAbsolutelySet`, `IsDupe`,
    /// `GeneratedInCombat`, `PendingBatchAutoPlay`,
    /// `DampenDowngradedMarker`, `Generic`) PLUS the wire-reconstruction
    /// cost trio PLUS its card-specific keys (Thrash carries two). At the
    /// old capacity 8 the 9th distinct key panicked mid-run (Ironclad A10
    /// seed 41100016, `CostAbsolutelySet` via net_search forks).
    #[test]
    fn combat_vars_capacity_holds_worst_case_distinct_key_set() {
        // 16 keys: 11 generic + 3 wire trio + Thrash's pair.
        let worst_case = [
            VarKey::FreeThisTurn,
            VarKey::EtherealThisCombat,
            VarKey::StarCostFreeThisCombat,
            VarKey::SneckoCostDeltaThisTurn,
            VarKey::SneckoRollLive,
            VarKey::CostAbsolutelySet,
            VarKey::IsDupe,
            VarKey::GeneratedInCombat,
            VarKey::PendingBatchAutoPlay,
            VarKey::DampenDowngradedMarker,
            VarKey::EnchantmentUsed,
            VarKey::WireTransientCostThisTurn,
            VarKey::WireCostExpiringOnPlay,
            VarKey::WireCostStable,
            VarKey::ThrashFoldRemNum,
            VarKey::ThrashFoldRemDen,
        ];
        let mut c = sample_card(1);
        for (i, key) in worst_case.iter().enumerate() {
            c.set_combat_var(*key, i as i32 + 1);
        }
        for (i, key) in worst_case.iter().enumerate() {
            assert_eq!(c.combat_var(*key), i as i32 + 1, "slot {key:?} lost");
        }
    }

    /// Bead `sts2-rs-q8uap`: is_x_cost returns true iff cost == -1
    /// AND card_type is NOT Curse/Status. Used by play_card to decide
    /// whether to drain state.player.energy into energy_spent. A
    /// regression that dropped the Curse/Status carve-out would
    /// silently let UNPLAYABLE Curse/Status sentinels (which use
    /// cost=-1 in Python) drain energy on every draw.
    #[test]
    fn is_upgradable_excludes_curses_statuses_and_upgraded() {
        // Bead `sts2-rs-tye89` (R3 lever 2): IsUpgradable parity.
        // Un-upgraded Attack/Skill/Power → upgradable.
        for ty in [CardType::Attack, CardType::Skill, CardType::Power] {
            let mut c = sample_card(1);
            c.card_type = ty;
            c.upgraded = false;
            assert!(c.is_upgradable(), "un-upgraded {ty:?} is upgradable");
        }
        // Already upgraded → not upgradable (MaxUpgradeLevel reached).
        let mut up = sample_card(1);
        up.card_type = CardType::Attack;
        up.upgraded = true;
        assert!(!up.is_upgradable(), "upgraded card is not upgradable");
        // Curse / Status (MaxUpgradeLevel=0, e.g. INFECTION) → never
        // upgradable even when un-upgraded.
        for ty in [CardType::Curse, CardType::Status] {
            let mut c = sample_card(1);
            c.card_type = ty;
            c.upgraded = false;
            assert!(!c.is_upgradable(), "{ty:?} is never upgradable");
        }
    }

    #[test]
    fn is_x_cost_gates_on_negative_one_and_non_curse_status() {
        // True case: cost == -1 + Attack/Skill/Power.
        for ty in [CardType::Attack, CardType::Skill, CardType::Power] {
            let mut c = sample_card(1);
            c.cost = -1;
            c.card_type = ty;
            assert!(c.is_x_cost(), "X-cost {ty:?} (cost=-1) must read true");
        }
        // False case: cost == -1 but Curse/Status (UNPLAYABLE sentinel).
        for ty in [CardType::Curse, CardType::Status] {
            let mut c = sample_card(1);
            c.cost = -1;
            c.card_type = ty;
            assert!(
                !c.is_x_cost(),
                "UNPLAYABLE {ty:?} sentinel (cost=-1) must NOT read as X-cost"
            );
        }
        // False case: cost != -1, any type.
        for cost in [0, 1, 2, 3] {
            let mut c = sample_card(1);
            c.cost = cost;
            c.card_type = CardType::Attack;
            assert!(!c.is_x_cost(), "cost={cost} cannot be X-cost");
        }
    }

    /// Bead `sts2-rs-cz7n6`: reset_combat_vars clears combat_vars
    /// and zeros energy_spent (cards.rs:526). It deliberately does
    /// NOT touch enchantments (persistent across combats per
    /// FresnelLens semantics) or the `upgraded` flag. A drive-by that
    /// added `.enchantments.clear()` or `.upgraded = false` would
    /// silently destroy persistent state at every combat reset.
    #[test]
    fn reset_combat_vars_preserves_enchantments_and_upgraded() {
        let mut c = sample_card(1);
        c.set_combat_var(VarKey::FreeThisTurn, 1);
        c.energy_spent = 4;
        c.add_enchantment(EnchantmentId::Sharp, 3);
        assert!(c.upgrade(), "first upgrade flips");
        assert!(c.upgraded);

        c.reset_combat_vars();

        // Cleared:
        assert_eq!(c.combat_var(VarKey::FreeThisTurn), 0, "combat_vars cleared");
        assert_eq!(c.energy_spent, 0, "energy_spent zeroed");
        // Preserved:
        assert_eq!(
            c.enchantment(EnchantmentId::Sharp),
            3,
            "enchantments are persistent — reset must NOT touch them"
        );
        assert!(c.upgraded, "upgraded flag is persistent");
    }

    /// Bead `sts2-rs-iyjcb`: add_enchantment uses saturating_add
    /// (cards.rs:440) to defend against overflow when callers push
    /// deltas past i32::MAX. Locks the saturation invariant — a
    /// drive-by replacing saturating_add with += would silently wrap
    /// to negative values, breaking has_enchantment (which gates on
    /// `> 0`).
    #[test]
    fn add_enchantment_saturates_at_i32_max() {
        let mut c = sample_card(1);
        c.set_enchantment(EnchantmentId::Sharp, i32::MAX - 1);
        c.add_enchantment(EnchantmentId::Sharp, 5);
        assert_eq!(c.enchantment(EnchantmentId::Sharp), i32::MAX);
        // Adding more at the cap remains saturated, NOT wrapped.
        c.add_enchantment(EnchantmentId::Sharp, 100);
        assert_eq!(c.enchantment(EnchantmentId::Sharp), i32::MAX);
        assert!(c.has_enchantment(EnchantmentId::Sharp));
    }

    /// Bead `sts2-rs-btj7k`: set_enchantment overwrites an existing
    /// entry (vs add_enchantment which sums) AND has_enchantment
    /// treats amount<=0 as absent (line 420 `> 0`). Both are subtle
    /// contracts a refactor could silently break.
    #[test]
    fn set_enchantment_overwrites_and_zero_reads_as_absent() {
        let mut c = sample_card(1);
        // Initial insert via set.
        c.set_enchantment(EnchantmentId::Sharp, 3);
        assert_eq!(c.enchantment(EnchantmentId::Sharp), 3);
        assert!(c.has_enchantment(EnchantmentId::Sharp));
        // Overwrite, not sum.
        c.set_enchantment(EnchantmentId::Sharp, 1);
        assert_eq!(c.enchantment(EnchantmentId::Sharp), 1);
        // set to 0 — entry still exists internally, but has_enchantment
        // reports absent (the `> 0` gate at line 420).
        c.set_enchantment(EnchantmentId::Sharp, 0);
        assert_eq!(c.enchantment(EnchantmentId::Sharp), 0);
        assert!(!c.has_enchantment(EnchantmentId::Sharp));
        // Negative amount: also reported absent.
        c.set_enchantment(EnchantmentId::Sharp, -2);
        assert!(!c.has_enchantment(EnchantmentId::Sharp));
    }

    #[test]
    fn add_enchantment_stacks() {
        // Repeated `add_enchantment` calls accumulate the stack count.
        // Mirrors Python `CardInstance.add_enchantment(name, amount)`
        // additive stacking semantics used by FresnelLens-style multi-
        // application.
        let mut c = sample_card(1);
        assert_eq!(c.enchantment(EnchantmentId::Sharp), 0);
        c.add_enchantment(EnchantmentId::Sharp, 1);
        c.add_enchantment(EnchantmentId::Sharp, 2);
        assert_eq!(c.enchantment(EnchantmentId::Sharp), 3);
        assert!(c.has_enchantment(EnchantmentId::Sharp));
        // Distinct kinds live in distinct slots.
        c.add_enchantment(EnchantmentId::Nimble, 1);
        assert_eq!(c.enchantment(EnchantmentId::Sharp), 3);
        assert_eq!(c.enchantment(EnchantmentId::Nimble), 1);
    }

    #[test]
    fn upgrade_idempotency() {
        // Mirrors Python's `if card.upgraded: return card` early-exit:
        // the first upgrade flips the flag and reports `true`, the
        // second reports `false` and leaves the card unchanged.
        let mut c = sample_card(1);
        assert!(!c.upgraded);
        assert!(c.upgrade());
        assert!(c.upgraded);
        let before = c;
        assert!(!c.upgrade());
        assert!(c.upgraded);
        assert_eq!(c, before);
    }

    /// C# `CardCmd.Upgrade` skips a card that isn't `IsUpgradable`
    /// (`CardCmd.cs:273-276`): a curse (Ascender's Bane), a status or a
    /// Quest card is left as it is on every upgrade path, in either build.
    #[test]
    fn upgrade_refuses_a_card_that_is_not_upgradable() {
        for (card_id, card_type) in [
            (CardId::AscendersBane, CardType::Curse),
            (CardId::Wound, CardType::Status),
            (CardId::SpoilsMap, CardType::Quest),
        ] {
            let mut c = Card {
                card_id,
                card_type,
                ..sample_card(1)
            };
            let before = c;
            assert!(!c.upgrade(), "{card_id:?}");
            assert!(!c.upgrade_for(crate::GameVersion::V0_111_0), "{card_id:?}");
            assert_eq!(c, before, "{card_id:?}");
        }
    }

    #[test]
    fn clone_determinism_with_seed() {
        // Same source + same seed -> same clone. Different seeds change
        // only the `uid` field (the load-bearing instance identifier).
        let src = sample_card(7);
        let a = src.clone_with_seed(0xDEAD_BEEF_CAFE_F00D);
        let b = src.clone_with_seed(0xDEAD_BEEF_CAFE_F00D);
        assert_eq!(a, b);
        // Differing seeds permute the uid.
        let c = src.clone_with_seed(0x1234_5678_9ABC_DEF0);
        assert_ne!(a.uid, c.uid);
        // Non-uid fields are unaffected by seed.
        let mut a_no_uid = a;
        a_no_uid.uid = c.uid;
        assert_eq!(a_no_uid, c);
        // Even a zero-seed clones to a valid (non-zero) uid.
        let z = src.clone_with_seed(0);
        assert_eq!(z.uid.0.get(), 1);
    }

    #[test]
    fn card_tag_query_roundtrip() {
        // `CardInstance.has_tag(CardTag.STRIKE)` in Python -> Rust
        // `card.has_tag(CardTag::Strike)` round-trip.
        let mut c = sample_card(1);
        assert!(c.has_tag(CardTag::Strike));
        assert!(!c.has_tag(CardTag::Defend));
        // The bit-packed set round-trips.
        let view = c.card_tags();
        assert!(view.contains(CardTag::Strike));
        assert!(!view.contains(CardTag::Defend));
        // Adding tags via `CardTags::with` is non-destructive.
        c.tags = c.tags.with(CardTag::Defend);
        assert!(c.has_tag(CardTag::Strike));
        assert!(c.has_tag(CardTag::Defend));
        // Vec round-trip ordering matches enum discriminant order.
        let v = c.card_tags().to_vec();
        assert_eq!(v.as_slice(), &[CardTag::Strike, CardTag::Defend]);
        // Empty set => `is_empty`.
        assert!(CardTags::NONE.is_empty());
        assert!(!c.card_tags().is_empty());
    }

    #[test]
    fn surface_integration_enchant_upgrade_clone_tags_compose() {
        // End-to-end roundtrip that exercises every entry point this
        // bead lands: `add_enchantment`, `upgrade`, `clone_with_seed`,
        // `has_tag`. Mirrors the call shape downstream relic bodies
        // (FresnelLens, BoneTea, HistoryCourse, FakeStrikeDummy) will
        // use once `sts2-rs-01o` retrofits them. The `CardCtx`
        // placeholder in `hooks.rs` is the planned home for a
        // `&CardInstance` field once the upstream hook-bus bead
        // `sts2-rs-2ax` lands — this test pins the surface so that
        // wiring can happen without further changes to `Card`.
        let base = sample_card(42);

        // 1. Stack a "Nimble" enchantment (FresnelLens behavior).
        let mut enchanted = base;
        enchanted.add_enchantment(EnchantmentId::Nimble, 2);
        assert_eq!(enchanted.enchantment(EnchantmentId::Nimble), 2);

        // 2. Upgrade in place (BoneTea behavior).
        assert!(enchanted.upgrade());
        assert!(enchanted.upgraded);

        // 3. Deterministic clone with a fresh seed (HistoryCourse / FakeStrikeDummy).
        let dup = enchanted.clone_with_seed(0xC0FFEE_u64);
        assert_eq!(dup.enchantment(EnchantmentId::Nimble), 2);
        assert!(dup.upgraded);
        // Clone preserves tags exactly.
        assert!(dup.has_tag(CardTag::Strike));
        // Clone's uid is distinct from the source.
        assert_ne!(dup.uid, enchanted.uid);

        // 4. FakeStrikeDummy-style tag query on the clone.
        assert!(dup.has_tag(CardTag::Strike));
    }

    #[test]
    fn card_tag_bit_positions_match_python_enum_order() {
        // CardTag variant order is load-bearing: it pins the bit
        // positions used by [`CardTags`] across pin bumps. If a Python
        // pin bump inserts a new tag mid-list, this assertion breaks
        // first.
        assert_eq!(CardTag::Strike as u8, 0);
        assert_eq!(CardTag::Defend as u8, 1);
        assert_eq!(CardTag::Minion as u8, 2);
        assert_eq!(CardTag::OstyAttack as u8, 3);
        assert_eq!(CardTag::Shiv as u8, 4);
        assert_eq!(CardTag::Strike.bit(), 0b0_0001);
        assert_eq!(CardTag::Shiv.bit(), 0b1_0000);
    }

    // -----------------------------------------------------------------
    // Bead `sts2-rs-o6xw`: pinned-position preservation across shuffles
    // -----------------------------------------------------------------

    /// A pinned top-of-draw card draws first across many independent
    /// determinizations (different RNG seeds = different shuffles).
    #[test]
    fn pinned_top_card_draws_first_across_100_determinizations() {
        let pinned = uid(7);
        for seed in 0u64..100 {
            let mut p = PlayerCombatState::default();
            for n in 1..=20u32 {
                p.draw.push(uid(n));
            }
            // Pin uid(7) to top.
            pin_top(&mut p, pinned);
            let mut r = crate::dotnet_rng::Rng::new((seed) as i32);
            shuffle(&mut p, &mut r);
            assert_eq!(
                p.draw.first().copied(),
                Some(pinned),
                "seed {seed}: pinned card should be at top of draw after shuffle"
            );
            // Draw consumes the pin.
            let moved = draw(&mut p, 1, &empty_store(), &mut r);
            assert_eq!(moved, 1);
            assert_eq!(p.hand.last().copied(), Some(pinned));
            assert!(
                !p.pinned_top.contains(&pinned),
                "drawing the pinned card must clear its pin"
            );
        }
    }

    /// A pinned bottom-of-draw card draws last after a full draw cycle.
    #[test]
    fn pinned_bottom_card_draws_last_after_full_cycle() {
        let pinned = uid(13);
        for seed in 0u64..50 {
            let mut p = PlayerCombatState::default();
            for n in 1..=15u32 {
                p.draw.push(uid(n));
            }
            pin_bottom(&mut p, pinned);
            let mut r = crate::dotnet_rng::Rng::new((seed) as i32);
            shuffle(&mut p, &mut r);
            assert_eq!(
                p.draw.last().copied(),
                Some(pinned),
                "seed {seed}: bottom-pinned card should be last in draw after shuffle"
            );
            // Draw all 15 — pinned card must come out last.
            // Hand limit is 10 so we draw to fill, then move some to discard
            // to keep drawing. Simpler: peek the order directly.
            let order: Vec<CardUid> = p.draw.iter().copied().collect();
            assert_eq!(order.last().copied(), Some(pinned));
        }
    }

    /// `sts2-rs-xo223`: edge case where `top + bot` cover ALL cards
    /// in draw — the unpinned `middle` is empty, so the inner
    /// `middle.as_mut_slice().shuffle(rng)` branch is skipped. The
    /// reconstruction (clear + extend top + extend middle + extend
    /// bot) must yield exactly `top ++ bot` (deterministic, no RNG
    /// influence). A regression that:
    ///   - extended in wrong order (bot before top), or
    ///   - failed to clear() before extending,
    /// would silently corrupt the pinned ordering without tripping
    /// any of the existing shuffle / pin-ordering tests.
    #[test]
    fn shuffle_all_pinned_no_middle_yields_top_then_bot() {
        let mut p = PlayerCombatState::default();
        p.draw.extend([uid(1), uid(2), uid(3)]);
        pin_top(&mut p, uid(1));
        pin_top(&mut p, uid(2));
        pin_bottom(&mut p, uid(3));
        // After pin_top calls (LIFO), pinned_top = [uid(2), uid(1)].
        assert_eq!(p.pinned_top.as_slice(), &[uid(2), uid(1)]);
        assert_eq!(p.pinned_bottom.as_slice(), &[uid(3)]);
        // Sanity check: every card in draw is pinned, so middle = [].
        let middle_count = p
            .draw
            .iter()
            .filter(|u| !p.pinned_top.contains(u) && !p.pinned_bottom.contains(u))
            .count();
        assert_eq!(middle_count, 0, "test premise: middle must be empty");

        let mut r = crate::dotnet_rng::Rng::new(0xDEAD_BEEF_u32 as i32);
        shuffle(&mut p, &mut r);

        // Result is deterministic: top ++ middle ++ bot
        // = [uid(2), uid(1)] ++ [] ++ [uid(3)].
        assert_eq!(p.draw.as_slice(), &[uid(2), uid(1), uid(3)]);

        // Re-shuffling with a different seed produces the same result —
        // confirms no RNG influence when middle is empty.
        let mut r2 = crate::dotnet_rng::Rng::new(0xBADF00D_u32 as i32);
        shuffle(&mut p, &mut r2);
        assert_eq!(
            p.draw.as_slice(),
            &[uid(2), uid(1), uid(3)],
            "second shuffle with different seed must yield identical draw",
        );
    }

    /// Headbutt-on-Headbutt stacking: the most recently pinned card sits
    /// at `Top(0)` and demotes the previous pin to `Top(1)`.
    #[test]
    fn pin_top_stacks_lifo() {
        let mut p = PlayerCombatState::default();
        for n in 1..=10u32 {
            p.draw.push(uid(n));
        }
        pin_top(&mut p, uid(3));
        pin_top(&mut p, uid(7));
        // pinned_top is in draw-order: index 0 = next-drawn = uid(7), then uid(3).
        assert_eq!(p.pinned_top.as_slice(), &[uid(7), uid(3)]);
        let mut r = crate::dotnet_rng::Rng::new(0xDEAD_BEEF_u32 as i32);
        shuffle(&mut p, &mut r);
        assert_eq!(p.draw.first().copied(), Some(uid(7)));
        assert_eq!(p.draw.get(1).copied(), Some(uid(3)));
    }

    /// Bead `sts2-rs-7earr`: pin_bottom sibling of ksn7z. A stale uid
    /// (not in draw) must silently land in `pinned_bottom` AND be
    /// dropped on the next shuffle via the retain-against-draw filter
    /// (cards.rs:725).
    #[test]
    fn pin_bottom_with_uid_not_in_draw_is_silent_then_dropped_on_shuffle() {
        let mut p = PlayerCombatState::default();
        p.draw.extend([uid(1), uid(2)]);
        let stale = uid(99);
        assert!(!p.draw.contains(&stale));
        pin_bottom(&mut p, stale);
        assert_eq!(p.pinned_bottom.as_slice(), &[stale]);
        let mut r = crate::dotnet_rng::Rng::new(0xC0FFEE_u32 as i32);
        shuffle(&mut p, &mut r);
        assert!(
            p.pinned_bottom.is_empty(),
            "shuffle must drop the stale bottom pin via retain-against-draw"
        );
    }

    /// Bead `sts2-rs-ksn7z`: pin_top accepts uids not currently in draw
    /// (the doc-comment notes "stale pin lifetime is best-effort"), so
    /// the stale pin must silently land in `pinned_top` AND be dropped
    /// on the next shuffle when the retain-against-draw filter fires.
    #[test]
    fn pin_top_with_uid_not_in_draw_is_silent_then_dropped_on_shuffle() {
        let mut p = PlayerCombatState::default();
        p.draw.extend([uid(1), uid(2)]);
        let stale = uid(99);
        // Precondition: stale_uid is NOT in draw.
        assert!(!p.draw.contains(&stale));
        pin_top(&mut p, stale);
        // Silently accepted into pinned_top.
        assert_eq!(p.pinned_top.as_slice(), &[stale]);
        // First shuffle: retain drops stale (not in draw).
        let mut r = crate::dotnet_rng::Rng::new(0xC0FFEE_u32 as i32);
        shuffle(&mut p, &mut r);
        assert!(
            p.pinned_top.is_empty(),
            "shuffle must drop the stale pin via retain-against-draw"
        );
    }

    /// Reshuffle (discard -> draw on empty draw) clears all pins.
    #[test]
    fn reshuffle_clears_all_pins() {
        let mut p = PlayerCombatState::default();
        // Draw is empty; pins are set (a pathological state — pre-reshuffle
        // these would refer to cards that are no longer in draw).
        p.discard.extend([uid(1), uid(2), uid(3)]);
        // Manually inject pins to verify they are cleared regardless of
        // whether the pinned uid is in any pile.
        p.pinned_top.push(uid(99));
        p.pinned_bottom.push(uid(88));
        let mut r = crate::dotnet_rng::Rng::new(42_i32);
        discard_pile_into_draw_pile(&mut p, &empty_store(), &mut r);
        assert!(p.pinned_top.is_empty(), "pinned_top must be cleared");
        assert!(p.pinned_bottom.is_empty(), "pinned_bottom must be cleared");
        assert_eq!(p.draw.len(), 3);
    }

    /// Property: shuffle never reorders pinned cards relative to each
    /// other. Across many seeds and pin configurations, the sequence of
    /// pinned-top entries observed in the post-shuffle draw pile must
    /// equal `pinned_top` itself; symmetric for `pinned_bottom`.
    #[test]
    fn shuffle_preserves_relative_order_of_pinned_cards() {
        for seed in 0u64..200 {
            let mut p = PlayerCombatState::default();
            for n in 1..=20u32 {
                p.draw.push(uid(n));
            }
            // Multi-pin: pin three cards on top (LIFO so order is [u(5),u(2),u(11)])
            pin_top(&mut p, uid(11));
            pin_top(&mut p, uid(2));
            pin_top(&mut p, uid(5));
            // And two on the bottom.
            pin_bottom(&mut p, uid(17));
            pin_bottom(&mut p, uid(9));
            let top_snapshot = p.pinned_top.clone();
            let bot_snapshot = p.pinned_bottom.clone();

            let mut r = crate::dotnet_rng::Rng::new((seed) as i32);
            shuffle(&mut p, &mut r);

            // The first |top_snapshot| draw entries must equal top_snapshot.
            let prefix: Vec<CardUid> = p.draw.iter().take(top_snapshot.len()).copied().collect();
            assert_eq!(prefix, top_snapshot.as_slice(), "seed {seed}: top prefix");
            // The last |bot_snapshot| draw entries must equal bot_snapshot.
            let n_draw = p.draw.len();
            let suffix: Vec<CardUid> = p
                .draw
                .iter()
                .skip(n_draw - bot_snapshot.len())
                .copied()
                .collect();
            assert_eq!(suffix, bot_snapshot.as_slice(), "seed {seed}: bot suffix");
            // Multiset over draw is preserved (no card lost).
            let mut all: Vec<u32> = p.draw.iter().map(|u| u.get()).collect();
            all.sort_unstable();
            assert_eq!(all, (1..=20u32).collect::<Vec<_>>());
        }
    }

    /// Pinning the same uid twice via `pin_top` is idempotent: it stays
    /// at `Top(0)` (the prior entry is removed and re-inserted at front).
    #[test]
    fn pin_top_is_idempotent_per_uid() {
        let mut p = PlayerCombatState::default();
        p.draw.extend([uid(1), uid(2), uid(3)]);
        pin_top(&mut p, uid(2));
        pin_top(&mut p, uid(3));
        pin_top(&mut p, uid(2)); // re-pin uid(2)
                                 // uid(2) should be Top(0) now, uid(3) demoted to Top(1).
        assert_eq!(p.pinned_top.as_slice(), &[uid(2), uid(3)]);
    }

    /// Bead `sts2-rs-jzjpd`: `unpin` removes a uid from both
    /// `pinned_top` and `pinned_bottom`. The function had 2
    /// production callers but zero direct tests, despite its
    /// siblings `pin_top` / `pin_bottom` being heavily covered.
    #[test]
    fn unpin_clears_top_pin() {
        let mut p = PlayerCombatState::default();
        p.draw.extend([uid(1), uid(2), uid(3)]);
        pin_top(&mut p, uid(2));
        assert_eq!(p.pinned_top.as_slice(), &[uid(2)]);
        unpin(&mut p, uid(2));
        assert!(p.pinned_top.is_empty());
    }

    /// `unpin` mirrors the top-pin clear on the bottom side, and is
    /// a no-op when the uid was never pinned (defensive: callers in
    /// the draw / move pipeline invoke unpin unconditionally).
    #[test]
    fn unpin_clears_bottom_pin_and_is_noop_on_missing() {
        let mut p = PlayerCombatState::default();
        p.draw.extend([uid(1), uid(2), uid(3)]);
        pin_bottom(&mut p, uid(2));
        assert_eq!(p.pinned_bottom.as_slice(), &[uid(2)]);
        unpin(&mut p, uid(2));
        assert!(p.pinned_bottom.is_empty());

        // No-op on never-pinned uid.
        unpin(&mut p, uid(99));
        assert!(p.pinned_top.is_empty());
        assert!(p.pinned_bottom.is_empty());
    }

    /// `pin_bottom` removes any existing top-pin for the uid, and vice
    /// versa — a single uid is never pinned to both ends simultaneously.
    #[test]
    fn pin_top_and_bottom_are_mutually_exclusive_per_uid() {
        let mut p = PlayerCombatState::default();
        p.draw.extend([uid(1), uid(2), uid(3)]);
        pin_top(&mut p, uid(2));
        assert_eq!(p.pinned_top.as_slice(), &[uid(2)]);
        pin_bottom(&mut p, uid(2));
        assert_eq!(p.pinned_top.as_slice(), &[] as &[CardUid]);
        assert_eq!(p.pinned_bottom.as_slice(), &[uid(2)]);
    }

    /// Drawing a card with a bottom-pin should also clear it (drawing
    /// any pinned card consumes its pin — the pin is no longer
    /// meaningful once the card has left the draw pile).
    #[test]
    fn drawing_pinned_bottom_card_clears_its_pin() {
        let mut p = PlayerCombatState::default();
        p.draw.extend([uid(1)]); // Single card; will draw it whether pinned bot or top.
        pin_bottom(&mut p, uid(1));
        let mut r = crate::dotnet_rng::Rng::new(7_i32);
        let moved = draw(&mut p, 1, &empty_store(), &mut r);
        assert_eq!(moved, 1);
        assert!(p.pinned_bottom.is_empty());
    }

    /// Bead `sts2-rs-6kpi8`: `draw_signaling` returns
    /// `(moved, shuffles)` — zero shuffles when the draw pile
    /// already has enough cards.
    #[test]
    fn draw_signaling_reports_zero_shuffles_when_draw_pile_has_cards() {
        let mut p = PlayerCombatState::default();
        p.draw.extend([uid(1), uid(2), uid(3)]);
        let mut rng = crate::dotnet_rng::Rng::new(1_i32);
        let (moved, shuffles) = draw_signaling(&mut p, 2, &empty_store(), &mut rng);
        assert_eq!(moved, 2);
        assert_eq!(shuffles, 0, "no auto-reshuffle needed");
        assert_eq!(p.hand.len(), 2);
        assert_eq!(p.draw.len(), 1);
    }

    /// `draw_signaling` increments the shuffle counter when the draw
    /// pile empties mid-draw and the discard pile gets folded back
    /// in via `discard_pile_into_draw_pile_signaling`.
    #[test]
    fn draw_signaling_increments_shuffle_counter_on_auto_reshuffle() {
        let mut p = PlayerCombatState::default();
        // Empty draw; one card in discard. Drawing 1 forces a
        // reshuffle, which moves discard→draw before the draw.
        p.discard.push(uid(7));
        let mut rng = crate::dotnet_rng::Rng::new(2_i32);
        let (moved, shuffles) = draw_signaling(&mut p, 1, &empty_store(), &mut rng);
        assert_eq!(moved, 1);
        assert_eq!(shuffles, 1, "auto-reshuffle must bump the counter");
        assert_eq!(p.hand.as_slice(), &[uid(7)]);
        assert!(p.discard.is_empty());
    }

    /// Bead `sts2-rs-xst9w`: seeded fuzz pass over `shuffle`.
    /// Asserts three invariants across 1000 iterations with random
    /// pile sizes (0..50) and random pin counts (0..=3 each end):
    ///   1. multiset preservation — the post-shuffle draw pile is a
    ///      permutation of the pre-shuffle draw pile (no card
    ///      loss / duplication)
    ///   2. pinned_top prefix — pinned_top uids appear at the start
    ///      of `draw` in the order recorded in `pinned_top`
    ///   3. pinned_bottom suffix — pinned_bottom uids appear at the
    ///      end of `draw` in the order recorded in `pinned_bottom`
    ///
    /// Driven by Xoshiro256PlusPlus seeded with the iteration
    /// counter so failures are reproducible.
    #[test]
    fn shuffle_fuzz_preserves_multiset_and_pin_ordering() {
        for seed in 0u64..1000 {
            let mut rng = crate::dotnet_rng::Rng::new((seed) as i32);
            // Random pile size 0..50.
            let n = (rng.next_int_exclusive(0, 50_i32) as u64) as u32;
            let mut p = PlayerCombatState::default();
            for i in 1..=n {
                p.draw.push(uid(i));
            }
            // Random pin counts: 0..=min(3, n) on each end, drawn from
            // disjoint subsets of the existing uids.
            let max_pin = n.min(3);
            let n_top = if max_pin == 0 {
                0
            } else {
                (rng.next_int_exclusive(0, (max_pin + 1) as i32) as u64) as u32
            };
            let remaining = max_pin.saturating_sub(n_top);
            let n_bot = if remaining == 0 {
                0
            } else {
                (rng.next_int_exclusive(0, (remaining + 1) as i32) as u64) as u32
            };
            // Pick disjoint top + bot uids from [1..=n] without replacement.
            let mut pool: Vec<u32> = (1..=n).collect();
            // Shuffle pool selector deterministically off the same rng.
            for i in (1..pool.len()).rev() {
                let j = rng.next_int_exclusive(0, (i + 1) as i32) as usize;
                pool.swap(i, j);
            }
            let top_uids: Vec<u32> = pool.iter().take(n_top as usize).copied().collect();
            let bot_uids: Vec<u32> = pool
                .iter()
                .skip(n_top as usize)
                .take(n_bot as usize)
                .copied()
                .collect();
            for &u in &top_uids {
                pin_top(&mut p, uid(u));
            }
            for &u in &bot_uids {
                pin_bottom(&mut p, uid(u));
            }
            // Capture pre-shuffle multiset (sorted UIDs).
            let mut pre: Vec<u32> = p.draw.iter().map(|c| c.get()).collect();
            pre.sort_unstable();

            shuffle(&mut p, &mut rng);

            let mut post: Vec<u32> = p.draw.iter().map(|c| c.get()).collect();
            post.sort_unstable();
            assert_eq!(
                pre, post,
                "seed {seed}: shuffle must preserve draw-pile multiset"
            );

            // Pinned_top prefix invariant. `pinned_top` records the
            // order in which pin_top was called (LIFO insertion);
            // reading from index 0 onward gives the expected prefix.
            let expected_top: Vec<CardUid> = p.pinned_top.iter().copied().collect();
            let actual_top_prefix: Vec<CardUid> =
                p.draw.iter().take(expected_top.len()).copied().collect();
            assert_eq!(
                actual_top_prefix, expected_top,
                "seed {seed}: pinned_top must be the post-shuffle prefix"
            );

            // Pinned_bottom suffix invariant.
            let expected_bot: Vec<CardUid> = p.pinned_bottom.iter().copied().collect();
            let suffix_start = p.draw.len().saturating_sub(expected_bot.len());
            let actual_bot_suffix: Vec<CardUid> =
                p.draw.iter().skip(suffix_start).copied().collect();
            assert_eq!(
                actual_bot_suffix, expected_bot,
                "seed {seed}: pinned_bottom must be the post-shuffle suffix"
            );
        }
    }

    // -----------------------------------------------------------------
    // Bead `sts2-rs-jg5wh`: invariant fuzz for `draw` — pile-sum
    // conservation + return-value-matches-moved + NoDraw gate.
    // -----------------------------------------------------------------

    /// `draw` must never lose or duplicate cards across a call:
    /// `|draw| + |discard| + |hand|` is conserved (exhaust + master_deck
    /// are not touched by this primitive). Fuzz with random pile sizes
    /// in `[0, 60]` and random draw counts in `[0, 20]` over 1000
    /// iterations seeded from `(0, 1)..` so failures reproduce.
    #[test]
    fn jg5wh_draw_conserves_pile_sum_and_return_value() {
        for seed in 0u64..1000 {
            let mut seed_rng = crate::dotnet_rng::Rng::new((seed) as i32);
            let draw_count = (seed_rng.next_int_exclusive(0, 60_i32) as u32) as usize;
            let discard_count = (seed_rng.next_int_exclusive(0, 60_i32) as u32) as usize;
            let hand_count = (seed_rng.next_int_exclusive(0, 11_i32) as u32) as usize; // can already be at HAND_LIMIT
            let request = (seed_rng.next_int_exclusive(0, 20_i32) as u32) as i32 - 5; // include n <= 0

            let mut p = PlayerCombatState::default();
            let mut next_uid: u32 = 1;
            for _ in 0..draw_count {
                p.draw.push(uid(next_uid));
                next_uid += 1;
            }
            for _ in 0..discard_count {
                p.discard.push(uid(next_uid));
                next_uid += 1;
            }
            for _ in 0..hand_count {
                p.hand.push(uid(next_uid));
                next_uid += 1;
            }
            let total_before = p.draw.len() + p.discard.len() + p.hand.len();
            let hand_before = p.hand.len();

            let mut draw_rng = crate::dotnet_rng::Rng::new((seed.wrapping_mul(31)) as i32);
            let moved = draw(&mut p, request, &empty_store(), &mut draw_rng);

            let total_after = p.draw.len() + p.discard.len() + p.hand.len();
            assert_eq!(
                total_after, total_before,
                "seed {seed}: pile-sum invariant violated (before={total_before} after={total_after})",
            );
            let hand_growth = p.hand.len() - hand_before;
            assert_eq!(
                moved, hand_growth,
                "seed {seed}: return value must equal hand growth",
            );
            // Negative or zero request always returns 0.
            if request <= 0 {
                assert_eq!(moved, 0, "seed {seed}: n <= 0 must return 0");
            }
            // Hand never exceeds HAND_LIMIT after a draw.
            assert!(
                p.hand.len() <= HAND_LIMIT,
                "seed {seed}: hand overflowed HAND_LIMIT (got {})",
                p.hand.len(),
            );
        }
    }

    /// `draw_via_state` returns 0 when the player has any active
    /// `NoDraw` power, regardless of pile contents. Counterpart: a
    /// fresh state with no NoDraw stack draws normally.
    #[test]
    fn jg5wh_draw_via_state_respects_no_draw_gate() {
        use crate::{CombatState, Power, PowerKind, PowerUid};
        // Sanity: no NoDraw stack -> draws normally.
        let mut state = CombatState::default();
        // A live player: a dead one makes the combat ending, so draws move no card.
        state.player.current_hp = 80;
        for n in 1u32..=5 {
            state.player.draw.push(uid(n));
        }
        let moved = draw_via_state(&mut state, 3);
        assert_eq!(moved, 3, "no NoDraw stack -> draws full request");

        // Reset + attach a NoDraw power.
        let mut state = CombatState::default();
        for n in 1u32..=5 {
            state.player.draw.push(uid(n));
        }
        let pid = std::num::NonZeroU32::new(1234).expect("non-zero");
        state.powers.push(Power::new(pid, PowerKind::NoDraw, 1));
        state.player.powers.push(PowerUid(pid));

        let moved_under_no_draw = draw_via_state(&mut state, 3);
        assert_eq!(
            moved_under_no_draw, 0,
            "NoDraw stack > 0 -> draw_via_state must return 0",
        );
        // Pile unchanged.
        assert_eq!(state.player.draw.len(), 5);
        assert_eq!(state.player.hand.len(), 0);
    }

    /// Bead `sts2-rs-q6bix` (PILE_COUNT, BATTLE_TRANCE): NoDraw applied via
    /// the d03 player-creature MIRROR (the real card path —
    /// `apply_power_to_player` → `apply_power_to_creature`) must also gate
    /// `draw_via_state`. The legacy-only scan in the prior implementation
    /// silently missed mirror-applied NoDraw, so a Slimed card played the
    /// same turn as BattleTrance still drew. Counterpart to
    /// `jg5wh_draw_via_state_respects_no_draw_gate` (legacy surface).
    #[test]
    fn q6bix_draw_via_state_respects_mirror_no_draw_gate() {
        use crate::{CombatState, Power, PowerKind, PowerUid};
        let mut state = CombatState::default();
        for n in 1u32..=5 {
            state.player.draw.push(uid(n));
        }
        // Stand up the d03 player-creature mirror, then route NoDraw through
        // it ONLY (not state.player.powers) — exactly as the card path does
        // (`apply_power_to_player` → `apply_power_to_creature`).
        let cuid = state.init_player_creature();
        let pid = std::num::NonZeroU32::new(1234).expect("non-zero");
        state.powers.push(Power::new(pid, PowerKind::NoDraw, 1));
        let creature = state
            .creatures
            .iter_mut()
            .find(|c| c.id == cuid.0)
            .expect("player creature mirror exists");
        creature.powers.push(PowerUid(pid));

        let moved = draw_via_state(&mut state, 3);
        assert_eq!(
            moved, 0,
            "mirror-applied NoDraw must gate draw_via_state (BATTLE_TRANCE path)",
        );
        assert_eq!(state.player.draw.len(), 5);
        assert_eq!(state.player.hand.len(), 0);
    }

    /// C# `Slither.AfterCardDrawn` rerolls the card's cost off
    /// `CombatEnergyCosts.NextInt(4)` on EVERY draw-pile draw — including
    /// card-effect draws (Pommel Strike, Drum of Battle, Pillage).
    /// `draw_via_state`'s batch branch previously skipped the enchantment
    /// bus entirely, so the cursor fell one read behind the DLL at the
    /// first effect-draw of a Slither card and every later Slither cost
    /// diverged (shadow census v8 seeds 1003/1006/1042/1049). Exactly one
    /// read per enchanted drawn card; un-enchanted cards consume nothing.
    #[test]
    fn draw_via_state_fires_slither_reroll_on_effect_draw() {
        use crate::CombatState;
        let mut state = CombatState::default();
        // A live player: a dead one makes the combat ending, so draws move no card.
        state.player.current_hp = 80;
        let mut enchanted = Card {
            uid: uid(1),
            card_id: CardId::ShrugItOff,
            cost: 1,
            card_type: CardType::Skill,
            target_type: TargetType::Self_,
            base_damage: 0,
            base_block: 8,
            ..Card::pod_defaults()
        };
        enchanted.set_enchantment(EnchantmentId::Slither, 1);
        state.cards.push(enchanted);
        state.cards.push(Card {
            uid: uid(2),
            card_id: CardId::StrikeIronclad,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            base_damage: 6,
            base_block: 0,
            ..Card::pod_defaults()
        });
        state.player.draw.push(uid(1));
        state.player.draw.push(uid(2));

        let cursor_before = state.run_rng.combat_energy_costs.counter();
        let moved = draw_via_state(&mut state, 2);
        assert_eq!(moved, 2, "both cards drawn");
        assert_eq!(
            state.run_rng.combat_energy_costs.counter() - cursor_before,
            1,
            "exactly one combat_energy_costs read: the Slither card rerolls, the plain card does not",
        );
        assert!(
            (0..=3).contains(&state.cards[0].cost),
            "Slither card cost rerolled into [0, 3], got {}",
            state.cards[0].cost,
        );
        assert_eq!(state.cards[1].cost, 1, "un-enchanted card cost untouched");
    }

    /// Defect `IterationPower.AfterCardDrawn` (C# `IterationPower.cs`): the
    /// FIRST `CardType::Status` card the owner draws each turn pulls `Amount`
    /// extra cards; a SECOND status card drawn the same turn does NOT re-fire
    /// (C#'s `num <= 1` per-turn history gate). Drives the on-draw rider in
    /// [`crate::CombatState::invoke_card_drawn_for_newly_drawn`].
    #[test]
    fn iteration_first_status_draw_pulls_amount_extra() {
        use crate::{CombatState, Power, PowerKind, PowerUid};
        let mut state = CombatState::default();
        // A live player: a dead one makes the combat ending, so draws move no card.
        state.player.current_hp = 80;
        // 8 cards: uid 1 and uid 5 are Status; the rest Attacks. The draw
        // pile is ordered so uid 1 (Status) is on top, then 4 attacks, then
        // uid 5 (the second Status), then more attacks.
        for n in 1u32..=8 {
            state.cards.push(Card {
                uid: uid(n),
                card_id: CardId::Dazed,
                cost: 0,
                card_type: if n == 1 || n == 5 {
                    CardType::Status
                } else {
                    CardType::Attack
                },
                target_type: TargetType::Self_,
                base_damage: 0,
                base_block: 0,
                ..Card::pod_defaults()
            });
        }
        for n in [1u32, 2, 3, 4, 5, 6, 7, 8] {
            state.player.draw.push(uid(n));
        }
        let pid = std::num::NonZeroU32::new(99).expect("non-zero");
        state.powers.push(Power::new(pid, PowerKind::Iteration, 2));
        state.player.powers.push(PowerUid(pid));

        // Draw 1 → pulls the top Status card → Iteration fires once → +2.
        draw_via_state(&mut state, 1);
        assert_eq!(
            state.player.hand.len(),
            3,
            "first Status draw triggers Iteration(2): 1 requested + 2 extra",
        );
        assert_eq!(
            state.combat_log.status_cards_drawn_this_turn, 1,
            "exactly one status card counted so far",
        );

        // Draw 2 more → pulls uid 5 (the second Status) among them; the gate
        // is already past 1, so Iteration must NOT fire again.
        let hand_before = state.player.hand.len();
        draw_via_state(&mut state, 2);
        assert_eq!(
            state.player.hand.len(),
            hand_before + 2,
            "second Status card draws no extra (Iteration already fired this turn)",
        );
        assert!(
            state.combat_log.status_cards_drawn_this_turn >= 2,
            "second status card was counted",
        );
    }

    // -----------------------------------------------------------------
    // Bead `sts2-rs-78atw`: invariant fuzz for
    // `discard_pile_into_draw_pile_signaling` — pile-sum conservation,
    // signal correctness, idempotent on empty.
    // -----------------------------------------------------------------

    /// 500-iteration fuzz: for every (|draw|, |discard|) combo in
    /// `[0, 30] × [0, 30]` (sampled randomly per seed), assert:
    /// - The reshuffle preserves `|draw| + |discard|`.
    /// - The signal is `true` iff `draw_before.is_empty() &&
    ///   !discard_before.is_empty()` (the precondition path).
    /// - When the signal is `true`, the post-state has
    ///   `|draw| == draw_before + discard_before` and
    ///   `|discard| == 0`.
    /// - When the signal is `false`, both piles are byte-identical
    ///   to their pre-state.
    #[test]
    fn jzz78atw_reshuffle_conserves_pile_sum_and_signals_correctly() {
        for seed in 0u64..500 {
            let mut seed_rng = crate::dotnet_rng::Rng::new((seed) as i32);
            let draw_n = (seed_rng.next_int_exclusive(0, 31_i32) as u32) as usize;
            let discard_n = (seed_rng.next_int_exclusive(0, 31_i32) as u32) as usize;

            let mut p = PlayerCombatState::default();
            let mut next: u32 = 1;
            for _ in 0..draw_n {
                p.draw.push(uid(next));
                next += 1;
            }
            for _ in 0..discard_n {
                p.discard.push(uid(next));
                next += 1;
            }
            let draw_before: Vec<CardUid> = p.draw.iter().copied().collect();
            let discard_before: Vec<CardUid> = p.discard.iter().copied().collect();
            let total_before = draw_before.len() + discard_before.len();
            let expect_signal = draw_before.is_empty() && !discard_before.is_empty();

            let mut rng = crate::dotnet_rng::Rng::new((seed.wrapping_mul(127)) as i32);
            let signal = discard_pile_into_draw_pile_signaling(&mut p, &empty_store(), &mut rng);
            assert_eq!(
                signal, expect_signal,
                "seed {seed}: signal mismatch (draw={draw_n} discard={discard_n})",
            );
            let total_after = p.draw.len() + p.discard.len();
            assert_eq!(
                total_after, total_before,
                "seed {seed}: pile-sum invariant violated (before={total_before} after={total_after})",
            );
            if signal {
                assert_eq!(
                    p.discard.len(),
                    0,
                    "seed {seed}: discard must be empty after reshuffle"
                );
                assert_eq!(
                    p.draw.len(),
                    draw_before.len() + discard_before.len(),
                    "seed {seed}: draw must grow by the prior discard size",
                );
            } else {
                // No-op path: piles byte-identical.
                assert_eq!(
                    p.draw.iter().copied().collect::<Vec<_>>(),
                    draw_before,
                    "seed {seed}: no-op signal must leave draw byte-identical",
                );
                assert_eq!(
                    p.discard.iter().copied().collect::<Vec<_>>(),
                    discard_before,
                    "seed {seed}: no-op signal must leave discard byte-identical",
                );
            }
        }
    }

    /// `discard_pile_into_draw_pile` (the non-signaling variant) is
    /// a `let _ =` wrapper. Verify it's behaviorally equivalent to
    /// the signaling form on the canonical empty-draw + non-empty-
    /// discard auto-reshuffle path.
    #[test]
    fn jzz78atw_basic_variant_matches_signaling_on_reshuffle() {
        let mut p = PlayerCombatState::default();
        for n in 1u32..=4 {
            p.discard.push(uid(n));
        }
        let mut rng = crate::dotnet_rng::Rng::new(7_i32);
        discard_pile_into_draw_pile(&mut p, &empty_store(), &mut rng);
        assert_eq!(p.discard.len(), 0);
        assert_eq!(p.draw.len(), 4);
    }

    // -----------------------------------------------------------------
    // Bead `sts2-rs-n0s2y`: `try_add_to_hand` MAX_HAND_SIZE redirect.
    // -----------------------------------------------------------------

    /// `try_add_to_hand` with hand size `< HAND_LIMIT`: card lands
    /// in hand, returns `true`. Discard stays empty.
    #[test]
    fn n0s2y_try_add_to_hand_inserts_when_under_limit() {
        let mut p = PlayerCombatState::default();
        for n in 1u32..=5 {
            p.hand.push(uid(n));
        }
        let new_uid = uid(99);
        let ok = try_add_to_hand(&mut p, new_uid);
        assert!(ok, "must return true when hand is under HAND_LIMIT");
        assert_eq!(p.hand.len(), 6, "hand grew by 1");
        assert!(p.hand.contains(&new_uid));
        assert!(p.discard.is_empty(), "discard untouched");
    }

    /// `try_add_to_hand` with hand at `HAND_LIMIT`: card redirects
    /// to discard, returns `false`. Hand size unchanged. Mirrors
    /// Python `combat.py:1682-1691` redirect path.
    #[test]
    fn n0s2y_try_add_to_hand_redirects_when_full() {
        let mut p = PlayerCombatState::default();
        for n in 1u32..=(HAND_LIMIT as u32) {
            p.hand.push(uid(n));
        }
        assert_eq!(p.hand.len(), HAND_LIMIT);
        let new_uid = uid(99);
        let ok = try_add_to_hand(&mut p, new_uid);
        assert!(!ok, "must return false when hand is at HAND_LIMIT");
        assert_eq!(p.hand.len(), HAND_LIMIT, "hand unchanged");
        assert!(!p.hand.contains(&new_uid), "new uid did not land in hand");
        assert_eq!(p.discard.len(), 1, "card redirected to discard");
        assert!(p.discard.contains(&new_uid));
    }

    // -----------------------------------------------------------------
    // Bead `sts2-rs-fkru3`: pile_iter / pile_len cover all 5 PileKind
    // variants (Hand / Draw / Discard / Exhaust / Play).
    // -----------------------------------------------------------------

    /// Per-variant smoke for `pile_len` + `pile_iter`. Builds a
    /// PlayerCombatState with distinct uid sequences per pile and
    /// asserts pile_len matches the populated count + pile_iter
    /// yields the same uids in insertion order.
    #[test]
    fn fkru3_pile_len_and_pile_iter_match_for_every_pilekind() {
        let mut p = PlayerCombatState::default();
        // Each pile gets a distinct uid sequence so a swapped
        // match arm would mismatch the assertion.
        for n in 1u32..=2 {
            p.hand.push(uid(n));
        }
        for n in 10u32..=12 {
            p.draw.push(uid(n));
        }
        for n in 20u32..=23 {
            p.discard.push(uid(n));
        }
        for n in 30u32..=34 {
            p.exhaust.push(uid(n));
        }
        for n in 40u32..=46 {
            p.play.push(uid(n));
        }

        let cases: &[(PileKind, usize, std::ops::RangeInclusive<u32>)] = &[
            (PileKind::Hand, 2, 1..=2),
            (PileKind::Draw, 3, 10..=12),
            (PileKind::Discard, 4, 20..=23),
            (PileKind::Exhaust, 5, 30..=34),
            (PileKind::Play, 7, 40..=46),
        ];
        for (pile, expected_len, expected_range) in cases {
            assert_eq!(
                pile_len(&p, *pile),
                *expected_len,
                "pile_len mismatch for {pile:?}",
            );
            let actual: Vec<CardUid> = pile_iter(&p, *pile).collect();
            let expected: Vec<CardUid> = expected_range.clone().map(uid).collect();
            assert_eq!(actual, expected, "pile_iter mismatch for {pile:?}");
        }
    }

    // -----------------------------------------------------------------
    // Bead `sts2-rs-kq1d7`: draw_signaling shuffle-count under
    // auto-reshuffle loop.
    // -----------------------------------------------------------------

    /// 5-card discard + empty draw + empty hand, request draw(10):
    /// expect moved=5, shuffles=1. The auto-reshuffle fires once
    /// when draw empties (one card per iteration after the move),
    /// then the loop drains the refilled draw pile until both
    /// piles are exhausted.
    #[test]
    fn kq1d7_draw_signaling_fires_exactly_one_shuffle_on_discard_only_state() {
        let mut p = PlayerCombatState::default();
        for n in 1u32..=5 {
            p.discard.push(uid(n));
        }
        let mut rng = crate::dotnet_rng::Rng::new(11_i32);
        let (moved, shuffles) = draw_signaling(&mut p, 10, &empty_store(), &mut rng);
        assert_eq!(moved, 5, "moved == |discard| when request exceeds total");
        assert_eq!(
            shuffles, 1,
            "exactly one reshuffle on the first empty-draw iteration; \
             further iterations see an empty discard and bail",
        );
        assert_eq!(p.hand.len(), 5);
        assert_eq!(p.draw.len(), 0);
        assert_eq!(p.discard.len(), 0);
    }

    /// Mixed draw + discard: 3-card draw + 4-card discard + empty
    /// hand, request draw(10): expect moved=7, shuffles=1. The draw
    /// pile drains first (3 iterations, no shuffle), then iteration
    /// 4 sees empty draw + non-empty discard and reshuffles.
    #[test]
    fn kq1d7_draw_signaling_fires_one_shuffle_only_after_draw_drains() {
        let mut p = PlayerCombatState::default();
        for n in 1u32..=3 {
            p.draw.push(uid(n));
        }
        for n in 10u32..=13 {
            p.discard.push(uid(n));
        }
        let mut rng = crate::dotnet_rng::Rng::new(13_i32);
        let (moved, shuffles) = draw_signaling(&mut p, 10, &empty_store(), &mut rng);
        assert_eq!(moved, 7);
        assert_eq!(shuffles, 1, "one reshuffle when draw drains mid-loop");
        assert_eq!(p.hand.len(), 7);
        assert_eq!(p.draw.len(), 0);
        assert_eq!(p.discard.len(), 0);
    }

    /// Both piles empty: request draw(5) returns (0, 0) — no
    /// shuffle attempted, no panic, no card produced.
    #[test]
    fn kq1d7_draw_signaling_returns_zero_zero_on_empty_state() {
        let mut p = PlayerCombatState::default();
        let mut rng = crate::dotnet_rng::Rng::new(17_i32);
        let (moved, shuffles) = draw_signaling(&mut p, 5, &empty_store(), &mut rng);
        assert_eq!(moved, 0);
        assert_eq!(shuffles, 0);
        assert!(p.hand.is_empty());
        assert!(p.draw.is_empty());
        assert!(p.discard.is_empty());
    }

    // -----------------------------------------------------------------
    // Bead `sts2-rs-ii7h9`: pin_top/pin_bottom/unpin idempotent
    // migration between pinned_top + pinned_bottom lists.
    // -----------------------------------------------------------------

    /// Each pin helper retains-out the uid from BOTH lists before
    /// inserting into the target. A regression that dropped one of
    /// the retains would let the uid duplicate across both lists.
    /// Walk pin_top -> pin_bottom -> unpin and assert state at each
    /// step (no duplication; migration is exclusive).
    #[test]
    fn ii7h9_pin_helpers_keep_uid_in_at_most_one_list() {
        let mut p = PlayerCombatState::default();
        let target = uid(42);

        // pin_top.
        pin_top(&mut p, target);
        assert_eq!(p.pinned_top.iter().filter(|u| **u == target).count(), 1);
        assert_eq!(p.pinned_bottom.iter().filter(|u| **u == target).count(), 0);

        // pin_bottom should migrate, not duplicate.
        pin_bottom(&mut p, target);
        assert_eq!(
            p.pinned_top.iter().filter(|u| **u == target).count(),
            0,
            "pin_bottom must clear the prior top entry",
        );
        assert_eq!(p.pinned_bottom.iter().filter(|u| **u == target).count(), 1);

        // re-pin_top: migrate back.
        pin_top(&mut p, target);
        assert_eq!(p.pinned_top.iter().filter(|u| **u == target).count(), 1);
        assert_eq!(p.pinned_bottom.iter().filter(|u| **u == target).count(), 0);

        // unpin: remove from both.
        unpin(&mut p, target);
        assert_eq!(p.pinned_top.iter().filter(|u| **u == target).count(), 0);
        assert_eq!(p.pinned_bottom.iter().filter(|u| **u == target).count(), 0);
    }

    /// Repeated pin_top calls are idempotent at the size level: the
    /// uid sits at the front position and never appears more than
    /// once.
    #[test]
    fn ii7h9_pin_top_is_idempotent() {
        let mut p = PlayerCombatState::default();
        let target = uid(99);
        for _ in 0..5 {
            pin_top(&mut p, target);
        }
        assert_eq!(p.pinned_top.iter().filter(|u| **u == target).count(), 1);
        assert_eq!(p.pinned_top[0], target, "uid sits at the front");
    }

    /// Bead `sts2-rs-cd1zg` (7n7tb sub-2): `Card::set_affliction`
    /// honors C# `AfflictionModel.CanAfflictCardType` — Devoured
    /// only sticks on Attack/Skill cards (`Devoured.cs:26-33`).
    #[test]
    fn set_affliction_devoured_only_accepts_attack_or_skill() {
        let mut attack = sample_card(1);
        attack.card_type = CardType::Attack;
        let devoured = crate::card_afflictions::CardAffliction::devoured_with_exhaust(3, true);
        assert!(attack.set_affliction(devoured));
        assert_eq!(attack.affliction, Some(devoured));

        let mut skill = sample_card(2);
        skill.card_type = CardType::Skill;
        assert!(skill.set_affliction(devoured));

        let mut power = sample_card(3);
        power.card_type = CardType::Power;
        assert!(!power.set_affliction(devoured), "Power rejects Devoured");
        assert!(
            power.affliction.is_none(),
            "rejected set must not mutate the card"
        );
    }

    /// `Card::clear_affliction` returns the prior value and leaves
    /// the field None — the round-trip of `HungerPower.AfterApplied
    /// → AfterRemoved` (`HungerPower.cs:23-76`) relies on this.
    #[test]
    fn clear_affliction_returns_prior_and_unsets() {
        let mut c = sample_card(1);
        c.card_type = CardType::Attack;
        let devoured = crate::card_afflictions::CardAffliction::devoured_with_exhaust(2, true);
        assert!(c.set_affliction(devoured));
        let cleared = c.clear_affliction();
        assert_eq!(cleared, Some(devoured));
        assert!(c.affliction.is_none());
        // Idempotent: clearing again returns None.
        assert!(c.clear_affliction().is_none());
    }

    /// `Card::devoured_added_exhaust` is true iff a Devoured
    /// affliction with `applied_exhaust=true` is currently set. The
    /// HungerPower revert path (bead `sts2-rs-9l5c2`) reads this to
    /// decide whether to strip the Exhaust keyword.
    #[test]
    fn devoured_added_exhaust_reflects_flag_and_kind() {
        let mut c = sample_card(1);
        c.card_type = CardType::Attack;
        assert!(!c.devoured_added_exhaust(), "no affliction → false");

        assert!(c.set_affliction(
            crate::card_afflictions::CardAffliction::devoured_with_exhaust(1, true)
        ));
        assert!(c.devoured_added_exhaust(), "Devoured + flag → true");

        assert!(c.set_affliction(
            crate::card_afflictions::CardAffliction::devoured_with_exhaust(1, false)
        ));
        assert!(
            !c.devoured_added_exhaust(),
            "Devoured + !flag → false (card already had Exhaust pre-affliction)"
        );

        // Non-Devoured afflictions never report devoured_added_exhaust.
        assert!(
            c.set_affliction(crate::card_afflictions::CardAffliction::new(
                crate::card_afflictions::CardAfflictionKind::Bound,
                2,
            ))
        );
        assert!(!c.devoured_added_exhaust(), "non-Devoured → false");
    }

    // ── DrawChance helpers (bead `sts2-rs-i8bgu`, F1 plan §3.2 step 1) ──

    #[test]
    fn unknown_middle_uids_is_whole_pile_when_unpinned() {
        let p = player_with_draw(&[3, 1, 4, 1, 5]);
        assert_eq!(unknown_middle_uids(&p).as_slice(), p.draw.as_slice());
    }

    fn player_with_draw(order: &[u32]) -> PlayerCombatState {
        PlayerCombatState {
            draw: order.iter().copied().map(uid).collect::<SmallVec<_>>(),
            ..PlayerCombatState::default()
        }
    }

    #[test]
    fn unknown_middle_uids_excludes_pins() {
        let mut p = player_with_draw(&[5, 3, 1, 4, 2]);
        pin_top(&mut p, uid(5));
        pin_bottom(&mut p, uid(2));
        let middle = unknown_middle_uids(&p);
        assert_eq!(middle.len(), 3);
        assert!(!middle.contains(&uid(5)));
        assert!(!middle.contains(&uid(2)));
    }

    #[test]
    fn unknown_middle_uids_ignores_stale_pins() {
        // A pin naming a uid no longer in `draw` must not blow up and
        // must not remove anything from the returned middle (it can
        // never match a `draw` entry).
        let mut p = player_with_draw(&[1, 2, 3]);
        p.pinned_top.push(uid(999));
        assert_eq!(unknown_middle_uids(&p).len(), 3);
    }

    #[test]
    fn cards_observationally_equal_ignores_uid_only() {
        let a = sample_card(1);
        let mut b = sample_card(2);
        assert!(
            cards_observationally_equal(&a, &b),
            "identical content, different uid, must compare equal"
        );
        b.upgraded = true;
        assert!(
            !cards_observationally_equal(&a, &b),
            "a real content difference must compare unequal"
        );
    }

    /// GH #741: a non-X card's stamped `energy_spent` is a per-play transient,
    /// so it does not split observational identity (the MCTS draw-chance and
    /// pile hashes); an X-cost card's value still does, as before #741.
    #[test]
    fn cards_observationally_equal_ignores_non_x_energy_spent() {
        let a = sample_card(1);
        let mut b = sample_card(2);
        b.energy_spent = 2;
        assert!(!a.is_x_cost());
        assert!(cards_observationally_equal(&a, &b));

        let mut x1 = sample_card(3);
        x1.cost = -1;
        let mut x2 = x1;
        x2.uid = uid(4);
        x2.energy_spent = 3;
        assert!(x1.is_x_cost());
        assert!(!cards_observationally_equal(&x1, &x2));
    }

    #[test]
    fn cards_observationally_equal_catches_combat_vars_and_enchantments() {
        let a = sample_card(1);
        let mut b = sample_card(2);
        b.combat_vars.push((VarKey::RampageDamage, 3));
        assert!(!cards_observationally_equal(&a, &b));

        let mut c = sample_card(3);
        c.enchantments.push((EnchantmentId::Steady, 1));
        assert!(!cards_observationally_equal(&a, &c));
    }

    #[test]
    fn segment_homogeneous_when_all_cards_equal() {
        let cards: CardStore = vec![sample_card(1), sample_card(2), sample_card(3)].into();
        let segment = [uid(1), uid(2), uid(3)];
        assert!(segment_is_observationally_homogeneous(&segment, &cards));
    }

    #[test]
    fn segment_heterogeneous_when_one_card_differs() {
        let mut cards: CardStore = vec![sample_card(1), sample_card(2), sample_card(3)].into();
        cards[2].card_id = CardId::Bash;
        let segment = [uid(1), uid(2), uid(3)];
        assert!(!segment_is_observationally_homogeneous(&segment, &cards));
    }

    #[test]
    fn segment_homogeneous_conservative_on_missing_card() {
        // A uid with no matching arena entry must never be treated as
        // "equal to everything" — that would silently widen the
        // homogeneous case to cover a lookup bug. It should read as
        // heterogeneous (the safe, tree-widening direction).
        let cards: CardStore = vec![sample_card(1)].into();
        let segment = [uid(1), uid(404)];
        assert!(!segment_is_observationally_homogeneous(&segment, &cards));
    }

    #[test]
    fn segment_homogeneous_single_card_trivially_true() {
        let cards: CardStore = vec![sample_card(1)].into();
        let segment = [uid(1)];
        assert!(segment_is_observationally_homogeneous(&segment, &cards));
    }

    // ── BeliefDraw deferred draw (bead `sts2-rs-09x5n`, F2 lightspeed port) ──

    fn deferred_player_with_draw(order: &[u32]) -> PlayerCombatState {
        PlayerCombatState {
            deferred_draw_order: true,
            ..player_with_draw(order)
        }
    }

    #[test]
    fn pop_next_card_singleton_segment_consumes_no_rng() {
        let mut p = deferred_player_with_draw(&[42]);
        let mut rng = crate::dotnet_rng::Rng::new(123);
        let before = rng.counter();
        let drawn = pop_next_card(&mut p, &mut rng);
        assert_eq!(drawn, uid(42));
        assert!(p.draw.is_empty());
        assert_eq!(
            rng.counter(),
            before,
            "a singleton unknown segment must draw deterministically with no RNG read"
        );
    }

    #[test]
    fn pop_next_card_multi_card_segment_consumes_rng() {
        let mut p = deferred_player_with_draw(&[1, 2, 3, 4, 5]);
        let mut rng = crate::dotnet_rng::Rng::new(123);
        let before = rng.counter();
        let _ = pop_next_card(&mut p, &mut rng);
        assert_eq!(
            rng.counter(),
            before + 1,
            "a >=2-card unknown segment must consume exactly one RNG read per draw"
        );
    }

    #[test]
    fn pop_next_card_pinned_top_drawn_first_no_rng() {
        let mut p = deferred_player_with_draw(&[1, 2, 3, 4, 5]);
        pin_top(&mut p, uid(1));
        pin_top(&mut p, uid(2));
        // `pin_top` only records the pin; real callers (Headbutt-style
        // resolvers) always physically `draw.insert(0, uid)` in the SAME
        // step. Reconcile the physical layout with the pin list the way
        // `shuffle`'s canonicalize-under-`deferred_draw_order` branch does,
        // so the physical front matches `pinned_top` before measuring.
        let mut setup_rng = crate::dotnet_rng::Rng::new(1);
        shuffle(&mut p, &mut setup_rng);

        let mut rng = crate::dotnet_rng::Rng::new(7);
        let before = rng.counter();
        // pinned_top is LIFO: uid(2) is the most recent pin -> drawn first.
        assert_eq!(pop_next_card(&mut p, &mut rng), uid(2));
        assert_eq!(pop_next_card(&mut p, &mut rng), uid(1));
        assert_eq!(
            rng.counter(),
            before,
            "pinned_top draws are player-KNOWN information and must never touch RNG"
        );
    }

    #[test]
    fn pop_next_card_pinned_bottom_drawn_last_in_order() {
        let mut p = deferred_player_with_draw(&[1, 2, 3]);
        pin_bottom(&mut p, uid(3));
        let mut rng = crate::dotnet_rng::Rng::new(7);
        // Middle {1,2}: one deferred (RNG) draw each; then pinned_bottom.
        let mut first_two = [
            pop_next_card(&mut p, &mut rng).get(),
            pop_next_card(&mut p, &mut rng).get(),
        ];
        first_two.sort_unstable();
        assert_eq!(first_two, [1, 2]);
        assert_eq!(pop_next_card(&mut p, &mut rng), uid(3));
        assert!(p.draw.is_empty());
    }

    #[test]
    fn pop_next_card_uniform_over_multi_card_segment() {
        // Not a proof of uniformity, but a basic sanity check that both
        // members of a 2-card segment are reachable across many seeds —
        // catches an off-by-one / always-index-0 regression cheaply.
        let mut seen = std::collections::BTreeSet::new();
        for seed in 0..64i32 {
            let mut p = deferred_player_with_draw(&[10, 20]);
            let mut rng = crate::dotnet_rng::Rng::new(seed);
            seen.insert(pop_next_card(&mut p, &mut rng).get());
        }
        assert_eq!(
            seen,
            std::collections::BTreeSet::from([10, 20]),
            "both cards in a 2-card unknown segment must be reachable"
        );
    }

    /// Final-branch-review finding (bead `sts2-rs-ztl78`): a stale
    /// `pinned_top`/`pinned_bottom` entry (a raw `draw.remove(pos)` at some
    /// content call site that bypassed `pop_next_card` and forgot to
    /// `unpin`) must not survive to make `pop_next_card` trust it. Simulate
    /// the bypass directly: stamp `pinned_top` with a uid that is NOT
    /// physically present in `draw` (as if the card already left via a raw
    /// removal elsewhere), and assert the staleness sweep drops it, falling
    /// through to the normal middle-segment logic — a >=2-card unknown
    /// segment must still consume RNG, not short-circuit to a
    /// zero-RNG deterministic pop.
    #[test]
    fn pop_next_card_sweeps_stale_pinned_top_and_keeps_chance_node() {
        let mut p = deferred_player_with_draw(&[1, 2, 3]);
        // uid(99) is NOT in `p.draw` — simulates a stale pin left behind by
        // a raw removal that bypassed `pop_next_card`/`unpin`.
        p.pinned_top.push(uid(99));
        assert!(!p.pinned_top.is_empty(), "stale pin set up");

        let mut rng = crate::dotnet_rng::Rng::new(11);
        let before = rng.counter();
        let drawn = pop_next_card(&mut p, &mut rng);

        assert!(
            p.pinned_top.is_empty(),
            "the staleness sweep must drop the pin whose uid is not in draw"
        );
        assert!(
            [uid(1), uid(2), uid(3)].contains(&drawn),
            "must fall through to the normal 3-card unknown middle, not the stale pin"
        );
        assert_eq!(
            rng.counter(),
            before + 1,
            "a >=2-card unknown middle must still consume RNG once the stale pin is swept"
        );
    }

    /// A VALID pin (uid physically present in `draw`) must still pop
    /// deterministically with ZERO RNG after the staleness-sweep guard is
    /// added — the sweep must not disturb the byte-identical happy path
    /// (final-branch-review finding, bead `sts2-rs-ztl78`).
    #[test]
    fn pop_next_card_valid_pinned_top_still_zero_rng_after_sweep_guard() {
        let mut p = deferred_player_with_draw(&[1, 2, 3, 4, 5]);
        pin_top(&mut p, uid(1));
        let mut setup_rng = crate::dotnet_rng::Rng::new(1);
        shuffle(&mut p, &mut setup_rng);

        let mut rng = crate::dotnet_rng::Rng::new(7);
        let before = rng.counter();
        assert_eq!(pop_next_card(&mut p, &mut rng), uid(1));
        assert_eq!(
            rng.counter(),
            before,
            "a still-valid pin must keep popping deterministically with no RNG read"
        );
    }

    #[test]
    fn pop_next_card_false_flag_is_byte_identical_to_legacy_pop_front() {
        let mut p = player_with_draw(&[5, 4, 3, 2, 1]);
        assert!(!p.deferred_draw_order, "default flag must be false");
        let mut rng = crate::dotnet_rng::Rng::new(999);
        let before = rng.counter();
        let drawn = pop_next_card(&mut p, &mut rng);
        assert_eq!(
            drawn,
            uid(5),
            "false flag must pop the front, like draw.remove(0)"
        );
        assert_eq!(rng.counter(), before, "false flag must never touch RNG");
    }

    // ── Top-of-draw helpers (GH #785) ──────────────────────────────────
    //
    // Havoc / Cascade / Distilled Chaos / Mayhem / I Am Invincible /
    // ToastyMittens act on the PHYSICAL top of the draw pile. Under a
    // deferred-order pile the unknown middle is kept uid-sorted, so its
    // `draw[0]` is a fixed stand-in (the lowest uid), not the top.

    #[test]
    fn pop_top_card_multi_card_segment_consumes_rng() {
        let mut p = deferred_player_with_draw(&[1, 2, 3, 4, 5]);
        let mut rng = crate::dotnet_rng::Rng::new(123);
        let before = rng.counter();
        let popped = pop_top_card(&mut p, &mut rng);
        assert!((1..=5).map(uid).any(|u| u == popped));
        assert_eq!(
            rng.counter(),
            before + 1,
            "the top of a >=2-card unknown middle is a chance event: one RNG read"
        );
        assert!(
            p.draw.windows(2).all(|w| w[0] < w[1]),
            "the rest of the unknown middle stays canonical: {:?}",
            p.draw
        );
    }

    /// The bias the issue is about: the old raw `draw.remove(0)` always took
    /// the lowest uid. Every card of the unknown middle must be reachable.
    #[test]
    fn pop_top_card_reaches_every_card_of_the_unknown_middle() {
        let mut seen = std::collections::BTreeSet::new();
        for seed in 0..128i32 {
            let mut p = deferred_player_with_draw(&[10, 20, 30]);
            let mut rng = crate::dotnet_rng::Rng::new(seed);
            seen.insert(pop_top_card(&mut p, &mut rng).get());
        }
        assert_eq!(seen, std::collections::BTreeSet::from([10, 20, 30]));
    }

    #[test]
    fn pop_top_card_pinned_top_is_deterministic_and_consumes_its_pin() {
        let mut p = deferred_player_with_draw(&[3, 1, 2, 4]);
        pin_top(&mut p, uid(3));
        let mut rng = crate::dotnet_rng::Rng::new(7);
        let before = rng.counter();
        assert_eq!(pop_top_card(&mut p, &mut rng), uid(3));
        assert_eq!(rng.counter(), before, "a known top must not touch RNG");
        assert!(p.pinned_top.is_empty(), "the popped card's pin is consumed");
    }

    #[test]
    fn pop_top_card_false_flag_is_legacy_remove_front_plus_unpin() {
        let mut p = player_with_draw(&[5, 4, 3, 2, 1]);
        pin_top(&mut p, uid(5));
        let mut rng = crate::dotnet_rng::Rng::new(999);
        let before = rng.counter();
        assert_eq!(pop_top_card(&mut p, &mut rng), uid(5));
        assert_eq!(pop_top_card(&mut p, &mut rng), uid(4));
        assert_eq!(rng.counter(), before, "clairvoyant mode never touches RNG");
        assert_eq!(p.draw.as_slice(), &[uid(3), uid(2), uid(1)]);
        assert!(p.pinned_top.is_empty());
    }

    #[test]
    fn peek_top_card_if_false_flag_reads_front_without_mutating() {
        let mut p = player_with_draw(&[5, 4, 3]);
        let mut rng = crate::dotnet_rng::Rng::new(1);
        let before = rng.counter();
        assert_eq!(
            peek_top_card_if(&mut p, &mut rng, |u| u == uid(5)),
            Some(uid(5))
        );
        assert_eq!(peek_top_card_if(&mut p, &mut rng, |u| u == uid(4)), None);
        assert_eq!(rng.counter(), before);
        assert_eq!(p.draw.as_slice(), &[uid(5), uid(4), uid(3)]);
        assert!(p.pinned_top.is_empty());
    }

    #[test]
    fn peek_top_card_if_no_matching_candidate_reads_no_rng_and_pins_nothing() {
        let mut p = deferred_player_with_draw(&[1, 2, 3, 4]);
        let mut rng = crate::dotnet_rng::Rng::new(1);
        let before = rng.counter();
        assert_eq!(peek_top_card_if(&mut p, &mut rng, |u| u == uid(99)), None);
        assert_eq!(
            rng.counter(),
            before,
            "an answer that is the same for every possible top is no chance event"
        );
        assert!(p.pinned_top.is_empty());
        assert_eq!(p.draw.as_slice(), &[uid(1), uid(2), uid(3), uid(4)]);
    }

    /// A matching card in a >=2-card unknown middle makes the peek a chance
    /// event; the sampled card is pinned on top, so the pop that follows (a
    /// match) or the next draw (no match) takes that same card, RNG-free.
    #[test]
    fn peek_top_card_if_samples_pins_and_the_next_pop_agrees() {
        let mut outcomes = std::collections::BTreeSet::new();
        for seed in 0..128i32 {
            let mut p = deferred_player_with_draw(&[1, 2, 3]);
            let mut rng = crate::dotnet_rng::Rng::new(seed);
            let before = rng.counter();
            let peeked = peek_top_card_if(&mut p, &mut rng, |u| u == uid(2));
            assert_eq!(rng.counter(), before + 1, "seed {seed}: one RNG read");
            let top = p.draw[0];
            assert_eq!(p.pinned_top.as_slice(), &[top], "seed {seed}: top pinned");
            assert_eq!(peeked, (top == uid(2)).then_some(top));
            let after_peek = rng.counter();
            assert_eq!(pop_top_card(&mut p, &mut rng), top, "seed {seed}");
            assert_eq!(rng.counter(), after_peek, "seed {seed}: pop is RNG-free");
            outcomes.insert(peeked.is_some());
        }
        assert_eq!(
            outcomes,
            std::collections::BTreeSet::from([false, true]),
            "both outcomes of the peek must be reachable"
        );
    }

    #[test]
    fn peek_top_card_if_known_top_is_deterministic() {
        // Pinned top.
        let mut p = deferred_player_with_draw(&[3, 1, 2]);
        pin_top(&mut p, uid(3));
        let mut rng = crate::dotnet_rng::Rng::new(1);
        let before = rng.counter();
        assert_eq!(
            peek_top_card_if(&mut p, &mut rng, |u| u == uid(3)),
            Some(uid(3))
        );
        assert_eq!(peek_top_card_if(&mut p, &mut rng, |u| u == uid(1)), None);
        // Single-card unknown middle above a known bottom.
        let mut q = deferred_player_with_draw(&[1, 2]);
        pin_bottom(&mut q, uid(2));
        assert_eq!(
            peek_top_card_if(&mut q, &mut rng, |u| u == uid(1)),
            Some(uid(1))
        );
        assert_eq!(rng.counter(), before, "a known top must not touch RNG");
        assert!(
            q.pinned_top.is_empty(),
            "nothing to pin when the top is known"
        );
    }

    #[test]
    fn pop_first_card_matching_false_flag_is_position_then_remove() {
        let mut p = player_with_draw(&[5, 4, 3, 2]);
        let mut rng = crate::dotnet_rng::Rng::new(1);
        let before = rng.counter();
        let odd = |u: CardUid| u.get() % 2 == 1;
        assert_eq!(pop_first_card_matching(&mut p, &mut rng, odd), Some(uid(5)));
        assert_eq!(pop_first_card_matching(&mut p, &mut rng, odd), Some(uid(3)));
        assert_eq!(pop_first_card_matching(&mut p, &mut rng, odd), None);
        assert_eq!(rng.counter(), before);
        assert_eq!(p.draw.as_slice(), &[uid(4), uid(2)]);
    }

    #[test]
    fn pop_first_card_matching_walks_known_top_then_samples_the_middle() {
        let odd = |u: CardUid| u.get() % 2 == 1;
        // A matching pinned top is taken first, with no RNG read.
        let mut p = deferred_player_with_draw(&[7, 1, 2, 3]);
        pin_top(&mut p, uid(7));
        let mut rng = crate::dotnet_rng::Rng::new(1);
        let before = rng.counter();
        assert_eq!(pop_first_card_matching(&mut p, &mut rng, odd), Some(uid(7)));
        assert_eq!(rng.counter(), before);
        assert!(p.pinned_top.is_empty());

        // A non-matching pinned top is skipped; two matches in the middle
        // are a chance event, and both are reachable.
        let mut seen = std::collections::BTreeSet::new();
        for seed in 0..64i32 {
            let mut p = deferred_player_with_draw(&[8, 1, 2, 3]);
            pin_top(&mut p, uid(8));
            let mut rng = crate::dotnet_rng::Rng::new(seed);
            let before = rng.counter();
            let got = pop_first_card_matching(&mut p, &mut rng, odd).expect("a match");
            assert_eq!(rng.counter(), before + 1, "seed {seed}");
            assert_eq!(p.pinned_top.as_slice(), &[uid(8)], "the known top stays");
            assert_eq!(p.draw[0], uid(8));
            seen.insert(got.get());
        }
        assert_eq!(seen, std::collections::BTreeSet::from([1, 3]));

        // A single middle match is forced: no RNG read.
        let mut p = deferred_player_with_draw(&[1, 2, 4]);
        let mut rng = crate::dotnet_rng::Rng::new(1);
        let before = rng.counter();
        assert_eq!(pop_first_card_matching(&mut p, &mut rng, odd), Some(uid(1)));
        assert_eq!(rng.counter(), before);
    }

    #[test]
    fn pop_first_card_matching_falls_back_to_known_bottom_then_none() {
        let odd = |u: CardUid| u.get() % 2 == 1;
        let mut p = deferred_player_with_draw(&[2, 4, 3]);
        pin_bottom(&mut p, uid(3));
        let mut rng = crate::dotnet_rng::Rng::new(1);
        let before = rng.counter();
        assert_eq!(pop_first_card_matching(&mut p, &mut rng, odd), Some(uid(3)));
        assert!(
            p.pinned_bottom.is_empty(),
            "the taken card's pin is consumed"
        );
        assert_eq!(pop_first_card_matching(&mut p, &mut rng, odd), None);
        assert_eq!(rng.counter(), before);
        assert_eq!(p.draw.as_slice(), &[uid(2), uid(4)]);
    }

    /// GH #785 / #894: dropping a sampled miss restores the pile exactly as it
    /// was before the peek (canonical middle, no top pin, the known bottom
    /// untouched), so the misses of one peek are one state whatever card was
    /// sampled. A known pin, or a card that is not the pinned top, is left
    /// alone.
    #[test]
    fn drop_sampled_top_pin_restores_the_pre_peek_pile() {
        let mut dropped_states = std::collections::BTreeSet::new();
        let mut sampled = std::collections::BTreeSet::new();
        for seed in 0..64i32 {
            let mut p = deferred_player_with_draw(&[1, 2, 3, 4, 5]);
            pin_bottom(&mut p, uid(5));
            let before = p.clone();
            let mut rng = crate::dotnet_rng::Rng::new(seed);
            if peek_top_card_if(&mut p, &mut rng, |u| u == uid(2)).is_some() {
                continue;
            }
            let top = p.draw[0];
            assert_eq!(
                p.pinned_top.as_slice(),
                &[top],
                "seed {seed}: a sampled pin"
            );
            sampled.insert(top.get());
            drop_sampled_top_pin(&mut p, top);
            assert_eq!(p.draw, before.draw, "seed {seed}");
            assert_eq!(p.pinned_top, before.pinned_top, "seed {seed}");
            assert_eq!(p.pinned_bottom, before.pinned_bottom, "seed {seed}");
            dropped_states.insert(format!("{:?}", (&p.draw, &p.pinned_top, &p.pinned_bottom)));
        }
        assert!(
            sampled.len() >= 2,
            "fixture: several hidden tops were sampled: {sampled:?}"
        );
        assert_eq!(dropped_states.len(), 1, "every miss drops to one pile");

        // A known pin is not a sampled one: nothing happens.
        let mut p = deferred_player_with_draw(&[3, 1, 2]);
        pin_top(&mut p, uid(3));
        let known = p.clone();
        drop_sampled_top_pin(&mut p, uid(1));
        assert_eq!(p, known, "uid 1 is not the pinned top");
        // ... and the clairvoyant pile is never touched.
        let mut q = player_with_draw(&[3, 1, 2]);
        pin_top(&mut q, uid(3));
        let clair = q.clone();
        drop_sampled_top_pin(&mut q, uid(3));
        assert_eq!(q, clair, "flag clear: no-op");
    }

    /// The peek samples its top from the unknown MIDDLE only: a known-bottom
    /// card that satisfies `pred` sits below the whole middle, so it can
    /// never be "the top". A sample range that spilled into the bottom stack
    /// would hoist it onto the top and re-pin it there.
    #[test]
    fn peek_top_card_if_never_samples_the_known_bottom() {
        let mut outcomes = std::collections::BTreeSet::new();
        for seed in 0..64i32 {
            let mut p = deferred_player_with_draw(&[1, 2, 3]);
            pin_bottom(&mut p, uid(3));
            let mut rng = crate::dotnet_rng::Rng::new(seed);
            let before = rng.counter();
            let peeked = peek_top_card_if(&mut p, &mut rng, |u| u == uid(2) || u == uid(3));
            assert_eq!(rng.counter(), before + 1, "seed {seed}: one RNG read");
            assert_ne!(
                peeked,
                Some(uid(3)),
                "seed {seed}: the bottom card is not on top"
            );
            assert_ne!(p.draw[0], uid(3), "seed {seed}");
            assert_eq!(
                p.draw.last(),
                Some(&uid(3)),
                "seed {seed}: bottom stays put"
            );
            assert_eq!(p.pinned_bottom.as_slice(), &[uid(3)], "seed {seed}");
            assert!(!p.pinned_top.contains(&uid(3)), "seed {seed}");
            outcomes.insert(peeked.map(CardUid::get));
        }
        assert_eq!(
            outcomes,
            std::collections::BTreeSet::from([None, Some(2)]),
            "both middle cards are reachable as the top"
        );
    }

    /// "First match from the top" walks the unknown middle before the
    /// known-bottom stack: with exactly one middle match it is forced (no
    /// RNG read), whatever matches further down in the bottom stack.
    #[test]
    fn pop_first_card_matching_takes_the_single_middle_match_before_the_known_bottom() {
        for seed in 0..64i32 {
            let mut p = deferred_player_with_draw(&[1, 2, 3]);
            pin_bottom(&mut p, uid(3));
            let mut rng = crate::dotnet_rng::Rng::new(seed);
            let before = rng.counter();
            let got = pop_first_card_matching(&mut p, &mut rng, |u| u == uid(1) || u == uid(3));
            assert_eq!(got, Some(uid(1)), "seed {seed}");
            assert_eq!(
                rng.counter(),
                before,
                "seed {seed}: a forced pick reads no RNG"
            );
            assert_eq!(p.draw.as_slice(), &[uid(2), uid(3)], "seed {seed}");
            assert_eq!(p.pinned_bottom.as_slice(), &[uid(3)], "seed {seed}");
        }
    }

    #[test]
    fn shuffle_sorts_instead_of_shuffling_under_deferred_flag() {
        let mut p = deferred_player_with_draw(&[5, 3, 1, 4, 2]);
        let mut rng = crate::dotnet_rng::Rng::new(0x00C0_FFEE);
        let before = rng.counter();
        shuffle(&mut p, &mut rng);
        assert_eq!(
            p.draw.as_slice(),
            &[uid(1), uid(2), uid(3), uid(4), uid(5)],
            "a deferred-order pile must canonicalize (sort) instead of shuffling"
        );
        assert_eq!(
            rng.counter(),
            before,
            "order-dissolving mutations under BeliefDraw must consume no RNG"
        );
    }

    #[test]
    fn shuffle_sorts_preserving_pins_under_deferred_flag() {
        let mut p = deferred_player_with_draw(&[5, 3, 1, 4, 2]);
        pin_top(&mut p, uid(5));
        pin_bottom(&mut p, uid(2));
        let mut rng = crate::dotnet_rng::Rng::new(0xBEEF);
        shuffle(&mut p, &mut rng);
        assert_eq!(p.pinned_top.as_slice(), &[uid(5)]);
        assert_eq!(p.pinned_bottom.as_slice(), &[uid(2)]);
        assert_eq!(p.draw.as_slice(), &[uid(5), uid(1), uid(3), uid(4), uid(2)]);
    }

    #[test]
    fn auto_reshuffle_sorts_and_consumes_no_shuffle_rng_under_deferred_flag() {
        let mut p = PlayerCombatState {
            discard: [5u32, 3, 1, 4, 2].into_iter().map(uid).collect(),
            deferred_draw_order: true,
            ..PlayerCombatState::default()
        };
        let cards: CardStore = (1..=5).map(sample_card).collect();
        let mut rng = crate::dotnet_rng::Rng::new(0xABCD);
        let before = rng.counter();
        let shuffled = discard_pile_into_draw_pile_signaling(&mut p, &cards, &mut rng);
        assert!(shuffled, "non-empty discard into empty draw must reshuffle");
        assert!(p.discard.is_empty());
        assert_eq!(
            p.draw.as_slice(),
            &[uid(1), uid(2), uid(3), uid(4), uid(5)],
            "the auto-reshuffle must land the deferred pile in canonical (sorted) order"
        );
        assert_eq!(
            rng.counter(),
            before,
            "the auto-reshuffle must consume NO shuffle-stream RNG under BeliefDraw"
        );
    }

    #[test]
    fn insert_into_unknown_sorted_preserves_sortedness_no_rng() {
        let mut p = deferred_player_with_draw(&[1, 2, 4, 5]);
        insert_into_unknown_sorted(&mut p, uid(3));
        assert_eq!(
            p.draw.as_slice(),
            &[uid(1), uid(2), uid(3), uid(4), uid(5)],
            "insert must land the new uid at its sorted slot"
        );
    }

    #[test]
    fn insert_into_unknown_sorted_respects_pins() {
        let mut p = deferred_player_with_draw(&[5, 2, 4, 1]);
        pin_top(&mut p, uid(5));
        pin_bottom(&mut p, uid(1));
        insert_into_unknown_sorted(&mut p, uid(3));
        assert_eq!(p.pinned_top.as_slice(), &[uid(5)]);
        assert_eq!(p.pinned_bottom.as_slice(), &[uid(1)]);
        assert_eq!(
            p.draw.as_slice(),
            &[uid(5), uid(2), uid(3), uid(4), uid(1)],
            "the new uid must land sorted WITHIN the unpinned middle, pins untouched"
        );
    }

    /// Stale-pin resurrection guard (bead `sts2-rs-09x5n` re-review): a
    /// pinned card removed from draw WITHOUT an `unpin` (a raw
    /// `draw.remove(..)`, as the Havoc/Cascade top pop was before GH #785)
    /// must NOT be re-inserted by a later
    /// `insert_into_unknown_sorted` rebuild — that would duplicate the
    /// card across draw AND play/exhaust. The function must retain-sweep
    /// the pin lists against the actual pile first, exactly like
    /// `canonicalize_unknown_middle` / legacy `shuffle` do.
    #[test]
    fn insert_into_unknown_sorted_drops_stale_pins_no_resurrection() {
        let mut p = deferred_player_with_draw(&[5, 2, 4, 1]);
        pin_top(&mut p, uid(5));
        pin_bottom(&mut p, uid(1));
        // Simulate the Havoc pop: the pinned top leaves draw with NO unpin.
        let popped = p.draw.remove(0);
        assert_eq!(popped, uid(5));
        p.play.push(popped);
        assert!(
            p.pinned_top.contains(&uid(5)),
            "precondition: the pin entry is stale (card gone from draw, pin not swept)"
        );

        insert_into_unknown_sorted(&mut p, uid(3));

        // No resurrection: uid(5) lives ONLY in play, not back in draw.
        assert!(
            !p.draw.contains(&uid(5)),
            "stale-pinned card must NOT be resurrected into draw: {:?}",
            p.draw
        );
        assert_eq!(p.play.as_slice(), &[uid(5)]);
        // Card count conserved: 3 pre-existing draw cards + the inserted one.
        assert_eq!(p.draw.len(), 4);
        // Stale pin swept; live bottom pin intact.
        assert!(p.pinned_top.is_empty(), "stale top pin must be swept");
        assert_eq!(p.pinned_bottom.as_slice(), &[uid(1)]);
        // Layout valid: middle sorted, live bottom pin last.
        assert_eq!(
            p.draw.as_slice(),
            &[uid(2), uid(3), uid(4), uid(1)],
            "middle sorted with the insert in place, pinned bottom last"
        );
        // And pop_next_card drains the result without panicking, bottom last.
        let mut rng = crate::dotnet_rng::Rng::new(7);
        let mut drawn = Vec::new();
        for _ in 0..4 {
            let u = pop_next_card(&mut p, &mut rng);
            unpin(&mut p, u);
            drawn.push(u);
        }
        assert!(p.draw.is_empty());
        assert_eq!(drawn.last().copied(), Some(uid(1)));
    }

    #[test]
    fn enchantment_wire_name_tolerates_an_unresolved_loc_key() {
        // The producer's loc lookup returns the raw key when the English
        // data lacks the entry (`enchantments/INKY.title` in v0.107.1).
        assert_eq!(
            EnchantmentId::from_wire_name("INKY.title"),
            Some(EnchantmentId::Inky)
        );
        // The three established dialects keep resolving.
        assert_eq!(
            EnchantmentId::from_wire_name("Soul's Power"),
            Some(EnchantmentId::SoulsPower)
        );
        assert_eq!(
            EnchantmentId::from_wire_name("SOULS_POWER"),
            Some(EnchantmentId::SoulsPower)
        );
        assert_eq!(
            EnchantmentId::from_wire_name("Nimble"),
            Some(EnchantmentId::Nimble)
        );
        assert_eq!(EnchantmentId::from_wire_name("NoSuchThing.title"), None);
    }

    // -----------------------------------------------------------------
    // J02: CardStore gate-id presence bits
    // -----------------------------------------------------------------

    const GATE_IDS: [CardId; 5] = [
        CardId::Stomp,
        CardId::Pinpoint,
        CardId::Melancholy,
        CardId::Bolas,
        CardId::ThrummingHatchet,
    ];

    /// `holds_id` answers the arena scan for every gate id.
    fn assert_holds_match_scan(store: &CardStore) {
        for id in GATE_IDS {
            assert_eq!(
                store.holds_id(id),
                store.iter().any(|c| c.card_id == id),
                "{id:?}"
            );
        }
    }

    /// Every structural writer keeps the bits: `push`, `From<Vec>`, `collect`,
    /// `extend`, `truncate`, `clear`.
    #[test]
    fn card_store_gate_bits_follow_every_structural_write() {
        let mut store = CardStore::new();
        assert_holds_match_scan(&store);
        for (i, id) in [CardId::StrikeIronclad, CardId::Stomp, CardId::Bolas]
            .into_iter()
            .enumerate()
        {
            store.push(Card {
                uid: uid(u32::try_from(i + 1).expect("fits")),
                card_id: id,
                ..Card::pod_defaults()
            });
            assert_holds_match_scan(&store);
        }
        assert!(store.holds_id(CardId::Stomp) && store.holds_id(CardId::Bolas));
        assert!(!store.holds_id(CardId::Pinpoint));

        let collected = store_with_ids(&[CardId::Melancholy, CardId::DefendIronclad]);
        assert_holds_match_scan(&collected);
        assert!(collected.holds_id(CardId::Melancholy));

        let from_vec = CardStore::from(collected.clone().into_vec());
        assert_holds_match_scan(&from_vec);

        store.extend(collected.iter().copied());
        assert_holds_match_scan(&store);
        assert!(store.holds_id(CardId::Melancholy));

        store.truncate(2);
        assert_holds_match_scan(&store);
        assert!(
            !store.holds_id(CardId::Bolas),
            "truncate drops the Bolas row"
        );

        store.clear();
        assert_holds_match_scan(&store);
        assert!(store.is_empty());
        #[cfg(debug_assertions)]
        store.debug_assert_gate_bits();
    }

    /// The bits are derived: equality and the printed form are the old
    /// `Vec<Card>`'s.
    #[test]
    fn card_store_eq_and_debug_are_the_vec_ones() {
        let cards = vec![sample_card(1), sample_card(2)];
        let store = CardStore::from(cards.clone());
        assert_eq!(format!("{store:?}"), format!("{cards:?}"));
        assert_eq!(format!("{store:#?}"), format!("{cards:#?}"));
        let mut pushed = CardStore::new();
        for c in &cards {
            pushed.push(*c);
        }
        assert_eq!(store, pushed);
        assert_ne!(store, CardStore::from(vec![sample_card(1)]));
    }

    /// `card_id` is a public field, so `&mut [Card]` can rewrite it in place;
    /// the debug drift guard (run at every `apply` entry) catches a rewrite
    /// TO a gate id that the bits would otherwise miss.
    #[cfg(debug_assertions)]
    #[test]
    #[should_panic(expected = "gate bits drifted")]
    fn card_store_drift_guard_catches_an_in_place_card_id_write() {
        let mut store = store_with_ids(&[CardId::StrikeIronclad]);
        store[0].card_id = CardId::Stomp;
        store.debug_assert_gate_bits();
    }

    /// `holds_id` cross-checks the scan in debug builds, so a stale bit
    /// can never silently close a gate there.
    #[cfg(debug_assertions)]
    #[test]
    #[should_panic(expected = "disagrees with the arena scan")]
    fn card_store_holds_id_cross_checks_the_scan_in_debug() {
        let mut store = store_with_ids(&[CardId::StrikeIronclad]);
        store[0].card_id = CardId::Pinpoint;
        let _ = store.holds_id(CardId::Pinpoint);
    }

    /// C# `CardModel.DowngradeInternal` (`CardModel.cs:2149-2162`, same in
    /// v0.107.1) resets `_keywords` to the canonical Local set, dropping an
    /// Ethereal that `CardCmd.ApplyKeyword` added (Ghost Seed, a Music Box
    /// clone). Dampen's downgrade must clear `EtherealThisCombat`, or the
    /// end-of-turn sweep exhausts the card (Ironclad:6190 @1049).
    #[test]
    fn downgrade_drops_applied_ethereal() {
        let mut card = Card {
            card_id: CardId::StrikeIronclad,
            upgraded: true,
            ..Card::pod_defaults()
        };
        card.set_combat_var(VarKey::EtherealThisCombat, 1);
        card.set_combat_var(VarKey::DampenDowngradedMarker, 1);
        assert!(card.downgrade_for(crate::GameVersion::V0_111_0));
        assert_eq!(card.combat_var(VarKey::EtherealThisCombat), 0);
        assert_eq!(
            card.combat_var(VarKey::DampenDowngradedMarker),
            1,
            "other instance state survives"
        );
    }

    /// C# `ResetForDowngrade` restores the base cost (9) under Banshee's Cry's
    /// `AddThisCombat(-2)` modifiers, so after 5 Ethereal plays a downgraded
    /// copy resolves to `max(0, 9 - 10) = 0`, not the floored 0 plus the
    /// reverted +2 (loadout Necrobinder 1006), and after 4 to `9 - 8 = 1`
    /// with no debt left over (loadout Necrobinder 5439, v0.107.1: the stale
    /// debt read the cost as 0).
    #[test]
    fn banshees_cry_downgrade_keeps_its_ethereal_discounts() {
        let factory = |id, up: bool| {
            Some(Card {
                card_id: id,
                cost: if up { 7 } else { 9 },
                ..Card::pod_defaults()
            })
        };
        let shaved = |plays: i32| {
            let mut card = Card {
                card_id: CardId::BansheesCry,
                cost: 7,
                upgraded: true,
                ..Card::pod_defaults()
            };
            for _ in 0..plays {
                card.add_cost_this_combat(-2);
            }
            card.set_combat_var(VarKey::BansheesCryEtherealCounted, plays);
            card
        };
        let mut card = shaved(5);
        assert!(card.downgrade_with(factory));
        assert_eq!(card.cost, 0);
        assert_eq!(card.combat_var(VarKey::CostDebtThisCombat), 1, "9 - 10");

        let mut card = shaved(4);
        assert!(card.downgrade_with(factory));
        assert_eq!(card.cost, 1, "max(0, 9 - 8)");
        assert_eq!(card.combat_var(VarKey::CostDebtThisCombat), 0);

        // The upgrade shifts the same unclamped sum: 9 - 8 = 1, upgraded
        // 7 - 8 = -1 shows 0, and the downgrade brings back 1.
        assert!(card.upgrade_with(factory));
        assert_eq!(
            (card.cost, card.combat_var(VarKey::CostDebtThisCombat)),
            (0, 1)
        );
        assert!(card.downgrade_with(factory));
        assert_eq!(card.cost, 1);
    }

    /// GH #1150: Enlightenment+'s reduce-only cap over a live Snecko roll AND
    /// a later `AddUntilPlayed(-1)`. C# folds `[roll 2, -1, cap 2]`: shown
    /// `min(1, 2) = 1`; after the roll expires `[-1, cap 2]` on the 3-base,
    /// `min(2, 2) = 2`; after the play `[cap 2]`, `min(3, 2) = 2`.
    #[test]
    fn enlightenment_cap_over_a_snecko_roll_keeps_the_until_played_reduction() {
        let mut card = Card {
            cost: 3,
            ..Card::pod_defaults()
        };
        // Snecko roll 3 -> 2 (what `snecko_randomize_hand_costs` banks).
        card.cost = 2;
        card.set_combat_var(VarKey::SneckoCostDeltaThisTurn, -1);
        card.set_combat_var(VarKey::SneckoRollLive, SNECKO_ROLL_RAISED_FLAG);
        card.set_combat_var(VarKey::CostAbsolutelySet, 1);
        card.add_cost_reduction_until_played(1);
        let shown = |c: &Card| i32::from(c.cost) - c.combat_var(VarKey::CostReductionUntilPlayed);
        assert_eq!(shown(&card), 1);

        card.set_this_combat_reduce_only(2);
        assert_eq!(shown(&card), 1, "min(1, 2)");

        let mut end_of_turn = card;
        end_of_turn.expire_snecko_roll();
        assert_eq!(
            shown(&end_of_turn),
            2,
            "min(3 - 1, 2) once the roll expires"
        );

        let mut played = card;
        played.expire_snecko_roll();
        played.combat_vars.zero(VarKey::CostReductionUntilPlayed);
        assert_eq!(shown(&played), 2, "min(3, 2) once played");
    }
}
